        VALUES
          ('SH0214', 1, U&'\0E23\0E49\0E2D\0E22\0E25\0E30\0E04\0E27\0E32\0E21\0E1E\0E36\0E07\0E1E\0E2D\0E43\0E08\0E02\0E2D\0E07\0E1A\0E38\0E04\0E25\0E32\0E01\0E23\0E43\0E19\0E2D\0E07\0E04\0E4C\0E01\0E23\0E43\0E19\0E20\0E32\0E1E\0E23\0E27\0E21\0E02\0E2D\0E07\0E1A\0E38\0E04\0E25\0E32\0E01\0E23\0E2A\0E32\0E22\0E2A\0E19\0E31\0E1A\0E2A\0E19\0E38\0E19\0020\0028\0E23\0E30\0E14\0E31\0E1A\0020\0031\002D\0032\0029', 'HRD: Percentage of back office personel satisfaction (level 1-2)')
      ), fiscal_periods AS (
        SELECT
          generated.period_start::date AS period_start,
