            WHERE fv.hn = opd_periodized.hn
              AND fv.vstdate >= opd_periodized.event_date + INTERVAL '180 days'
              AND fv.vstdate <= opd_periodized.event_date + INTERVAL '270 days'
              AND COALESCE(fs.smoking_type_id, 0) NOT IN (2, 3)
          )
          AND NOT EXISTS (
            SELECT 1
            FROM ovst rv
            JOIN opdscreen rs ON rs.vn = rv.vn
            WHERE rv.hn = opd_periodized.hn
              AND rv.vstdate > opd_periodized.event_date
              AND rv.vstdate <= opd_periodized.event_date + INTERVAL '270 days'
              AND rs.smoking_type_id IN (2, 3)
          )
        )) AS numerator,
            COUNT(DISTINCT opd_periodized.hn) FILTER (WHERE (
          EXISTS (
            SELECT 1
            FROM ovstdiag sd
            WHERE sd.vn = opd_periodized.vn
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') = 'Z716'
          )
          OR EXISTS (
              SELECT 1
              FROM iptdiag idg
              WHERE idg.an = opd_periodized.an
                AND REPLACE(UPPER(TRIM(idg.icd10)), '.', '') = 'Z716'
            )
          OR EXISTS (
            SELECT 1
            FROM opdscreen scr
            WHERE scr.vn = opd_periodized.vn
              AND (
                scr.advice1 = 'Y' OR scr.advice2 = 'Y' OR scr.advice3 = 'Y'
                OR scr.advice4 = 'Y' OR scr.advice5 = 'Y' OR scr.advice6 = 'Y'
                OR scr.advice7 = 'Y' OR scr.advice8 = 'Y'
                OR scr.advice7_note ILIKE '%smoke%'
                OR scr.advice7_note ILIKE U&'%\0E2A\0E39\0E1A%'
              )
          )
          OR EXISTS (
            SELECT 1
            FROM opitemrece oi
            JOIN drugitems di ON di.icode = oi.icode
            WHERE oi.vn = opd_periodized.vn
              AND (
                di.name ILIKE '%bupropion%'
                OR di.name ILIKE '%varenicline%'
                OR di.name ILIKE '%nicotine%'
              )
          )
        )) AS denominator,
            ROUND((COUNT(DISTINCT opd_periodized.hn) FILTER (WHERE (
          EXISTS (
            SELECT 1
            FROM ovstdiag sd
            WHERE sd.vn = opd_periodized.vn
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') = 'Z716'
          )
          OR EXISTS (
              SELECT 1
              FROM iptdiag idg
              WHERE idg.an = opd_periodized.an
                AND REPLACE(UPPER(TRIM(idg.icd10)), '.', '') = 'Z716'
            )
          OR EXISTS (
            SELECT 1
            FROM opdscreen scr
            WHERE scr.vn = opd_periodized.vn
              AND (
                scr.advice1 = 'Y' OR scr.advice2 = 'Y' OR scr.advice3 = 'Y'
                OR scr.advice4 = 'Y' OR scr.advice5 = 'Y' OR scr.advice6 = 'Y'
                OR scr.advice7 = 'Y' OR scr.advice8 = 'Y'
                OR scr.advice7_note ILIKE '%smoke%'
                OR scr.advice7_note ILIKE U&'%\0E2A\0E39\0E1A%'
              )
          )
          OR EXISTS (
            SELECT 1
            FROM opitemrece oi
            JOIN drugitems di ON di.icode = oi.icode
            WHERE oi.vn = opd_periodized.vn
              AND (
                di.name ILIKE '%bupropion%'
                OR di.name ILIKE '%varenicline%'
                OR di.name ILIKE '%nicotine%'
              )
          )
        ) AND (
          EXISTS (
            SELECT 1
            FROM ovst fv
            JOIN opdscreen fs ON fs.vn = fv.vn
            WHERE fv.hn = opd_periodized.hn
              AND fv.vstdate >= opd_periodized.event_date + INTERVAL '180 days'
              AND fv.vstdate <= opd_periodized.event_date + INTERVAL '270 days'
              AND COALESCE(fs.smoking_type_id, 0) NOT IN (2, 3)
          )
          AND NOT EXISTS (
            SELECT 1
            FROM ovst rv
            JOIN opdscreen rs ON rs.vn = rv.vn
            WHERE rv.hn = opd_periodized.hn
              AND rv.vstdate > opd_periodized.event_date
              AND rv.vstdate <= opd_periodized.event_date + INTERVAL '270 days'
              AND rs.smoking_type_id IN (2, 3)
          )
        )) * 100.0) / NULLIF(COUNT(DISTINCT opd_periodized.hn) FILTER (WHERE (
          EXISTS (
            SELECT 1
            FROM ovstdiag sd
            WHERE sd.vn = opd_periodized.vn
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') = 'Z716'
          )
          OR EXISTS (
              SELECT 1
              FROM iptdiag idg
              WHERE idg.an = opd_periodized.an
                AND REPLACE(UPPER(TRIM(idg.icd10)), '.', '') = 'Z716'
            )
          OR EXISTS (
            SELECT 1
            FROM opdscreen scr
            WHERE scr.vn = opd_periodized.vn
              AND (
                scr.advice1 = 'Y' OR scr.advice2 = 'Y' OR scr.advice3 = 'Y'
                OR scr.advice4 = 'Y' OR scr.advice5 = 'Y' OR scr.advice6 = 'Y'
                OR scr.advice7 = 'Y' OR scr.advice8 = 'Y'
                OR scr.advice7_note ILIKE '%smoke%'
                OR scr.advice7_note ILIKE U&'%\0E2A\0E39\0E1A%'
              )
          )
          OR EXISTS (
            SELECT 1
            FROM opitemrece oi
            JOIN drugitems di ON di.icode = oi.icode
            WHERE oi.vn = opd_periodized.vn
              AND (
                di.name ILIKE '%bupropion%'
                OR di.name ILIKE '%varenicline%'
                OR di.name ILIKE '%nicotine%'
              )
          )
        )), 0), 2) AS value
          FROM opd_periodized
          WHERE opd_periodized.age_y >= 15 AND (
          LEFT(pdx, 3) = 'F17'
          OR pdx = 'Z720'
          OR EXISTS (
            SELECT 1
            FROM ovstdiag sd
            WHERE sd.vn = opd_periodized.vn
              AND (
                LEFT(REPLACE(UPPER(TRIM(sd.icd10)), '.', ''), 3) = 'F17'
                OR REPLACE(UPPER(TRIM(sd.icd10)), '.', '') = 'Z720'
              )
          )
          OR EXISTS (
              SELECT 1
              FROM iptdiag idg
              WHERE idg.an = opd_periodized.an
                AND (
                  LEFT(REPLACE(UPPER(TRIM(idg.icd10)), '.', ''), 3) = 'F17'
                  OR REPLACE(UPPER(TRIM(idg.icd10)), '.', '') = 'Z720'
                )
            )
        ) AND (
          EXISTS (
            SELECT 1
            FROM ovstdiag sd
            JOIN ovst v ON v.vn = sd.vn
            WHERE v.hn = opd_periodized.hn
              AND v.vstdate >= (SELECT fy_start FROM thip_params)
              AND v.vstdate < (SELECT fy_end FROM thip_params)
              AND LEFT(REPLACE(UPPER(TRIM(sd.icd10)), '.', ''), 3) IN ('I10', 'I11', 'I12', 'I13', 'I14', 'I15')
          )
          OR EXISTS (
            SELECT 1
            FROM iptdiag idg
            JOIN ipt i ON i.an = idg.an
            WHERE i.hn = opd_periodized.hn
              AND i.dchdate >= (SELECT fy_start FROM thip_params)
              AND i.dchdate < (SELECT fy_end FROM thip_params)
              AND LEFT(REPLACE(UPPER(TRIM(idg.icd10)), '.', ''), 3) IN ('I10', 'I11', 'I12', 'I13', 'I14', 'I15')
          )
        )
          GROUP BY 2, 3, 4
          ), expected_codes(indicator_code, fiscal_month, indicator_name_th, indicator_name_en) AS (
            VALUES
              ('HH0104.2', 1, U&'\0E23\0E49\0E2D\0E22\0E25\0E30\0E02\0E2D\0E07\0E1C\0E39\0E49\0E1B\0E48\0E27\0E22\0E01\0E25\0E38\0E48\0E21\0E42\0E23\0E04\0E04\0E27\0E32\0E21\0E14\0E31\0E19\0E42\0E25\0E2B\0E34\0E15\0E2A\0E39\0E07\0E17\0E35\0E48\0E23\0E31\0E1A\0E1A\0E23\0E34\0E01\0E32\0E23\0E1A\0E33\0E1A\0E31\0E14\0E23\0E31\0E01\0E29\0E32\0E20\0E32\0E27\0E30\0E15\0E34\0E14\0E19\0E34\0E42\0E04\0E15\0E34\0E19\0E41\0E25\0E30\0020\0E2A\0E32\0E21\0E32\0E23\0E16\0E2B\0E22\0E38\0E14\0E1A\0E23\0E34\0E42\0E20\0E04\0E22\0E32\0E2A\0E39\0E1A\0E15\0E48\0E2D\0E40\0E19\0E37\0E48\0E2D\0E07\0020\0036\0020\0E40\0E14\0E37\0E2D\0E19', 'Tobacco use: continuous abstinence rate (CAR) at 6 months (Hypertension Patients)')
          ), fiscal_periods AS (
            SELECT
              generated.period_start::date AS period_start,
              CASE
                WHEN EXTRACT(MONTH FROM generated.period_start) >= 10
                  THEN EXTRACT(MONTH FROM generated.period_start)::integer - 9
                ELSE EXTRACT(MONTH FROM generated.period_start)::integer + 3
              END AS fiscal_month,
              CASE
                WHEN EXTRACT(MONTH FROM generated.period_start) >= 10
                  THEN EXTRACT(YEAR FROM generated.period_start)::integer + 1
                ELSE EXTRACT(YEAR FROM generated.period_start)::integer
              END AS fiscal_year
            FROM generate_series(
              CAST((SELECT fy_start FROM thip_params) AS date),
              CAST((SELECT fy_end FROM thip_params) AS date) - INTERVAL '1 month',
              INTERVAL '1 month'
            ) AS generated(period_start)
          )
          SELECT
            expected_codes.indicator_code,
            expected_codes.indicator_name_th AS indicator_name_th,
            expected_codes.indicator_name_en AS indicator_name_en,
            fiscal_periods.period_start,
            fiscal_periods.fiscal_month,
            fiscal_periods.fiscal_year,
            COALESCE(facts.numerator, 0) AS numerator,
            COALESCE(facts.denominator, 0) AS denominator,
            facts.value
          FROM expected_codes
          JOIN fiscal_periods
            ON fiscal_periods.fiscal_month = expected_codes.fiscal_month
          LEFT JOIN facts
            ON facts.indicator_code = expected_codes.indicator_code
           AND facts.period_start = fiscal_periods.period_start
           AND facts.fiscal_month = fiscal_periods.fiscal_month
           AND facts.fiscal_year = fiscal_periods.fiscal_year
          ORDER BY expected_codes.indicator_code, fiscal_periods.period_start
  ) AS b_HH0104_2
  UNION ALL
  SELECT * FROM (
    WITH
          ipd AS (
        SELECT
          i.an,
          i.hn,
          i.regdate,
          i.regtime,
          i.dchdate,
          COALESCE(i.bw, 0) AS bw,
          s.age_y,
          s.los,
          REPLACE(UPPER(TRIM(s.pdx)), '.', '') AS pdx,
          EXISTS (
