        )) AS numerator,
            COUNT(DISTINCT opd_periodized.hn) FILTER (WHERE (
          EXISTS (
            SELECT 1
            FROM ovstdiag sd
            WHERE sd.vn = opd_periodized.vn
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') = 'Z716'
          )
          OR EXISTS (
              SELECT 1
              FROM iptdiag idg
              WHERE idg.an = opd_periodized.an
                AND REPLACE(UPPER(TRIM(idg.icd10)), '.', '') = 'Z716'
            )
          OR EXISTS (
            SELECT 1
            FROM opdscreen scr
            WHERE scr.vn = opd_periodized.vn
              AND (
                scr.advice1 = 'Y' OR scr.advice2 = 'Y' OR scr.advice3 = 'Y'
                OR scr.advice4 = 'Y' OR scr.advice5 = 'Y' OR scr.advice6 = 'Y'
                OR scr.advice7 = 'Y' OR scr.advice8 = 'Y'
                OR scr.advice7_note ILIKE '%smoke%'
                OR scr.advice7_note ILIKE U&'%\0E2A\0E39\0E1A%'
              )
          )
          OR EXISTS (
            SELECT 1
            FROM opitemrece oi
            JOIN drugitems di ON di.icode = oi.icode
            WHERE oi.vn = opd_periodized.vn
              AND (
                di.name ILIKE '%bupropion%'
                OR di.name ILIKE '%varenicline%'
                OR di.name ILIKE '%nicotine%'
              )
          )
        )) AS denominator,
            ROUND((COUNT(DISTINCT opd_periodized.hn) FILTER (WHERE (
          EXISTS (
            SELECT 1
            FROM ovstdiag sd
            WHERE sd.vn = opd_periodized.vn
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') = 'Z716'
          )
          OR EXISTS (
              SELECT 1
              FROM iptdiag idg
              WHERE idg.an = opd_periodized.an
                AND REPLACE(UPPER(TRIM(idg.icd10)), '.', '') = 'Z716'
            )
          OR EXISTS (
            SELECT 1
            FROM opdscreen scr
            WHERE scr.vn = opd_periodized.vn
              AND (
                scr.advice1 = 'Y' OR scr.advice2 = 'Y' OR scr.advice3 = 'Y'
                OR scr.advice4 = 'Y' OR scr.advice5 = 'Y' OR scr.advice6 = 'Y'
                OR scr.advice7 = 'Y' OR scr.advice8 = 'Y'
                OR scr.advice7_note ILIKE '%smoke%'
                OR scr.advice7_note ILIKE U&'%\0E2A\0E39\0E1A%'
              )
          )
          OR EXISTS (
            SELECT 1
            FROM opitemrece oi
            JOIN drugitems di ON di.icode = oi.icode
            WHERE oi.vn = opd_periodized.vn
              AND (
                di.name ILIKE '%bupropion%'
                OR di.name ILIKE '%varenicline%'
                OR di.name ILIKE '%nicotine%'
              )
          )
        ) AND (
          EXISTS (
            SELECT 1
            FROM ovst fv
            JOIN opdscreen fs ON fs.vn = fv.vn
            WHERE fv.hn = opd_periodized.hn
              AND fv.vstdate >= opd_periodized.event_date + INTERVAL '180 days'
              AND fv.vstdate <= opd_periodized.event_date + INTERVAL '270 days'
              AND COALESCE(fs.smoking_type_id, 0) NOT IN (2, 3)
          )
          AND NOT EXISTS (
            SELECT 1
            FROM ovst rv
            JOIN opdscreen rs ON rs.vn = rv.vn
            WHERE rv.hn = opd_periodized.hn
              AND rv.vstdate > opd_periodized.event_date
              AND rv.vstdate <= opd_periodized.event_date + INTERVAL '270 days'
              AND rs.smoking_type_id IN (2, 3)
          )
        )) * 100.0) / NULLIF(COUNT(DISTINCT opd_periodized.hn) FILTER (WHERE (
          EXISTS (
            SELECT 1
            FROM ovstdiag sd
            WHERE sd.vn = opd_periodized.vn
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') = 'Z716'
          )
          OR EXISTS (
              SELECT 1
              FROM iptdiag idg
              WHERE idg.an = opd_periodized.an
                AND REPLACE(UPPER(TRIM(idg.icd10)), '.', '') = 'Z716'
            )
          OR EXISTS (
            SELECT 1
            FROM opdscreen scr
            WHERE scr.vn = opd_periodized.vn
              AND (
                scr.advice1 = 'Y' OR scr.advice2 = 'Y' OR scr.advice3 = 'Y'
                OR scr.advice4 = 'Y' OR scr.advice5 = 'Y' OR scr.advice6 = 'Y'
                OR scr.advice7 = 'Y' OR scr.advice8 = 'Y'
                OR scr.advice7_note ILIKE '%smoke%'
                OR scr.advice7_note ILIKE U&'%\0E2A\0E39\0E1A%'
              )
          )
          OR EXISTS (
            SELECT 1
            FROM opitemrece oi
            JOIN drugitems di ON di.icode = oi.icode
            WHERE oi.vn = opd_periodized.vn
              AND (
                di.name ILIKE '%bupropion%'
                OR di.name ILIKE '%varenicline%'
                OR di.name ILIKE '%nicotine%'
              )
          )
        )), 0), 2) AS value
          FROM opd_periodized
          WHERE opd_periodized.age_y >= 15 AND (
          LEFT(pdx, 3) = 'F17'
          OR pdx = 'Z720'
          OR EXISTS (
            SELECT 1
            FROM ovstdiag sd
            WHERE sd.vn = opd_periodized.vn
              AND (
                LEFT(REPLACE(UPPER(TRIM(sd.icd10)), '.', ''), 3) = 'F17'
                OR REPLACE(UPPER(TRIM(sd.icd10)), '.', '') = 'Z720'
              )
          )
          OR EXISTS (
              SELECT 1
              FROM iptdiag idg
              WHERE idg.an = opd_periodized.an
                AND (
                  LEFT(REPLACE(UPPER(TRIM(idg.icd10)), '.', ''), 3) = 'F17'
                  OR REPLACE(UPPER(TRIM(idg.icd10)), '.', '') = 'Z720'
                )
            )
        ) AND (
          EXISTS (
            SELECT 1
            FROM ovstdiag sd
            JOIN ovst v ON v.vn = sd.vn
            WHERE v.hn = opd_periodized.hn
              AND v.vstdate >= (SELECT fy_start FROM thip_params)
              AND v.vstdate < (SELECT fy_end FROM thip_params)
              AND LEFT(REPLACE(UPPER(TRIM(sd.icd10)), '.', ''), 3) IN ('J45', 'J46')
          )
          OR EXISTS (
            SELECT 1
            FROM iptdiag idg
            JOIN ipt i ON i.an = idg.an
            WHERE i.hn = opd_periodized.hn
              AND i.dchdate >= (SELECT fy_start FROM thip_params)
              AND i.dchdate < (SELECT fy_end FROM thip_params)
              AND LEFT(REPLACE(UPPER(TRIM(idg.icd10)), '.', ''), 3) IN ('J45', 'J46')
          )
        )
          GROUP BY 2, 3, 4
          ), expected_codes(indicator_code, fiscal_month, indicator_name_th, indicator_name_en) AS (
            VALUES
              ('HH0104.3', 1, U&'\0E23\0E49\0E2D\0E22\0E25\0E30\0E02\0E2D\0E07\0E1C\0E39\0E49\0E1B\0E48\0E27\0E22\0E01\0E25\0E38\0E48\0E21\0E42\0E23\0E04\0E2B\0E37\0E14\0E17\0E35\0E48\0E23\0E31\0E1A\0E1A\0E23\0E34\0E01\0E32\0E23\0E1A\0E33\0E1A\0E31\0E14\0E23\0E31\0E01\0E29\0E32\0E20\0E32\0E27\0E30\0E15\0E34\0E14\0E19\0E34\0E42\0E04\0E15\0E34\0E19\0E41\0E25\0E30\0E2A\0E32\0E21\0E32\0E23\0E16\0E2B\0E22\0E38\0E14\0020\0E1A\0E23\0E34\0E42\0E20\0E04\0E22\0E32\0E2A\0E39\0E1A\0E15\0E48\0E2D\0E40\0E19\0E37\0E48\0E2D\0E07\0020\0036\0020\0E40\0E14\0E37\0E2D\0E19', 'Tobacco use: continuous abstinence rate (CAR) at 6 months (Asthma Patients)')
          ), fiscal_periods AS (
            SELECT
              generated.period_start::date AS period_start,
              CASE
                WHEN EXTRACT(MONTH FROM generated.period_start) >= 10
                  THEN EXTRACT(MONTH FROM generated.period_start)::integer - 9
                ELSE EXTRACT(MONTH FROM generated.period_start)::integer + 3
              END AS fiscal_month,
              CASE
                WHEN EXTRACT(MONTH FROM generated.period_start) >= 10
                  THEN EXTRACT(YEAR FROM generated.period_start)::integer + 1
                ELSE EXTRACT(YEAR FROM generated.period_start)::integer
              END AS fiscal_year
            FROM generate_series(
              CAST((SELECT fy_start FROM thip_params) AS date),
              CAST((SELECT fy_end FROM thip_params) AS date) - INTERVAL '1 month',
              INTERVAL '1 month'
            ) AS generated(period_start)
          )
          SELECT
            expected_codes.indicator_code,
            expected_codes.indicator_name_th AS indicator_name_th,
            expected_codes.indicator_name_en AS indicator_name_en,
            fiscal_periods.period_start,
            fiscal_periods.fiscal_month,
            fiscal_periods.fiscal_year,
            COALESCE(facts.numerator, 0) AS numerator,
            COALESCE(facts.denominator, 0) AS denominator,
            facts.value
          FROM expected_codes
          JOIN fiscal_periods
            ON fiscal_periods.fiscal_month = expected_codes.fiscal_month
          LEFT JOIN facts
            ON facts.indicator_code = expected_codes.indicator_code
           AND facts.period_start = fiscal_periods.period_start
           AND facts.fiscal_month = fiscal_periods.fiscal_month
           AND facts.fiscal_year = fiscal_periods.fiscal_year
          ORDER BY expected_codes.indicator_code, fiscal_periods.period_start
  ) AS b_HH0104_3
  UNION ALL
  SELECT * FROM (
    WITH
          ipd AS (
        SELECT
          i.an,
          i.hn,
          i.regdate,
          i.regtime,
          i.dchdate,
          COALESCE(i.bw, 0) AS bw,
          s.age_y,
          s.los,
          REPLACE(UPPER(TRIM(s.pdx)), '.', '') AS pdx,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
          ) AS died,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') <> REPLACE(UPPER(TRIM(s.pdx)), '.', '')
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
          ) AS has_acs_sdx,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
              AND (
                REPLACE(UPPER(TRIM(d.death_diag_icd10)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_cause)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_1)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_2)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_3)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_4)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
              )
          ) AS died_from_acs,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') <> REPLACE(UPPER(TRIM(s.pdx)), '.', '')
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
          ) AS has_stemi_sdx,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') <> REPLACE(UPPER(TRIM(s.pdx)), '.', '')
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') IN ('I214', 'I219')
          ) AS has_nste_sdx,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
              AND d.death_date IS NOT NULL
              AND (d.death_date + COALESCE(d.death_time, TIME '23:59:59')) >=
                (i.regdate + COALESCE(i.regtime, TIME '00:00:00'))
              AND (d.death_date + COALESCE(d.death_time, TIME '23:59:59')) <=
                (i.regdate + COALESCE(i.regtime, TIME '00:00:00')) + INTERVAL '48 hours'
          ) AS died_within_48h,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
              AND (
                REPLACE(UPPER(TRIM(d.death_diag_icd10)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
                OR REPLACE(UPPER(TRIM(d.death_cause)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
                OR REPLACE(UPPER(TRIM(d.death_diag_1)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
                OR REPLACE(UPPER(TRIM(d.death_diag_2)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
                OR REPLACE(UPPER(TRIM(d.death_diag_3)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
                OR REPLACE(UPPER(TRIM(d.death_diag_4)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
              )
          ) AS died_from_stemi,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
              AND (
                REPLACE(UPPER(TRIM(d.death_diag_icd10)), '.', '') IN ('I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_cause)), '.', '') IN ('I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_1)), '.', '') IN ('I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_2)), '.', '') IN ('I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_3)), '.', '') IN ('I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_4)), '.', '') IN ('I214', 'I219')
              )
          ) AS died_from_nste,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') <> REPLACE(UPPER(TRIM(s.pdx)), '.', '')
              AND (
                LEFT(REPLACE(UPPER(TRIM(sd.icd10)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(sd.icd10)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
              )
          ) AS has_pneumonia_sdx,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
              AND (
                LEFT(REPLACE(UPPER(TRIM(d.death_diag_icd10)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_icd10)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_cause)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_cause)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_1)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_1)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_2)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_2)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_3)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_3)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_4)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_4)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
              )
          ) AS died_from_pneumonia,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') IN ('A400', 'A419', 'R572', 'R651')
          ) AS has_ce0101_sepsis,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') IN ('A400', 'A409', 'A410', 'A419', 'R572', 'R651')
          ) AS has_ci0101_sepsis
        FROM ipt i
        JOIN an_stat s ON s.an = i.an
        WHERE i.dchdate >= (SELECT fy_start FROM thip_params)
          AND i.dchdate < (SELECT fy_end FROM thip_params)
          AND i.regdate IS NOT NULL
          AND EXTRACT(EPOCH FROM (
            (i.dchdate + COALESCE(i.dchtime, TIME '23:59:59')) -
            (i.regdate + COALESCE(i.regtime, TIME '00:00:00'))
          )) >= 14400
      ),
      periodized AS (
        SELECT
          *,
          DATE_TRUNC('month', dchdate)::date AS period_start,
          EXTRACT(MONTH FROM dchdate)::integer AS calendar_month
        FROM ipd
      ),
          opd_periodized AS (
        SELECT
          v.vn,
          v.hn,
          v.an,
          EXTRACT(YEAR FROM AGE(v.vstdate, pd.birthday))::integer AS age_y,
          pd.sex,
          (SELECT REPLACE(UPPER(TRIM(sd.icd10)), '.', '')
             FROM ovstdiag sd
            WHERE sd.vn = v.vn AND sd.diagtype = '1'
            ORDER BY sd.ovst_diag_id
            LIMIT 1) AS pdx,
          v.vstdate AS event_date,
          er.enter_er_time,
          er.triage_datetime,
          er.doctor_tx_time,
          er.finish_time,
          er.antibiotics_datetime,
          er.stroke_needle_datetime,
          er.stemi_balloon_datetime,
          er.er_emergency_level_id,
          er.unplanned_return,
          er.news2_score,
          DATE_TRUNC('month', v.vstdate)::date AS period_start,
          EXTRACT(MONTH FROM v.vstdate)::integer AS calendar_month
        FROM ovst v
        LEFT JOIN patient pd ON pd.hn = v.hn
        LEFT JOIN er_regist er ON er.vn = v.vn
        WHERE v.vstdate >= (SELECT fy_start FROM thip_params)
          AND v.vstdate < (SELECT fy_end FROM thip_params)
      ),
      chronic_periodized AS (
        SELECT
          cm.clinicmember_id,
          cm.clinic,
          cm.hn,
          cm.regdate,
          cm.lastvisit,
          cm.dchdate,
          cm.current_status,
          cm.clinic_member_status_id,
          cm.age_y,
          cm.sex,
          cm.chronic_type,
          cm.begin_year,
          cm.last_hba1c_value,
          cm.last_hba1c_date,
          cm.last_bp_bps_value,
          cm.last_bp_bpd_value,
          cm.last_bp_date,
          DATE_TRUNC('month', cm.regdate)::date AS period_start,
          EXTRACT(MONTH FROM cm.regdate)::integer AS calendar_month
        FROM clinicmember cm
        WHERE cm.regdate >= (SELECT fy_start FROM thip_params)
          AND cm.regdate < (SELECT fy_end FROM thip_params)
      ),
      delivery_periodized AS (
        SELECT
          l.laborid,
          l.an,
          l.hage AS mother_age_y,
          l.labor_type,
          l.mother_method,
          l.infant_sex,
          l.infant_weight,
          l.infant_apgarscore1,
          l.infant_apgarscore5,
          l.infant_apgarscore10,
          l.placenta_bloodloss,
          l.labour_startdate,
          l.labour_finishdate,
          DATE_TRUNC('month', COALESCE(l.labour_startdate, i.regdate))::date AS period_start,
          EXTRACT(MONTH FROM COALESCE(l.labour_startdate, i.regdate))::integer AS calendar_month
        FROM labor l
        LEFT JOIN ipt i ON i.an = l.an
        WHERE COALESCE(l.labour_startdate, i.regdate) >= (SELECT fy_start FROM thip_params)
          AND COALESCE(l.labour_startdate, i.regdate) < (SELECT fy_end FROM thip_params)
      ),
      newborn_periodized AS (
        SELECT
          nb.an,
          nb.mother_an,
          nb.born_date,
          nb.birth_weight,
          nb.apgar1,
          nb.apgar2,
          nb.dead,
          nb.has_asphyxia,
          nb.birthcondition1,
          nb.birthcondition2,
          nb.anc_complete,
          DATE_TRUNC('month', nb.born_date)::date AS period_start,
          EXTRACT(MONTH FROM nb.born_date)::integer AS calendar_month
        FROM ipt_newborn nb
        WHERE nb.born_date >= (SELECT fy_start FROM thip_params)
          AND nb.born_date < (SELECT fy_end FROM thip_params)
      ),
      emp_periodized AS (
        SELECT
          e.emp_id,
          e.emp_sex_id,
          e.emp_birthdate,
          e.emp_status_id,
          e.emp_type_id,
          e.emp_dep_id,
          e.emp_position_main_id,
          e.emp_work_begindate,
          e.emp_resign_enddate,
          e.emp_resign_type_id,
          DATE_TRUNC('month', e.emp_work_begindate)::date AS period_start,
          EXTRACT(MONTH FROM e.emp_work_begindate)::integer AS calendar_month
        FROM emp e
        WHERE e.emp_work_begindate >= (SELECT fy_start FROM thip_params)
          AND e.emp_work_begindate < (SELECT fy_end FROM thip_params)
      ),
          facts AS (
      
          SELECT
            'HH0104.4' AS indicator_code,
            DATE_TRUNC('month', period_start)::date - MAKE_INTERVAL(months => (CASE WHEN calendar_month >= 10 THEN calendar_month - 9 ELSE calendar_month + 3 END) - (1)) AS period_start,
            1 AS fiscal_month,
            CASE WHEN calendar_month >= 10 THEN EXTRACT(YEAR FROM period_start)::integer + 1 ELSE EXTRACT(YEAR FROM period_start)::integer END AS fiscal_year,
            COUNT(DISTINCT opd_periodized.hn) FILTER (WHERE (
          EXISTS (
            SELECT 1
            FROM ovstdiag sd
            WHERE sd.vn = opd_periodized.vn
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') = 'Z716'
          )
          OR EXISTS (
              SELECT 1
              FROM iptdiag idg
              WHERE idg.an = opd_periodized.an
                AND REPLACE(UPPER(TRIM(idg.icd10)), '.', '') = 'Z716'
            )
          OR EXISTS (
            SELECT 1
            FROM opdscreen scr
            WHERE scr.vn = opd_periodized.vn
              AND (
                scr.advice1 = 'Y' OR scr.advice2 = 'Y' OR scr.advice3 = 'Y'
                OR scr.advice4 = 'Y' OR scr.advice5 = 'Y' OR scr.advice6 = 'Y'
                OR scr.advice7 = 'Y' OR scr.advice8 = 'Y'
                OR scr.advice7_note ILIKE '%smoke%'
                OR scr.advice7_note ILIKE U&'%\0E2A\0E39\0E1A%'
              )
          )
          OR EXISTS (
            SELECT 1
            FROM opitemrece oi
            JOIN drugitems di ON di.icode = oi.icode
            WHERE oi.vn = opd_periodized.vn
              AND (
                di.name ILIKE '%bupropion%'
                OR di.name ILIKE '%varenicline%'
                OR di.name ILIKE '%nicotine%'
              )
          )
        ) AND (
          EXISTS (
            SELECT 1
            FROM ovst fv
            JOIN opdscreen fs ON fs.vn = fv.vn
            WHERE fv.hn = opd_periodized.hn
              AND fv.vstdate >= opd_periodized.event_date + INTERVAL '180 days'
              AND fv.vstdate <= opd_periodized.event_date + INTERVAL '270 days'
              AND COALESCE(fs.smoking_type_id, 0) NOT IN (2, 3)
          )
          AND NOT EXISTS (
            SELECT 1
            FROM ovst rv
            JOIN opdscreen rs ON rs.vn = rv.vn
            WHERE rv.hn = opd_periodized.hn
              AND rv.vstdate > opd_periodized.event_date
              AND rv.vstdate <= opd_periodized.event_date + INTERVAL '270 days'
              AND rs.smoking_type_id IN (2, 3)
          )
        )) AS numerator,
            COUNT(DISTINCT opd_periodized.hn) FILTER (WHERE (
          EXISTS (
            SELECT 1
            FROM ovstdiag sd
            WHERE sd.vn = opd_periodized.vn
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') = 'Z716'
          )
          OR EXISTS (
              SELECT 1
              FROM iptdiag idg
              WHERE idg.an = opd_periodized.an
                AND REPLACE(UPPER(TRIM(idg.icd10)), '.', '') = 'Z716'
            )
          OR EXISTS (
            SELECT 1
            FROM opdscreen scr
            WHERE scr.vn = opd_periodized.vn
              AND (
                scr.advice1 = 'Y' OR scr.advice2 = 'Y' OR scr.advice3 = 'Y'
                OR scr.advice4 = 'Y' OR scr.advice5 = 'Y' OR scr.advice6 = 'Y'
                OR scr.advice7 = 'Y' OR scr.advice8 = 'Y'
                OR scr.advice7_note ILIKE '%smoke%'
                OR scr.advice7_note ILIKE U&'%\0E2A\0E39\0E1A%'
              )
          )
          OR EXISTS (
            SELECT 1
            FROM opitemrece oi
            JOIN drugitems di ON di.icode = oi.icode
            WHERE oi.vn = opd_periodized.vn
              AND (
                di.name ILIKE '%bupropion%'
                OR di.name ILIKE '%varenicline%'
                OR di.name ILIKE '%nicotine%'
              )
          )
        )) AS denominator,
            ROUND((COUNT(DISTINCT opd_periodized.hn) FILTER (WHERE (
          EXISTS (
            SELECT 1
            FROM ovstdiag sd
            WHERE sd.vn = opd_periodized.vn
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') = 'Z716'
          )
          OR EXISTS (
              SELECT 1
              FROM iptdiag idg
              WHERE idg.an = opd_periodized.an
                AND REPLACE(UPPER(TRIM(idg.icd10)), '.', '') = 'Z716'
            )
          OR EXISTS (
            SELECT 1
            FROM opdscreen scr
            WHERE scr.vn = opd_periodized.vn
              AND (
                scr.advice1 = 'Y' OR scr.advice2 = 'Y' OR scr.advice3 = 'Y'
                OR scr.advice4 = 'Y' OR scr.advice5 = 'Y' OR scr.advice6 = 'Y'
                OR scr.advice7 = 'Y' OR scr.advice8 = 'Y'
                OR scr.advice7_note ILIKE '%smoke%'
                OR scr.advice7_note ILIKE U&'%\0E2A\0E39\0E1A%'
              )
          )
          OR EXISTS (
            SELECT 1
            FROM opitemrece oi
            JOIN drugitems di ON di.icode = oi.icode
            WHERE oi.vn = opd_periodized.vn
              AND (
                di.name ILIKE '%bupropion%'
                OR di.name ILIKE '%varenicline%'
                OR di.name ILIKE '%nicotine%'
              )
          )
        ) AND (
          EXISTS (
            SELECT 1
            FROM ovst fv
            JOIN opdscreen fs ON fs.vn = fv.vn
            WHERE fv.hn = opd_periodized.hn
              AND fv.vstdate >= opd_periodized.event_date + INTERVAL '180 days'
              AND fv.vstdate <= opd_periodized.event_date + INTERVAL '270 days'
              AND COALESCE(fs.smoking_type_id, 0) NOT IN (2, 3)
          )
          AND NOT EXISTS (
            SELECT 1
            FROM ovst rv
            JOIN opdscreen rs ON rs.vn = rv.vn
            WHERE rv.hn = opd_periodized.hn
              AND rv.vstdate > opd_periodized.event_date
              AND rv.vstdate <= opd_periodized.event_date + INTERVAL '270 days'
              AND rs.smoking_type_id IN (2, 3)
          )
        )) * 100.0) / NULLIF(COUNT(DISTINCT opd_periodized.hn) FILTER (WHERE (
          EXISTS (
            SELECT 1
            FROM ovstdiag sd
            WHERE sd.vn = opd_periodized.vn
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') = 'Z716'
          )
          OR EXISTS (
              SELECT 1
              FROM iptdiag idg
              WHERE idg.an = opd_periodized.an
                AND REPLACE(UPPER(TRIM(idg.icd10)), '.', '') = 'Z716'
            )
          OR EXISTS (
            SELECT 1
            FROM opdscreen scr
            WHERE scr.vn = opd_periodized.vn
              AND (
                scr.advice1 = 'Y' OR scr.advice2 = 'Y' OR scr.advice3 = 'Y'
                OR scr.advice4 = 'Y' OR scr.advice5 = 'Y' OR scr.advice6 = 'Y'
                OR scr.advice7 = 'Y' OR scr.advice8 = 'Y'
                OR scr.advice7_note ILIKE '%smoke%'
                OR scr.advice7_note ILIKE U&'%\0E2A\0E39\0E1A%'
              )
          )
          OR EXISTS (
            SELECT 1
            FROM opitemrece oi
            JOIN drugitems di ON di.icode = oi.icode
            WHERE oi.vn = opd_periodized.vn
              AND (
                di.name ILIKE '%bupropion%'
                OR di.name ILIKE '%varenicline%'
                OR di.name ILIKE '%nicotine%'
              )
          )
        )), 0), 2) AS value
          FROM opd_periodized
          WHERE opd_periodized.age_y >= 15 AND (
          LEFT(pdx, 3) = 'F17'
          OR pdx = 'Z720'
          OR EXISTS (
            SELECT 1
            FROM ovstdiag sd
            WHERE sd.vn = opd_periodized.vn
              AND (
                LEFT(REPLACE(UPPER(TRIM(sd.icd10)), '.', ''), 3) = 'F17'
                OR REPLACE(UPPER(TRIM(sd.icd10)), '.', '') = 'Z720'
              )
          )
          OR EXISTS (
              SELECT 1
              FROM iptdiag idg
              WHERE idg.an = opd_periodized.an
                AND (
                  LEFT(REPLACE(UPPER(TRIM(idg.icd10)), '.', ''), 3) = 'F17'
                  OR REPLACE(UPPER(TRIM(idg.icd10)), '.', '') = 'Z720'
                )
            )
        ) AND (
          EXISTS (
            SELECT 1
            FROM ovstdiag sd
            JOIN ovst v ON v.vn = sd.vn
            WHERE v.hn = opd_periodized.hn
              AND v.vstdate >= (SELECT fy_start FROM thip_params)
              AND v.vstdate < (SELECT fy_end FROM thip_params)
              AND LEFT(REPLACE(UPPER(TRIM(sd.icd10)), '.', ''), 3) IN ('J44')
          )
          OR EXISTS (
            SELECT 1
            FROM iptdiag idg
            JOIN ipt i ON i.an = idg.an
            WHERE i.hn = opd_periodized.hn
              AND i.dchdate >= (SELECT fy_start FROM thip_params)
              AND i.dchdate < (SELECT fy_end FROM thip_params)
              AND LEFT(REPLACE(UPPER(TRIM(idg.icd10)), '.', ''), 3) IN ('J44')
          )
        )
          GROUP BY 2, 3, 4
          ), expected_codes(indicator_code, fiscal_month, indicator_name_th, indicator_name_en) AS (
            VALUES
              ('HH0104.4', 1, U&'\0E23\0E49\0E2D\0E22\0E25\0E30\0E02\0E2D\0E07\0E1C\0E39\0E49\0E1B\0E48\0E27\0E22\0E01\0E25\0E38\0E48\0E21\0E42\0E23\0E04\0E16\0E38\0E07\0E25\0E21\0E42\0E1B\0E48\0E07\0E1E\0E2D\0E07\0E17\0E35\0E48\0E23\0E31\0E1A\0E1A\0E23\0E34\0E01\0E32\0E23\0E1A\0E33\0E1A\0E31\0E14\0E23\0E31\0E01\0E29\0E32\0E20\0E32\0E27\0E30\0E15\0E34\0E14\0E19\0E34\0E42\0E04\0E15\0E34\0E19\0E41\0E25\0E30\0E2A\0E32\0E21\0E32\0E23\0E16\0020\0E2B\0E22\0E38\0E14\0E1A\0E23\0E34\0E42\0E20\0E04\0E22\0E32\0E2A\0E39\0E1A\0E15\0E48\0E2D\0E40\0E19\0E37\0E48\0E2D\0E07\0020\0036\0020\0E40\0E14\0E37\0E2D\0E19', 'Tobacco use: continuous abstinence rate (CAR) at 6 months (COPD Patients)')
          ), fiscal_periods AS (
            SELECT
              generated.period_start::date AS period_start,
              CASE
                WHEN EXTRACT(MONTH FROM generated.period_start) >= 10
                  THEN EXTRACT(MONTH FROM generated.period_start)::integer - 9
                ELSE EXTRACT(MONTH FROM generated.period_start)::integer + 3
              END AS fiscal_month,
              CASE
                WHEN EXTRACT(MONTH FROM generated.period_start) >= 10
                  THEN EXTRACT(YEAR FROM generated.period_start)::integer + 1
                ELSE EXTRACT(YEAR FROM generated.period_start)::integer
              END AS fiscal_year
            FROM generate_series(
              CAST((SELECT fy_start FROM thip_params) AS date),
              CAST((SELECT fy_end FROM thip_params) AS date) - INTERVAL '1 month',
              INTERVAL '1 month'
            ) AS generated(period_start)
          )
          SELECT
            expected_codes.indicator_code,
            expected_codes.indicator_name_th AS indicator_name_th,
            expected_codes.indicator_name_en AS indicator_name_en,
            fiscal_periods.period_start,
            fiscal_periods.fiscal_month,
            fiscal_periods.fiscal_year,
            COALESCE(facts.numerator, 0) AS numerator,
            COALESCE(facts.denominator, 0) AS denominator,
            facts.value
          FROM expected_codes
          JOIN fiscal_periods
            ON fiscal_periods.fiscal_month = expected_codes.fiscal_month
          LEFT JOIN facts
            ON facts.indicator_code = expected_codes.indicator_code
           AND facts.period_start = fiscal_periods.period_start
           AND facts.fiscal_month = fiscal_periods.fiscal_month
           AND facts.fiscal_year = fiscal_periods.fiscal_year
          ORDER BY expected_codes.indicator_code, fiscal_periods.period_start
  ) AS b_HH0104_4
  UNION ALL
  SELECT * FROM (
    WITH
          ipd AS (
        SELECT
          i.an,
          i.hn,
          i.regdate,
          i.regtime,
          i.dchdate,
          COALESCE(i.bw, 0) AS bw,
          s.age_y,
          s.los,
          REPLACE(UPPER(TRIM(s.pdx)), '.', '') AS pdx,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
          ) AS died,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') <> REPLACE(UPPER(TRIM(s.pdx)), '.', '')
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
          ) AS has_acs_sdx,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
              AND (
                REPLACE(UPPER(TRIM(d.death_diag_icd10)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_cause)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_1)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_2)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_3)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_4)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
              )
          ) AS died_from_acs,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') <> REPLACE(UPPER(TRIM(s.pdx)), '.', '')
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
          ) AS has_stemi_sdx,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') <> REPLACE(UPPER(TRIM(s.pdx)), '.', '')
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') IN ('I214', 'I219')
          ) AS has_nste_sdx,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
              AND d.death_date IS NOT NULL
              AND (d.death_date + COALESCE(d.death_time, TIME '23:59:59')) >=
                (i.regdate + COALESCE(i.regtime, TIME '00:00:00'))
              AND (d.death_date + COALESCE(d.death_time, TIME '23:59:59')) <=
                (i.regdate + COALESCE(i.regtime, TIME '00:00:00')) + INTERVAL '48 hours'
          ) AS died_within_48h,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
              AND (
                REPLACE(UPPER(TRIM(d.death_diag_icd10)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
                OR REPLACE(UPPER(TRIM(d.death_cause)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
                OR REPLACE(UPPER(TRIM(d.death_diag_1)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
                OR REPLACE(UPPER(TRIM(d.death_diag_2)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
                OR REPLACE(UPPER(TRIM(d.death_diag_3)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
                OR REPLACE(UPPER(TRIM(d.death_diag_4)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
              )
          ) AS died_from_stemi,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
              AND (
                REPLACE(UPPER(TRIM(d.death_diag_icd10)), '.', '') IN ('I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_cause)), '.', '') IN ('I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_1)), '.', '') IN ('I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_2)), '.', '') IN ('I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_3)), '.', '') IN ('I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_4)), '.', '') IN ('I214', 'I219')
              )
          ) AS died_from_nste,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') <> REPLACE(UPPER(TRIM(s.pdx)), '.', '')
              AND (
                LEFT(REPLACE(UPPER(TRIM(sd.icd10)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(sd.icd10)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
              )
          ) AS has_pneumonia_sdx,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
              AND (
                LEFT(REPLACE(UPPER(TRIM(d.death_diag_icd10)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_icd10)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_cause)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_cause)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_1)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_1)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_2)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_2)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_3)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_3)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_4)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_4)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
              )
          ) AS died_from_pneumonia,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') IN ('A400', 'A419', 'R572', 'R651')
          ) AS has_ce0101_sepsis,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') IN ('A400', 'A409', 'A410', 'A419', 'R572', 'R651')
          ) AS has_ci0101_sepsis
        FROM ipt i
        JOIN an_stat s ON s.an = i.an
        WHERE i.dchdate >= (SELECT fy_start FROM thip_params)
          AND i.dchdate < (SELECT fy_end FROM thip_params)
          AND i.regdate IS NOT NULL
          AND EXTRACT(EPOCH FROM (
            (i.dchdate + COALESCE(i.dchtime, TIME '23:59:59')) -
            (i.regdate + COALESCE(i.regtime, TIME '00:00:00'))
          )) >= 14400
      ),
      periodized AS (
        SELECT
          *,
          DATE_TRUNC('month', dchdate)::date AS period_start,
          EXTRACT(MONTH FROM dchdate)::integer AS calendar_month
        FROM ipd
      ),
          opd_periodized AS (
        SELECT
          v.vn,
          v.hn,
          v.an,
          EXTRACT(YEAR FROM AGE(v.vstdate, pd.birthday))::integer AS age_y,
          pd.sex,
          (SELECT REPLACE(UPPER(TRIM(sd.icd10)), '.', '')
             FROM ovstdiag sd
            WHERE sd.vn = v.vn AND sd.diagtype = '1'
            ORDER BY sd.ovst_diag_id
            LIMIT 1) AS pdx,
          v.vstdate AS event_date,
          er.enter_er_time,
          er.triage_datetime,
          er.doctor_tx_time,
          er.finish_time,
          er.antibiotics_datetime,
          er.stroke_needle_datetime,
          er.stemi_balloon_datetime,
          er.er_emergency_level_id,
          er.unplanned_return,
          er.news2_score,
          DATE_TRUNC('month', v.vstdate)::date AS period_start,
          EXTRACT(MONTH FROM v.vstdate)::integer AS calendar_month
        FROM ovst v
        LEFT JOIN patient pd ON pd.hn = v.hn
        LEFT JOIN er_regist er ON er.vn = v.vn
        WHERE v.vstdate >= (SELECT fy_start FROM thip_params)
          AND v.vstdate < (SELECT fy_end FROM thip_params)
      ),
      chronic_periodized AS (
        SELECT
          cm.clinicmember_id,
          cm.clinic,
          cm.hn,
          cm.regdate,
          cm.lastvisit,
          cm.dchdate,
          cm.current_status,
          cm.clinic_member_status_id,
          cm.age_y,
          cm.sex,
          cm.chronic_type,
          cm.begin_year,
          cm.last_hba1c_value,
          cm.last_hba1c_date,
          cm.last_bp_bps_value,
          cm.last_bp_bpd_value,
          cm.last_bp_date,
          DATE_TRUNC('month', cm.regdate)::date AS period_start,
          EXTRACT(MONTH FROM cm.regdate)::integer AS calendar_month
        FROM clinicmember cm
        WHERE cm.regdate >= (SELECT fy_start FROM thip_params)
          AND cm.regdate < (SELECT fy_end FROM thip_params)
      ),
      delivery_periodized AS (
        SELECT
          l.laborid,
          l.an,
          l.hage AS mother_age_y,
          l.labor_type,
          l.mother_method,
          l.infant_sex,
          l.infant_weight,
          l.infant_apgarscore1,
          l.infant_apgarscore5,
          l.infant_apgarscore10,
          l.placenta_bloodloss,
          l.labour_startdate,
          l.labour_finishdate,
          DATE_TRUNC('month', COALESCE(l.labour_startdate, i.regdate))::date AS period_start,
          EXTRACT(MONTH FROM COALESCE(l.labour_startdate, i.regdate))::integer AS calendar_month
        FROM labor l
        LEFT JOIN ipt i ON i.an = l.an
        WHERE COALESCE(l.labour_startdate, i.regdate) >= (SELECT fy_start FROM thip_params)
          AND COALESCE(l.labour_startdate, i.regdate) < (SELECT fy_end FROM thip_params)
      ),
      newborn_periodized AS (
        SELECT
          nb.an,
          nb.mother_an,
          nb.born_date,
          nb.birth_weight,
          nb.apgar1,
          nb.apgar2,
          nb.dead,
          nb.has_asphyxia,
          nb.birthcondition1,
          nb.birthcondition2,
          nb.anc_complete,
          DATE_TRUNC('month', nb.born_date)::date AS period_start,
          EXTRACT(MONTH FROM nb.born_date)::integer AS calendar_month
        FROM ipt_newborn nb
        WHERE nb.born_date >= (SELECT fy_start FROM thip_params)
          AND nb.born_date < (SELECT fy_end FROM thip_params)
      ),
      emp_periodized AS (
        SELECT
          e.emp_id,
          e.emp_sex_id,
          e.emp_birthdate,
          e.emp_status_id,
          e.emp_type_id,
          e.emp_dep_id,
          e.emp_position_main_id,
          e.emp_work_begindate,
          e.emp_resign_enddate,
          e.emp_resign_type_id,
          DATE_TRUNC('month', e.emp_work_begindate)::date AS period_start,
          EXTRACT(MONTH FROM e.emp_work_begindate)::integer AS calendar_month
        FROM emp e
        WHERE e.emp_work_begindate >= (SELECT fy_start FROM thip_params)
          AND e.emp_work_begindate < (SELECT fy_end FROM thip_params)
      ),
          facts AS (
      
          SELECT
            'HH0104.5' AS indicator_code,
            DATE_TRUNC('month', period_start)::date - MAKE_INTERVAL(months => (CASE WHEN calendar_month >= 10 THEN calendar_month - 9 ELSE calendar_month + 3 END) - (1)) AS period_start,
            1 AS fiscal_month,
            CASE WHEN calendar_month >= 10 THEN EXTRACT(YEAR FROM period_start)::integer + 1 ELSE EXTRACT(YEAR FROM period_start)::integer END AS fiscal_year,
            COUNT(DISTINCT opd_periodized.hn) FILTER (WHERE (
          EXISTS (
            SELECT 1
            FROM ovstdiag sd
            WHERE sd.vn = opd_periodized.vn
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') = 'Z716'
          )
          OR EXISTS (
              SELECT 1
              FROM iptdiag idg
              WHERE idg.an = opd_periodized.an
                AND REPLACE(UPPER(TRIM(idg.icd10)), '.', '') = 'Z716'
            )
          OR EXISTS (
            SELECT 1
            FROM opdscreen scr
            WHERE scr.vn = opd_periodized.vn
              AND (
                scr.advice1 = 'Y' OR scr.advice2 = 'Y' OR scr.advice3 = 'Y'
                OR scr.advice4 = 'Y' OR scr.advice5 = 'Y' OR scr.advice6 = 'Y'
                OR scr.advice7 = 'Y' OR scr.advice8 = 'Y'
                OR scr.advice7_note ILIKE '%smoke%'
                OR scr.advice7_note ILIKE U&'%\0E2A\0E39\0E1A%'
              )
          )
          OR EXISTS (
            SELECT 1
            FROM opitemrece oi
            JOIN drugitems di ON di.icode = oi.icode
            WHERE oi.vn = opd_periodized.vn
              AND (
                di.name ILIKE '%bupropion%'
                OR di.name ILIKE '%varenicline%'
                OR di.name ILIKE '%nicotine%'
              )
          )
        ) AND (
          EXISTS (
            SELECT 1
            FROM ovst fv
            JOIN opdscreen fs ON fs.vn = fv.vn
            WHERE fv.hn = opd_periodized.hn
              AND fv.vstdate >= opd_periodized.event_date + INTERVAL '180 days'
              AND fv.vstdate <= opd_periodized.event_date + INTERVAL '270 days'
              AND COALESCE(fs.smoking_type_id, 0) NOT IN (2, 3)
          )
          AND NOT EXISTS (
            SELECT 1
            FROM ovst rv
            JOIN opdscreen rs ON rs.vn = rv.vn
            WHERE rv.hn = opd_periodized.hn
              AND rv.vstdate > opd_periodized.event_date
              AND rv.vstdate <= opd_periodized.event_date + INTERVAL '270 days'
              AND rs.smoking_type_id IN (2, 3)
          )
        )) AS numerator,
            COUNT(DISTINCT opd_periodized.hn) FILTER (WHERE (
          EXISTS (
            SELECT 1
            FROM ovstdiag sd
            WHERE sd.vn = opd_periodized.vn
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') = 'Z716'
          )
          OR EXISTS (
              SELECT 1
              FROM iptdiag idg
              WHERE idg.an = opd_periodized.an
                AND REPLACE(UPPER(TRIM(idg.icd10)), '.', '') = 'Z716'
            )
          OR EXISTS (
            SELECT 1
            FROM opdscreen scr
            WHERE scr.vn = opd_periodized.vn
              AND (
                scr.advice1 = 'Y' OR scr.advice2 = 'Y' OR scr.advice3 = 'Y'
                OR scr.advice4 = 'Y' OR scr.advice5 = 'Y' OR scr.advice6 = 'Y'
                OR scr.advice7 = 'Y' OR scr.advice8 = 'Y'
                OR scr.advice7_note ILIKE '%smoke%'
                OR scr.advice7_note ILIKE U&'%\0E2A\0E39\0E1A%'
              )
          )
          OR EXISTS (
            SELECT 1
            FROM opitemrece oi
            JOIN drugitems di ON di.icode = oi.icode
            WHERE oi.vn = opd_periodized.vn
              AND (
                di.name ILIKE '%bupropion%'
                OR di.name ILIKE '%varenicline%'
                OR di.name ILIKE '%nicotine%'
              )
          )
        )) AS denominator,
            ROUND((COUNT(DISTINCT opd_periodized.hn) FILTER (WHERE (
          EXISTS (
            SELECT 1
            FROM ovstdiag sd
            WHERE sd.vn = opd_periodized.vn
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') = 'Z716'
          )
          OR EXISTS (
              SELECT 1
              FROM iptdiag idg
              WHERE idg.an = opd_periodized.an
                AND REPLACE(UPPER(TRIM(idg.icd10)), '.', '') = 'Z716'
            )
          OR EXISTS (
            SELECT 1
            FROM opdscreen scr
            WHERE scr.vn = opd_periodized.vn
              AND (
                scr.advice1 = 'Y' OR scr.advice2 = 'Y' OR scr.advice3 = 'Y'
                OR scr.advice4 = 'Y' OR scr.advice5 = 'Y' OR scr.advice6 = 'Y'
                OR scr.advice7 = 'Y' OR scr.advice8 = 'Y'
                OR scr.advice7_note ILIKE '%smoke%'
                OR scr.advice7_note ILIKE U&'%\0E2A\0E39\0E1A%'
              )
          )
          OR EXISTS (
            SELECT 1
            FROM opitemrece oi
            JOIN drugitems di ON di.icode = oi.icode
            WHERE oi.vn = opd_periodized.vn
              AND (
                di.name ILIKE '%bupropion%'
                OR di.name ILIKE '%varenicline%'
                OR di.name ILIKE '%nicotine%'
              )
          )
        ) AND (
          EXISTS (
            SELECT 1
            FROM ovst fv
            JOIN opdscreen fs ON fs.vn = fv.vn
            WHERE fv.hn = opd_periodized.hn
              AND fv.vstdate >= opd_periodized.event_date + INTERVAL '180 days'
              AND fv.vstdate <= opd_periodized.event_date + INTERVAL '270 days'
              AND COALESCE(fs.smoking_type_id, 0) NOT IN (2, 3)
          )
          AND NOT EXISTS (
            SELECT 1
            FROM ovst rv
            JOIN opdscreen rs ON rs.vn = rv.vn
            WHERE rv.hn = opd_periodized.hn
              AND rv.vstdate > opd_periodized.event_date
              AND rv.vstdate <= opd_periodized.event_date + INTERVAL '270 days'
              AND rs.smoking_type_id IN (2, 3)
          )
        )) * 100.0) / NULLIF(COUNT(DISTINCT opd_periodized.hn) FILTER (WHERE (
          EXISTS (
            SELECT 1
            FROM ovstdiag sd
            WHERE sd.vn = opd_periodized.vn
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') = 'Z716'
          )
          OR EXISTS (
              SELECT 1
              FROM iptdiag idg
              WHERE idg.an = opd_periodized.an
                AND REPLACE(UPPER(TRIM(idg.icd10)), '.', '') = 'Z716'
            )
          OR EXISTS (
            SELECT 1
            FROM opdscreen scr
            WHERE scr.vn = opd_periodized.vn
              AND (
                scr.advice1 = 'Y' OR scr.advice2 = 'Y' OR scr.advice3 = 'Y'
                OR scr.advice4 = 'Y' OR scr.advice5 = 'Y' OR scr.advice6 = 'Y'
                OR scr.advice7 = 'Y' OR scr.advice8 = 'Y'
                OR scr.advice7_note ILIKE '%smoke%'
                OR scr.advice7_note ILIKE U&'%\0E2A\0E39\0E1A%'
              )
          )
          OR EXISTS (
            SELECT 1
            FROM opitemrece oi
            JOIN drugitems di ON di.icode = oi.icode
            WHERE oi.vn = opd_periodized.vn
              AND (
                di.name ILIKE '%bupropion%'
                OR di.name ILIKE '%varenicline%'
                OR di.name ILIKE '%nicotine%'
              )
          )
        )), 0), 2) AS value
          FROM opd_periodized
          WHERE opd_periodized.age_y >= 15 AND (
          LEFT(pdx, 3) = 'F17'
          OR pdx = 'Z720'
          OR EXISTS (
            SELECT 1
            FROM ovstdiag sd
            WHERE sd.vn = opd_periodized.vn
              AND (
                LEFT(REPLACE(UPPER(TRIM(sd.icd10)), '.', ''), 3) = 'F17'
                OR REPLACE(UPPER(TRIM(sd.icd10)), '.', '') = 'Z720'
              )
          )
          OR EXISTS (
              SELECT 1
              FROM iptdiag idg
              WHERE idg.an = opd_periodized.an
                AND (
                  LEFT(REPLACE(UPPER(TRIM(idg.icd10)), '.', ''), 3) = 'F17'
                  OR REPLACE(UPPER(TRIM(idg.icd10)), '.', '') = 'Z720'
                )
            )
        ) AND (
          EXISTS (
            SELECT 1
            FROM opdscreen pg
            WHERE pg.vn = opd_periodized.vn
              AND pg.pregnancy = 'Y'
          )
          OR EXISTS (
            SELECT 1
            FROM opdscreen_pregnancy pg2
            WHERE pg2.vn = opd_periodized.vn
          )
          OR EXISTS (
              SELECT 1
              FROM ipt_pregnancy ipg
              WHERE ipg.an = opd_periodized.an
            )
          OR EXISTS (
            SELECT 1
            FROM clinicmember cm
            WHERE cm.hn = opd_periodized.hn
              AND cm.with_pregnancy = 'Y'
          )
        )
          GROUP BY 2, 3, 4
          ), expected_codes(indicator_code, fiscal_month, indicator_name_th, indicator_name_en) AS (
            VALUES
              ('HH0104.5', 1, U&'\0E23\0E49\0E2D\0E22\0E25\0E30\0E02\0E2D\0E07\0E1C\0E39\0E49\0E1B\0E48\0E27\0E22\0E01\0E25\0E38\0E48\0E21\0E2B\0E0D\0E34\0E07\0E15\0E31\0E49\0E07\0E04\0E23\0E23\0E20\0E4C\0E17\0E35\0E48\0E23\0E31\0E1A\0E1A\0E23\0E34\0E01\0E32\0E23\0E1A\0E33\0E1A\0E31\0E14\0E23\0E31\0E01\0E29\0E32\0E20\0E32\0E27\0E30\0E15\0E34\0E14\0E19\0E34\0E42\0E04\0E15\0E34\0E19\0E41\0E25\0E30\0E2A\0E32\0E21\0E32\0E23\0E16\0020\0E2B\0E22\0E38\0E14\0E1A\0E23\0E34\0E42\0E20\0E04\0E22\0E32\0E2A\0E39\0E1A\0E15\0E48\0E2D\0E40\0E19\0E37\0E48\0E2D\0E07\0020\0036\0020\0E40\0E14\0E37\0E2D\0E19', 'Tobacco use: Tobacco use: continuous abstinence rate (CAR) at 6 months (Pregnant Patients)')
          ), fiscal_periods AS (
            SELECT
              generated.period_start::date AS period_start,
              CASE
                WHEN EXTRACT(MONTH FROM generated.period_start) >= 10
                  THEN EXTRACT(MONTH FROM generated.period_start)::integer - 9
                ELSE EXTRACT(MONTH FROM generated.period_start)::integer + 3
              END AS fiscal_month,
              CASE
                WHEN EXTRACT(MONTH FROM generated.period_start) >= 10
                  THEN EXTRACT(YEAR FROM generated.period_start)::integer + 1
                ELSE EXTRACT(YEAR FROM generated.period_start)::integer
              END AS fiscal_year
            FROM generate_series(
              CAST((SELECT fy_start FROM thip_params) AS date),
              CAST((SELECT fy_end FROM thip_params) AS date) - INTERVAL '1 month',
              INTERVAL '1 month'
            ) AS generated(period_start)
          )
          SELECT
            expected_codes.indicator_code,
            expected_codes.indicator_name_th AS indicator_name_th,
            expected_codes.indicator_name_en AS indicator_name_en,
            fiscal_periods.period_start,
            fiscal_periods.fiscal_month,
            fiscal_periods.fiscal_year,
            COALESCE(facts.numerator, 0) AS numerator,
            COALESCE(facts.denominator, 0) AS denominator,
            facts.value
          FROM expected_codes
          JOIN fiscal_periods
            ON fiscal_periods.fiscal_month = expected_codes.fiscal_month
          LEFT JOIN facts
            ON facts.indicator_code = expected_codes.indicator_code
           AND facts.period_start = fiscal_periods.period_start
           AND facts.fiscal_month = fiscal_periods.fiscal_month
           AND facts.fiscal_year = fiscal_periods.fiscal_year
          ORDER BY expected_codes.indicator_code, fiscal_periods.period_start
  ) AS b_HH0104_5
  UNION ALL
  SELECT * FROM (
    WITH
          ipd AS (
        SELECT
          i.an,
          i.hn,
          i.regdate,
          i.regtime,
          i.dchdate,
          COALESCE(i.bw, 0) AS bw,
          s.age_y,
          s.los,
          REPLACE(UPPER(TRIM(s.pdx)), '.', '') AS pdx,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
          ) AS died,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') <> REPLACE(UPPER(TRIM(s.pdx)), '.', '')
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
          ) AS has_acs_sdx,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
              AND (
                REPLACE(UPPER(TRIM(d.death_diag_icd10)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_cause)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_1)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_2)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_3)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_4)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
              )
          ) AS died_from_acs,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') <> REPLACE(UPPER(TRIM(s.pdx)), '.', '')
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
          ) AS has_stemi_sdx,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') <> REPLACE(UPPER(TRIM(s.pdx)), '.', '')
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') IN ('I214', 'I219')
          ) AS has_nste_sdx,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
              AND d.death_date IS NOT NULL
              AND (d.death_date + COALESCE(d.death_time, TIME '23:59:59')) >=
                (i.regdate + COALESCE(i.regtime, TIME '00:00:00'))
              AND (d.death_date + COALESCE(d.death_time, TIME '23:59:59')) <=
                (i.regdate + COALESCE(i.regtime, TIME '00:00:00')) + INTERVAL '48 hours'
          ) AS died_within_48h,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
              AND (
                REPLACE(UPPER(TRIM(d.death_diag_icd10)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
                OR REPLACE(UPPER(TRIM(d.death_cause)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
                OR REPLACE(UPPER(TRIM(d.death_diag_1)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
                OR REPLACE(UPPER(TRIM(d.death_diag_2)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
                OR REPLACE(UPPER(TRIM(d.death_diag_3)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
                OR REPLACE(UPPER(TRIM(d.death_diag_4)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
              )
          ) AS died_from_stemi,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
              AND (
                REPLACE(UPPER(TRIM(d.death_diag_icd10)), '.', '') IN ('I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_cause)), '.', '') IN ('I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_1)), '.', '') IN ('I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_2)), '.', '') IN ('I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_3)), '.', '') IN ('I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_4)), '.', '') IN ('I214', 'I219')
              )
          ) AS died_from_nste,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') <> REPLACE(UPPER(TRIM(s.pdx)), '.', '')
              AND (
                LEFT(REPLACE(UPPER(TRIM(sd.icd10)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(sd.icd10)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
              )
          ) AS has_pneumonia_sdx,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
              AND (
                LEFT(REPLACE(UPPER(TRIM(d.death_diag_icd10)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_icd10)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_cause)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_cause)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_1)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_1)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_2)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_2)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_3)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_3)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_4)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_4)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
              )
          ) AS died_from_pneumonia,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') IN ('A400', 'A419', 'R572', 'R651')
          ) AS has_ce0101_sepsis,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') IN ('A400', 'A409', 'A410', 'A419', 'R572', 'R651')
          ) AS has_ci0101_sepsis
        FROM ipt i
        JOIN an_stat s ON s.an = i.an
        WHERE i.dchdate >= (SELECT fy_start FROM thip_params)
          AND i.dchdate < (SELECT fy_end FROM thip_params)
          AND i.regdate IS NOT NULL
          AND EXTRACT(EPOCH FROM (
            (i.dchdate + COALESCE(i.dchtime, TIME '23:59:59')) -
            (i.regdate + COALESCE(i.regtime, TIME '00:00:00'))
          )) >= 14400
      ),
      periodized AS (
        SELECT
          *,
          DATE_TRUNC('month', dchdate)::date AS period_start,
          EXTRACT(MONTH FROM dchdate)::integer AS calendar_month
        FROM ipd
      ),
          opd_periodized AS (
        SELECT
          v.vn,
          v.hn,
          v.an,
          EXTRACT(YEAR FROM AGE(v.vstdate, pd.birthday))::integer AS age_y,
          pd.sex,
          (SELECT REPLACE(UPPER(TRIM(sd.icd10)), '.', '')
             FROM ovstdiag sd
            WHERE sd.vn = v.vn AND sd.diagtype = '1'
            ORDER BY sd.ovst_diag_id
            LIMIT 1) AS pdx,
          v.vstdate AS event_date,
          er.enter_er_time,
          er.triage_datetime,
          er.doctor_tx_time,
          er.finish_time,
          er.antibiotics_datetime,
          er.stroke_needle_datetime,
          er.stemi_balloon_datetime,
          er.er_emergency_level_id,
          er.unplanned_return,
          er.news2_score,
          DATE_TRUNC('month', v.vstdate)::date AS period_start,
          EXTRACT(MONTH FROM v.vstdate)::integer AS calendar_month
        FROM ovst v
        LEFT JOIN patient pd ON pd.hn = v.hn
        LEFT JOIN er_regist er ON er.vn = v.vn
        WHERE v.vstdate >= (SELECT fy_start FROM thip_params)
          AND v.vstdate < (SELECT fy_end FROM thip_params)
      ),
      chronic_periodized AS (
        SELECT
          cm.clinicmember_id,
          cm.clinic,
          cm.hn,
          cm.regdate,
          cm.lastvisit,
          cm.dchdate,
          cm.current_status,
          cm.clinic_member_status_id,
          cm.age_y,
          cm.sex,
          cm.chronic_type,
          cm.begin_year,
          cm.last_hba1c_value,
          cm.last_hba1c_date,
          cm.last_bp_bps_value,
          cm.last_bp_bpd_value,
          cm.last_bp_date,
          DATE_TRUNC('month', cm.regdate)::date AS period_start,
          EXTRACT(MONTH FROM cm.regdate)::integer AS calendar_month
        FROM clinicmember cm
        WHERE cm.regdate >= (SELECT fy_start FROM thip_params)
          AND cm.regdate < (SELECT fy_end FROM thip_params)
      ),
      delivery_periodized AS (
        SELECT
          l.laborid,
          l.an,
          l.hage AS mother_age_y,
          l.labor_type,
          l.mother_method,
          l.infant_sex,
          l.infant_weight,
          l.infant_apgarscore1,
          l.infant_apgarscore5,
          l.infant_apgarscore10,
          l.placenta_bloodloss,
          l.labour_startdate,
          l.labour_finishdate,
          DATE_TRUNC('month', COALESCE(l.labour_startdate, i.regdate))::date AS period_start,
          EXTRACT(MONTH FROM COALESCE(l.labour_startdate, i.regdate))::integer AS calendar_month
        FROM labor l
        LEFT JOIN ipt i ON i.an = l.an
        WHERE COALESCE(l.labour_startdate, i.regdate) >= (SELECT fy_start FROM thip_params)
          AND COALESCE(l.labour_startdate, i.regdate) < (SELECT fy_end FROM thip_params)
      ),
      newborn_periodized AS (
        SELECT
          nb.an,
          nb.mother_an,
          nb.born_date,
          nb.birth_weight,
          nb.apgar1,
          nb.apgar2,
          nb.dead,
          nb.has_asphyxia,
          nb.birthcondition1,
          nb.birthcondition2,
          nb.anc_complete,
          DATE_TRUNC('month', nb.born_date)::date AS period_start,
          EXTRACT(MONTH FROM nb.born_date)::integer AS calendar_month
        FROM ipt_newborn nb
        WHERE nb.born_date >= (SELECT fy_start FROM thip_params)
          AND nb.born_date < (SELECT fy_end FROM thip_params)
      ),
      emp_periodized AS (
        SELECT
          e.emp_id,
          e.emp_sex_id,
          e.emp_birthdate,
          e.emp_status_id,
          e.emp_type_id,
          e.emp_dep_id,
          e.emp_position_main_id,
          e.emp_work_begindate,
          e.emp_resign_enddate,
          e.emp_resign_type_id,
          DATE_TRUNC('month', e.emp_work_begindate)::date AS period_start,
          EXTRACT(MONTH FROM e.emp_work_begindate)::integer AS calendar_month
        FROM emp e
        WHERE e.emp_work_begindate >= (SELECT fy_start FROM thip_params)
          AND e.emp_work_begindate < (SELECT fy_end FROM thip_params)
      ),
          facts AS (
      
          SELECT
            'SH0101' AS indicator_code,
            DATE_TRUNC('month', period_start)::date - MAKE_INTERVAL(months => (CASE WHEN calendar_month >= 10 THEN calendar_month - 9 ELSE calendar_month + 3 END) - (1)) AS period_start,
            1 AS fiscal_month,
            CASE WHEN calendar_month >= 10 THEN EXTRACT(YEAR FROM period_start)::integer + 1 ELSE EXTRACT(YEAR FROM period_start)::integer END AS fiscal_year,
            SUM(hr.voluntary_resign_cnt) / NULLIF(12, 0) AS numerator,
            (COUNT(DISTINCT hr.staff_key) FILTER (WHERE hr.active_at_fy_start) + COUNT(DISTINCT hr.staff_key) FILTER (WHERE hr.active_at_fy_end)) / NULLIF(2, 0) AS denominator,
            ROUND((SUM(hr.voluntary_resign_cnt) / NULLIF(12, 0)) * 100 / NULLIF((COUNT(DISTINCT hr.staff_key) FILTER (WHERE hr.active_at_fy_start) + COUNT(DISTINCT hr.staff_key) FILTER (WHERE hr.active_at_fy_end)) / NULLIF(2, 0), 0), 2) AS value
          FROM (
            SELECT
              e.emp_id AS staff_key,
              DATE_TRUNC('month', months.work_month)::date AS period_start,
              EXTRACT(MONTH FROM months.work_month)::integer AS calendar_month,
              (SELECT COUNT(*)
                FROM emp_resign rr
                LEFT JOIN emp_resign_type rt ON rt.emp_resign_type_id = rr.emp_resign_type_id
                WHERE rr.emp_id = e.emp_id
                  AND rr.emp_resign_date >= months.work_month
                  AND rr.emp_resign_date < months.work_month + INTERVAL '1 month'
                  AND (rt.emp_resign_type_name IS NULL OR rt.emp_resign_type_name NOT ILIKE ANY (ARRAY[U&'%\0E43\0E2B\0E49\0E2D\0E2D\0E01%', U&'%\0E44\0E25\0E48\0E2D\0E2D\0E01%', U&'%\0E1B\0E25\0E14%', U&'%\0E40\0E01\0E29\0E35\0E22\0E13%', U&'%\0E40\0E2A\0E35\0E22\0E0A\0E35\0E27\0E34\0E15%', U&'%\0E16\0E36\0E07\0E41\0E01\0E48\0E01\0E23\0E23\0E21%', U&'%\0E42\0E2D\0E19%', U&'%\0E22\0E49\0E32\0E22%', U&'%\0E15\0E32\0E22%']))) AS voluntary_resign_cnt,
              ((e.emp_work_begindate IS NULL OR e.emp_work_begindate <= CASE WHEN EXTRACT(MONTH FROM months.work_month) >= 10 THEN DATE_TRUNC('year', months.work_month)::date + INTERVAL '9 months' ELSE DATE_TRUNC('year', months.work_month)::date - INTERVAL '3 months' END) AND (e.emp_resign_enddate IS NULL OR e.emp_resign_enddate >= CASE WHEN EXTRACT(MONTH FROM months.work_month) >= 10 THEN DATE_TRUNC('year', months.work_month)::date + INTERVAL '9 months' ELSE DATE_TRUNC('year', months.work_month)::date - INTERVAL '3 months' END)) AS active_at_fy_start,
              ((e.emp_work_begindate IS NULL OR e.emp_work_begindate <= (CASE WHEN EXTRACT(MONTH FROM months.work_month) >= 10 THEN DATE_TRUNC('year', months.work_month)::date + INTERVAL '9 months' ELSE DATE_TRUNC('year', months.work_month)::date - INTERVAL '3 months' END + INTERVAL '1 year' - INTERVAL '1 day')) AND (e.emp_resign_enddate IS NULL OR e.emp_resign_enddate >= (CASE WHEN EXTRACT(MONTH FROM months.work_month) >= 10 THEN DATE_TRUNC('year', months.work_month)::date + INTERVAL '9 months' ELSE DATE_TRUNC('year', months.work_month)::date - INTERVAL '3 months' END + INTERVAL '1 year' - INTERVAL '1 day'))) AS active_at_fy_end
            FROM emp e
            LEFT JOIN emp_position_main pm ON pm.emp_position_main_id = e.emp_position_main_id
            JOIN GENERATE_SERIES(
              DATE_TRUNC('month', GREATEST(COALESCE(e.emp_work_begindate, (SELECT fy_start FROM thip_params)), (SELECT fy_start FROM thip_params))),
              DATE_TRUNC('month', LEAST(COALESCE(e.emp_resign_enddate, (SELECT fy_end FROM thip_params)), (SELECT fy_end FROM thip_params)) - INTERVAL '1 day'),
              INTERVAL '1 month'
            ) AS months(work_month) ON TRUE
          ) hr
          WHERE TRUE
          GROUP BY 2, 3, 4
          ), expected_codes(indicator_code, fiscal_month, indicator_name_th, indicator_name_en) AS (
            VALUES
              ('SH0101', 1, U&'\0E2D\0E31\0E15\0E23\0E32\0E01\0E32\0E23\0E25\0E32\0E2D\0E2D\0E01\0E02\0E2D\0E07\0E1A\0E38\0E04\0E25\0E32\0E01\0E23', 'HRM: Turnover tate')
          ), fiscal_periods AS (
            SELECT
              generated.period_start::date AS period_start,
              CASE
                WHEN EXTRACT(MONTH FROM generated.period_start) >= 10
                  THEN EXTRACT(MONTH FROM generated.period_start)::integer - 9
                ELSE EXTRACT(MONTH FROM generated.period_start)::integer + 3
              END AS fiscal_month,
              CASE
                WHEN EXTRACT(MONTH FROM generated.period_start) >= 10
                  THEN EXTRACT(YEAR FROM generated.period_start)::integer + 1
                ELSE EXTRACT(YEAR FROM generated.period_start)::integer
              END AS fiscal_year
            FROM generate_series(
              CAST((SELECT fy_start FROM thip_params) AS date),
              CAST((SELECT fy_end FROM thip_params) AS date) - INTERVAL '1 month',
              INTERVAL '1 month'
            ) AS generated(period_start)
          )
          SELECT
            expected_codes.indicator_code,
            expected_codes.indicator_name_th AS indicator_name_th,
            expected_codes.indicator_name_en AS indicator_name_en,
            fiscal_periods.period_start,
            fiscal_periods.fiscal_month,
            fiscal_periods.fiscal_year,
            COALESCE(facts.numerator, 0) AS numerator,
            COALESCE(facts.denominator, 0) AS denominator,
            facts.value
          FROM expected_codes
          JOIN fiscal_periods
            ON fiscal_periods.fiscal_month = expected_codes.fiscal_month
          LEFT JOIN facts
            ON facts.indicator_code = expected_codes.indicator_code
           AND facts.period_start = fiscal_periods.period_start
           AND facts.fiscal_month = fiscal_periods.fiscal_month
           AND facts.fiscal_year = fiscal_periods.fiscal_year
          ORDER BY expected_codes.indicator_code, fiscal_periods.period_start
  ) AS b_SH0101
  UNION ALL
  SELECT * FROM (
    WITH
          ipd AS (
        SELECT
          i.an,
          i.hn,
          i.regdate,
          i.regtime,
          i.dchdate,
          COALESCE(i.bw, 0) AS bw,
          s.age_y,
          s.los,
          REPLACE(UPPER(TRIM(s.pdx)), '.', '') AS pdx,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
          ) AS died,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') <> REPLACE(UPPER(TRIM(s.pdx)), '.', '')
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
          ) AS has_acs_sdx,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
              AND (
                REPLACE(UPPER(TRIM(d.death_diag_icd10)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_cause)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_1)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_2)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_3)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_4)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
              )
          ) AS died_from_acs,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') <> REPLACE(UPPER(TRIM(s.pdx)), '.', '')
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
          ) AS has_stemi_sdx,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') <> REPLACE(UPPER(TRIM(s.pdx)), '.', '')
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') IN ('I214', 'I219')
          ) AS has_nste_sdx,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
              AND d.death_date IS NOT NULL
              AND (d.death_date + COALESCE(d.death_time, TIME '23:59:59')) >=
                (i.regdate + COALESCE(i.regtime, TIME '00:00:00'))
              AND (d.death_date + COALESCE(d.death_time, TIME '23:59:59')) <=
                (i.regdate + COALESCE(i.regtime, TIME '00:00:00')) + INTERVAL '48 hours'
          ) AS died_within_48h,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
              AND (
                REPLACE(UPPER(TRIM(d.death_diag_icd10)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
                OR REPLACE(UPPER(TRIM(d.death_cause)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
                OR REPLACE(UPPER(TRIM(d.death_diag_1)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
                OR REPLACE(UPPER(TRIM(d.death_diag_2)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
                OR REPLACE(UPPER(TRIM(d.death_diag_3)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
                OR REPLACE(UPPER(TRIM(d.death_diag_4)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
              )
          ) AS died_from_stemi,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
              AND (
                REPLACE(UPPER(TRIM(d.death_diag_icd10)), '.', '') IN ('I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_cause)), '.', '') IN ('I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_1)), '.', '') IN ('I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_2)), '.', '') IN ('I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_3)), '.', '') IN ('I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_4)), '.', '') IN ('I214', 'I219')
              )
          ) AS died_from_nste,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') <> REPLACE(UPPER(TRIM(s.pdx)), '.', '')
              AND (
                LEFT(REPLACE(UPPER(TRIM(sd.icd10)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(sd.icd10)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
              )
          ) AS has_pneumonia_sdx,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
              AND (
                LEFT(REPLACE(UPPER(TRIM(d.death_diag_icd10)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_icd10)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_cause)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_cause)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_1)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_1)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_2)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_2)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_3)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_3)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_4)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_4)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
              )
          ) AS died_from_pneumonia,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') IN ('A400', 'A419', 'R572', 'R651')
          ) AS has_ce0101_sepsis,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') IN ('A400', 'A409', 'A410', 'A419', 'R572', 'R651')
          ) AS has_ci0101_sepsis
        FROM ipt i
        JOIN an_stat s ON s.an = i.an
        WHERE i.dchdate >= (SELECT fy_start FROM thip_params)
          AND i.dchdate < (SELECT fy_end FROM thip_params)
          AND i.regdate IS NOT NULL
          AND EXTRACT(EPOCH FROM (
            (i.dchdate + COALESCE(i.dchtime, TIME '23:59:59')) -
            (i.regdate + COALESCE(i.regtime, TIME '00:00:00'))
          )) >= 14400
      ),
      periodized AS (
        SELECT
          *,
          DATE_TRUNC('month', dchdate)::date AS period_start,
          EXTRACT(MONTH FROM dchdate)::integer AS calendar_month
        FROM ipd
      ),
          opd_periodized AS (
        SELECT
          v.vn,
          v.hn,
          v.an,
          EXTRACT(YEAR FROM AGE(v.vstdate, pd.birthday))::integer AS age_y,
          pd.sex,
          (SELECT REPLACE(UPPER(TRIM(sd.icd10)), '.', '')
             FROM ovstdiag sd
            WHERE sd.vn = v.vn AND sd.diagtype = '1'
            ORDER BY sd.ovst_diag_id
            LIMIT 1) AS pdx,
          v.vstdate AS event_date,
          er.enter_er_time,
          er.triage_datetime,
          er.doctor_tx_time,
          er.finish_time,
          er.antibiotics_datetime,
          er.stroke_needle_datetime,
          er.stemi_balloon_datetime,
          er.er_emergency_level_id,
          er.unplanned_return,
          er.news2_score,
          DATE_TRUNC('month', v.vstdate)::date AS period_start,
          EXTRACT(MONTH FROM v.vstdate)::integer AS calendar_month
        FROM ovst v
        LEFT JOIN patient pd ON pd.hn = v.hn
        LEFT JOIN er_regist er ON er.vn = v.vn
        WHERE v.vstdate >= (SELECT fy_start FROM thip_params)
          AND v.vstdate < (SELECT fy_end FROM thip_params)
      ),
      chronic_periodized AS (
        SELECT
          cm.clinicmember_id,
          cm.clinic,
          cm.hn,
          cm.regdate,
          cm.lastvisit,
          cm.dchdate,
          cm.current_status,
          cm.clinic_member_status_id,
          cm.age_y,
          cm.sex,
          cm.chronic_type,
          cm.begin_year,
          cm.last_hba1c_value,
          cm.last_hba1c_date,
          cm.last_bp_bps_value,
          cm.last_bp_bpd_value,
          cm.last_bp_date,
          DATE_TRUNC('month', cm.regdate)::date AS period_start,
          EXTRACT(MONTH FROM cm.regdate)::integer AS calendar_month
        FROM clinicmember cm
        WHERE cm.regdate >= (SELECT fy_start FROM thip_params)
          AND cm.regdate < (SELECT fy_end FROM thip_params)
      ),
      delivery_periodized AS (
        SELECT
          l.laborid,
          l.an,
          l.hage AS mother_age_y,
          l.labor_type,
          l.mother_method,
          l.infant_sex,
          l.infant_weight,
          l.infant_apgarscore1,
          l.infant_apgarscore5,
          l.infant_apgarscore10,
          l.placenta_bloodloss,
          l.labour_startdate,
          l.labour_finishdate,
          DATE_TRUNC('month', COALESCE(l.labour_startdate, i.regdate))::date AS period_start,
          EXTRACT(MONTH FROM COALESCE(l.labour_startdate, i.regdate))::integer AS calendar_month
        FROM labor l
        LEFT JOIN ipt i ON i.an = l.an
        WHERE COALESCE(l.labour_startdate, i.regdate) >= (SELECT fy_start FROM thip_params)
          AND COALESCE(l.labour_startdate, i.regdate) < (SELECT fy_end FROM thip_params)
      ),
      newborn_periodized AS (
        SELECT
          nb.an,
          nb.mother_an,
          nb.born_date,
          nb.birth_weight,
          nb.apgar1,
          nb.apgar2,
          nb.dead,
          nb.has_asphyxia,
          nb.birthcondition1,
          nb.birthcondition2,
          nb.anc_complete,
          DATE_TRUNC('month', nb.born_date)::date AS period_start,
          EXTRACT(MONTH FROM nb.born_date)::integer AS calendar_month
        FROM ipt_newborn nb
        WHERE nb.born_date >= (SELECT fy_start FROM thip_params)
          AND nb.born_date < (SELECT fy_end FROM thip_params)
      ),
      emp_periodized AS (
        SELECT
          e.emp_id,
          e.emp_sex_id,
          e.emp_birthdate,
          e.emp_status_id,
          e.emp_type_id,
          e.emp_dep_id,
          e.emp_position_main_id,
          e.emp_work_begindate,
          e.emp_resign_enddate,
          e.emp_resign_type_id,
          DATE_TRUNC('month', e.emp_work_begindate)::date AS period_start,
          EXTRACT(MONTH FROM e.emp_work_begindate)::integer AS calendar_month
        FROM emp e
        WHERE e.emp_work_begindate >= (SELECT fy_start FROM thip_params)
          AND e.emp_work_begindate < (SELECT fy_end FROM thip_params)
      ),
          facts AS (
      
          SELECT
            'SH0102' AS indicator_code,
            DATE_TRUNC('month', period_start)::date - MAKE_INTERVAL(months => (CASE WHEN calendar_month >= 10 THEN calendar_month - 9 ELSE calendar_month + 3 END) - (1)) AS period_start,
            1 AS fiscal_month,
            CASE WHEN calendar_month >= 10 THEN EXTRACT(YEAR FROM period_start)::integer + 1 ELSE EXTRACT(YEAR FROM period_start)::integer END AS fiscal_year,
            SUM(hr.work_injury_event_cnt) AS numerator,
            (COUNT(DISTINCT hr.staff_key) FILTER (WHERE hr.active_at_fy_start) + COUNT(DISTINCT hr.staff_key) FILTER (WHERE hr.active_at_fy_end)) / NULLIF(2, 0) AS denominator,
            ROUND((SUM(hr.work_injury_event_cnt)) * 100 / NULLIF((COUNT(DISTINCT hr.staff_key) FILTER (WHERE hr.active_at_fy_start) + COUNT(DISTINCT hr.staff_key) FILTER (WHERE hr.active_at_fy_end)) / NULLIF(2, 0), 0), 2) AS value
          FROM (
            SELECT
              e.emp_id AS staff_key,
              DATE_TRUNC('month', months.work_month)::date AS period_start,
              EXTRACT(MONTH FROM months.work_month)::integer AS calendar_month,
              (SELECT COUNT(*)
                FROM emp_work_sick es
                JOIN emp_work_sick_type st ON st.emp_work_sick_type_id = es.emp_work_sick_type_id
                WHERE es.emp_id = e.emp_id
                  AND es.emp_work_sick_sdatetime >= months.work_month
                  AND es.emp_work_sick_sdatetime < months.work_month + INTERVAL '1 month'
                  AND (st.emp_work_sick_type_name ILIKE U&'%\0E2D\0E31\0E19\0E15\0E23\0E32\0E22%' OR st.emp_work_sick_type_name ILIKE U&'%\0E1A\0E32\0E14\0E40\0E08\0E47\0E1A%' OR st.emp_work_sick_type_name ILIKE U&'%\0E2D\0E38\0E1A\0E31\0E15\0E34\0E40\0E2B\0E15\0E38%')) AS work_injury_event_cnt,
              ((e.emp_work_begindate IS NULL OR e.emp_work_begindate <= CASE WHEN EXTRACT(MONTH FROM months.work_month) >= 10 THEN DATE_TRUNC('year', months.work_month)::date + INTERVAL '9 months' ELSE DATE_TRUNC('year', months.work_month)::date - INTERVAL '3 months' END) AND (e.emp_resign_enddate IS NULL OR e.emp_resign_enddate >= CASE WHEN EXTRACT(MONTH FROM months.work_month) >= 10 THEN DATE_TRUNC('year', months.work_month)::date + INTERVAL '9 months' ELSE DATE_TRUNC('year', months.work_month)::date - INTERVAL '3 months' END)) AS active_at_fy_start,
              ((e.emp_work_begindate IS NULL OR e.emp_work_begindate <= (CASE WHEN EXTRACT(MONTH FROM months.work_month) >= 10 THEN DATE_TRUNC('year', months.work_month)::date + INTERVAL '9 months' ELSE DATE_TRUNC('year', months.work_month)::date - INTERVAL '3 months' END + INTERVAL '1 year' - INTERVAL '1 day')) AND (e.emp_resign_enddate IS NULL OR e.emp_resign_enddate >= (CASE WHEN EXTRACT(MONTH FROM months.work_month) >= 10 THEN DATE_TRUNC('year', months.work_month)::date + INTERVAL '9 months' ELSE DATE_TRUNC('year', months.work_month)::date - INTERVAL '3 months' END + INTERVAL '1 year' - INTERVAL '1 day'))) AS active_at_fy_end
            FROM emp e
            LEFT JOIN emp_position_main pm ON pm.emp_position_main_id = e.emp_position_main_id
            JOIN GENERATE_SERIES(
              DATE_TRUNC('month', GREATEST(COALESCE(e.emp_work_begindate, (SELECT fy_start FROM thip_params)), (SELECT fy_start FROM thip_params))),
              DATE_TRUNC('month', LEAST(COALESCE(e.emp_resign_enddate, (SELECT fy_end FROM thip_params)), (SELECT fy_end FROM thip_params)) - INTERVAL '1 day'),
              INTERVAL '1 month'
            ) AS months(work_month) ON TRUE
          ) hr
          WHERE TRUE
          GROUP BY 2, 3, 4
          ), expected_codes(indicator_code, fiscal_month, indicator_name_th, indicator_name_en) AS (
            VALUES
              ('SH0102', 1, U&'\0E23\0E49\0E2D\0E22\0E25\0E30\0E1A\0E38\0E04\0E25\0E32\0E01\0E23\0E17\0E35\0E48\0E1A\0E32\0E14\0E40\0E08\0E47\0E1A\0E08\0E32\0E01\0E01\0E32\0E23\0E17\0E33\0E07\0E32\0E19', 'HRM: Percent of employee work-related Injury')
          ), fiscal_periods AS (
            SELECT
              generated.period_start::date AS period_start,
              CASE
                WHEN EXTRACT(MONTH FROM generated.period_start) >= 10
                  THEN EXTRACT(MONTH FROM generated.period_start)::integer - 9
                ELSE EXTRACT(MONTH FROM generated.period_start)::integer + 3
              END AS fiscal_month,
              CASE
                WHEN EXTRACT(MONTH FROM generated.period_start) >= 10
                  THEN EXTRACT(YEAR FROM generated.period_start)::integer + 1
                ELSE EXTRACT(YEAR FROM generated.period_start)::integer
              END AS fiscal_year
            FROM generate_series(
              CAST((SELECT fy_start FROM thip_params) AS date),
              CAST((SELECT fy_end FROM thip_params) AS date) - INTERVAL '1 month',
              INTERVAL '1 month'
            ) AS generated(period_start)
          )
          SELECT
            expected_codes.indicator_code,
            expected_codes.indicator_name_th AS indicator_name_th,
            expected_codes.indicator_name_en AS indicator_name_en,
            fiscal_periods.period_start,
            fiscal_periods.fiscal_month,
            fiscal_periods.fiscal_year,
            COALESCE(facts.numerator, 0) AS numerator,
            COALESCE(facts.denominator, 0) AS denominator,
            facts.value
          FROM expected_codes
          JOIN fiscal_periods
            ON fiscal_periods.fiscal_month = expected_codes.fiscal_month
          LEFT JOIN facts
            ON facts.indicator_code = expected_codes.indicator_code
           AND facts.period_start = fiscal_periods.period_start
           AND facts.fiscal_month = fiscal_periods.fiscal_month
           AND facts.fiscal_year = fiscal_periods.fiscal_year
          ORDER BY expected_codes.indicator_code, fiscal_periods.period_start
  ) AS b_SH0102
  UNION ALL
  SELECT * FROM (
    WITH
          ipd AS (
        SELECT
          i.an,
          i.hn,
          i.regdate,
          i.regtime,
          i.dchdate,
          COALESCE(i.bw, 0) AS bw,
          s.age_y,
          s.los,
          REPLACE(UPPER(TRIM(s.pdx)), '.', '') AS pdx,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
          ) AS died,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') <> REPLACE(UPPER(TRIM(s.pdx)), '.', '')
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
          ) AS has_acs_sdx,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
              AND (
                REPLACE(UPPER(TRIM(d.death_diag_icd10)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_cause)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_1)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_2)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_3)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_4)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
              )
          ) AS died_from_acs,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') <> REPLACE(UPPER(TRIM(s.pdx)), '.', '')
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
          ) AS has_stemi_sdx,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') <> REPLACE(UPPER(TRIM(s.pdx)), '.', '')
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') IN ('I214', 'I219')
          ) AS has_nste_sdx,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
              AND d.death_date IS NOT NULL
              AND (d.death_date + COALESCE(d.death_time, TIME '23:59:59')) >=
                (i.regdate + COALESCE(i.regtime, TIME '00:00:00'))
              AND (d.death_date + COALESCE(d.death_time, TIME '23:59:59')) <=
                (i.regdate + COALESCE(i.regtime, TIME '00:00:00')) + INTERVAL '48 hours'
          ) AS died_within_48h,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
              AND (
                REPLACE(UPPER(TRIM(d.death_diag_icd10)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
                OR REPLACE(UPPER(TRIM(d.death_cause)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
                OR REPLACE(UPPER(TRIM(d.death_diag_1)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
                OR REPLACE(UPPER(TRIM(d.death_diag_2)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
                OR REPLACE(UPPER(TRIM(d.death_diag_3)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
                OR REPLACE(UPPER(TRIM(d.death_diag_4)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
              )
          ) AS died_from_stemi,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
              AND (
                REPLACE(UPPER(TRIM(d.death_diag_icd10)), '.', '') IN ('I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_cause)), '.', '') IN ('I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_1)), '.', '') IN ('I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_2)), '.', '') IN ('I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_3)), '.', '') IN ('I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_4)), '.', '') IN ('I214', 'I219')
              )
          ) AS died_from_nste,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') <> REPLACE(UPPER(TRIM(s.pdx)), '.', '')
              AND (
                LEFT(REPLACE(UPPER(TRIM(sd.icd10)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(sd.icd10)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
              )
          ) AS has_pneumonia_sdx,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
              AND (
                LEFT(REPLACE(UPPER(TRIM(d.death_diag_icd10)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_icd10)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_cause)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_cause)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_1)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_1)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_2)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_2)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_3)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_3)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_4)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_4)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
              )
          ) AS died_from_pneumonia,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') IN ('A400', 'A419', 'R572', 'R651')
          ) AS has_ce0101_sepsis,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') IN ('A400', 'A409', 'A410', 'A419', 'R572', 'R651')
          ) AS has_ci0101_sepsis
        FROM ipt i
        JOIN an_stat s ON s.an = i.an
        WHERE i.dchdate >= (SELECT fy_start FROM thip_params)
          AND i.dchdate < (SELECT fy_end FROM thip_params)
          AND i.regdate IS NOT NULL
          AND EXTRACT(EPOCH FROM (
            (i.dchdate + COALESCE(i.dchtime, TIME '23:59:59')) -
            (i.regdate + COALESCE(i.regtime, TIME '00:00:00'))
          )) >= 14400
      ),
      periodized AS (
        SELECT
          *,
          DATE_TRUNC('month', dchdate)::date AS period_start,
          EXTRACT(MONTH FROM dchdate)::integer AS calendar_month
        FROM ipd
      ),
          opd_periodized AS (
        SELECT
          v.vn,
          v.hn,
          v.an,
          EXTRACT(YEAR FROM AGE(v.vstdate, pd.birthday))::integer AS age_y,
          pd.sex,
          (SELECT REPLACE(UPPER(TRIM(sd.icd10)), '.', '')
             FROM ovstdiag sd
            WHERE sd.vn = v.vn AND sd.diagtype = '1'
            ORDER BY sd.ovst_diag_id
            LIMIT 1) AS pdx,
          v.vstdate AS event_date,
          er.enter_er_time,
          er.triage_datetime,
          er.doctor_tx_time,
          er.finish_time,
          er.antibiotics_datetime,
          er.stroke_needle_datetime,
          er.stemi_balloon_datetime,
          er.er_emergency_level_id,
          er.unplanned_return,
          er.news2_score,
          DATE_TRUNC('month', v.vstdate)::date AS period_start,
          EXTRACT(MONTH FROM v.vstdate)::integer AS calendar_month
        FROM ovst v
        LEFT JOIN patient pd ON pd.hn = v.hn
        LEFT JOIN er_regist er ON er.vn = v.vn
        WHERE v.vstdate >= (SELECT fy_start FROM thip_params)
          AND v.vstdate < (SELECT fy_end FROM thip_params)
      ),
      chronic_periodized AS (
        SELECT
          cm.clinicmember_id,
          cm.clinic,
          cm.hn,
          cm.regdate,
          cm.lastvisit,
          cm.dchdate,
          cm.current_status,
          cm.clinic_member_status_id,
          cm.age_y,
          cm.sex,
          cm.chronic_type,
          cm.begin_year,
          cm.last_hba1c_value,
          cm.last_hba1c_date,
          cm.last_bp_bps_value,
          cm.last_bp_bpd_value,
          cm.last_bp_date,
          DATE_TRUNC('month', cm.regdate)::date AS period_start,
          EXTRACT(MONTH FROM cm.regdate)::integer AS calendar_month
        FROM clinicmember cm
        WHERE cm.regdate >= (SELECT fy_start FROM thip_params)
          AND cm.regdate < (SELECT fy_end FROM thip_params)
      ),
      delivery_periodized AS (
        SELECT
          l.laborid,
          l.an,
          l.hage AS mother_age_y,
          l.labor_type,
          l.mother_method,
          l.infant_sex,
          l.infant_weight,
          l.infant_apgarscore1,
          l.infant_apgarscore5,
          l.infant_apgarscore10,
          l.placenta_bloodloss,
          l.labour_startdate,
          l.labour_finishdate,
          DATE_TRUNC('month', COALESCE(l.labour_startdate, i.regdate))::date AS period_start,
          EXTRACT(MONTH FROM COALESCE(l.labour_startdate, i.regdate))::integer AS calendar_month
        FROM labor l
        LEFT JOIN ipt i ON i.an = l.an
        WHERE COALESCE(l.labour_startdate, i.regdate) >= (SELECT fy_start FROM thip_params)
          AND COALESCE(l.labour_startdate, i.regdate) < (SELECT fy_end FROM thip_params)
      ),
      newborn_periodized AS (
        SELECT
          nb.an,
          nb.mother_an,
          nb.born_date,
          nb.birth_weight,
          nb.apgar1,
          nb.apgar2,
          nb.dead,
          nb.has_asphyxia,
          nb.birthcondition1,
          nb.birthcondition2,
          nb.anc_complete,
          DATE_TRUNC('month', nb.born_date)::date AS period_start,
          EXTRACT(MONTH FROM nb.born_date)::integer AS calendar_month
        FROM ipt_newborn nb
        WHERE nb.born_date >= (SELECT fy_start FROM thip_params)
          AND nb.born_date < (SELECT fy_end FROM thip_params)
      ),
      emp_periodized AS (
        SELECT
          e.emp_id,
          e.emp_sex_id,
          e.emp_birthdate,
          e.emp_status_id,
          e.emp_type_id,
          e.emp_dep_id,
          e.emp_position_main_id,
          e.emp_work_begindate,
          e.emp_resign_enddate,
          e.emp_resign_type_id,
          DATE_TRUNC('month', e.emp_work_begindate)::date AS period_start,
          EXTRACT(MONTH FROM e.emp_work_begindate)::integer AS calendar_month
        FROM emp e
        WHERE e.emp_work_begindate >= (SELECT fy_start FROM thip_params)
          AND e.emp_work_begindate < (SELECT fy_end FROM thip_params)
      ),
          facts AS (
      
          SELECT
            'SH0103' AS indicator_code,
            DATE_TRUNC('month', period_start)::date - MAKE_INTERVAL(months => (CASE WHEN calendar_month >= 10 THEN calendar_month - 9 ELSE calendar_month + 3 END) - (1)) AS period_start,
            1 AS fiscal_month,
            CASE WHEN calendar_month >= 10 THEN EXTRACT(YEAR FROM period_start)::integer + 1 ELSE EXTRACT(YEAR FROM period_start)::integer END AS fiscal_year,
            SUM(hr.work_illness_event_cnt) AS numerator,
            (COUNT(DISTINCT hr.staff_key) FILTER (WHERE hr.active_at_fy_start) + COUNT(DISTINCT hr.staff_key) FILTER (WHERE hr.active_at_fy_end)) / NULLIF(2, 0) AS denominator,
            ROUND((SUM(hr.work_illness_event_cnt)) * 100 / NULLIF((COUNT(DISTINCT hr.staff_key) FILTER (WHERE hr.active_at_fy_start) + COUNT(DISTINCT hr.staff_key) FILTER (WHERE hr.active_at_fy_end)) / NULLIF(2, 0), 0), 2) AS value
          FROM (
            SELECT
              e.emp_id AS staff_key,
              DATE_TRUNC('month', months.work_month)::date AS period_start,
              EXTRACT(MONTH FROM months.work_month)::integer AS calendar_month,
              (SELECT COUNT(*)
                FROM emp_work_sick es
                JOIN emp_work_sick_type st ON st.emp_work_sick_type_id = es.emp_work_sick_type_id
                WHERE es.emp_id = e.emp_id
                  AND es.emp_work_sick_sdatetime >= months.work_month
                  AND es.emp_work_sick_sdatetime < months.work_month + INTERVAL '1 month'
                  AND (st.emp_work_sick_type_name ILIKE U&'%\0E40\0E08\0E47\0E1A\0E1B\0E48\0E27\0E22%' OR st.emp_work_sick_type_name ILIKE U&'%\0E1B\0E27\0E14\0E2B\0E25\0E31\0E07%' OR st.emp_work_sick_type_name ILIKE U&'%\0E40\0E04\0E23\0E35\0E22\0E14%' OR st.emp_work_sick_type_name ILIKE U&'%\0E42\0E23\0E04\0E08\0E32\0E01\0E01\0E32\0E23\0E17\0E33\0E07\0E32\0E19%')) AS work_illness_event_cnt,
              ((e.emp_work_begindate IS NULL OR e.emp_work_begindate <= CASE WHEN EXTRACT(MONTH FROM months.work_month) >= 10 THEN DATE_TRUNC('year', months.work_month)::date + INTERVAL '9 months' ELSE DATE_TRUNC('year', months.work_month)::date - INTERVAL '3 months' END) AND (e.emp_resign_enddate IS NULL OR e.emp_resign_enddate >= CASE WHEN EXTRACT(MONTH FROM months.work_month) >= 10 THEN DATE_TRUNC('year', months.work_month)::date + INTERVAL '9 months' ELSE DATE_TRUNC('year', months.work_month)::date - INTERVAL '3 months' END)) AS active_at_fy_start,
              ((e.emp_work_begindate IS NULL OR e.emp_work_begindate <= (CASE WHEN EXTRACT(MONTH FROM months.work_month) >= 10 THEN DATE_TRUNC('year', months.work_month)::date + INTERVAL '9 months' ELSE DATE_TRUNC('year', months.work_month)::date - INTERVAL '3 months' END + INTERVAL '1 year' - INTERVAL '1 day')) AND (e.emp_resign_enddate IS NULL OR e.emp_resign_enddate >= (CASE WHEN EXTRACT(MONTH FROM months.work_month) >= 10 THEN DATE_TRUNC('year', months.work_month)::date + INTERVAL '9 months' ELSE DATE_TRUNC('year', months.work_month)::date - INTERVAL '3 months' END + INTERVAL '1 year' - INTERVAL '1 day'))) AS active_at_fy_end
            FROM emp e
            LEFT JOIN emp_position_main pm ON pm.emp_position_main_id = e.emp_position_main_id
            JOIN GENERATE_SERIES(
              DATE_TRUNC('month', GREATEST(COALESCE(e.emp_work_begindate, (SELECT fy_start FROM thip_params)), (SELECT fy_start FROM thip_params))),
              DATE_TRUNC('month', LEAST(COALESCE(e.emp_resign_enddate, (SELECT fy_end FROM thip_params)), (SELECT fy_end FROM thip_params)) - INTERVAL '1 day'),
              INTERVAL '1 month'
            ) AS months(work_month) ON TRUE
          ) hr
          WHERE TRUE
          GROUP BY 2, 3, 4
          ), expected_codes(indicator_code, fiscal_month, indicator_name_th, indicator_name_en) AS (
            VALUES
              ('SH0103', 1, U&'\0E23\0E49\0E2D\0E22\0E25\0E30\0E1A\0E38\0E04\0E25\0E32\0E01\0E23\0E17\0E35\0E48\0E40\0E08\0E47\0E1A\0E1B\0E48\0E27\0E22\0E08\0E32\0E01\0E01\0E32\0E23\0E17\0E33\0E07\0E32\0E19', 'HRM: Percent of employee work-related Illness')
          ), fiscal_periods AS (
            SELECT
              generated.period_start::date AS period_start,
              CASE
                WHEN EXTRACT(MONTH FROM generated.period_start) >= 10
                  THEN EXTRACT(MONTH FROM generated.period_start)::integer - 9
                ELSE EXTRACT(MONTH FROM generated.period_start)::integer + 3
              END AS fiscal_month,
              CASE
                WHEN EXTRACT(MONTH FROM generated.period_start) >= 10
                  THEN EXTRACT(YEAR FROM generated.period_start)::integer + 1
                ELSE EXTRACT(YEAR FROM generated.period_start)::integer
              END AS fiscal_year
            FROM generate_series(
              CAST((SELECT fy_start FROM thip_params) AS date),
              CAST((SELECT fy_end FROM thip_params) AS date) - INTERVAL '1 month',
              INTERVAL '1 month'
            ) AS generated(period_start)
          )
          SELECT
            expected_codes.indicator_code,
            expected_codes.indicator_name_th AS indicator_name_th,
            expected_codes.indicator_name_en AS indicator_name_en,
            fiscal_periods.period_start,
            fiscal_periods.fiscal_month,
            fiscal_periods.fiscal_year,
            COALESCE(facts.numerator, 0) AS numerator,
            COALESCE(facts.denominator, 0) AS denominator,
            facts.value
          FROM expected_codes
          JOIN fiscal_periods
            ON fiscal_periods.fiscal_month = expected_codes.fiscal_month
          LEFT JOIN facts
            ON facts.indicator_code = expected_codes.indicator_code
           AND facts.period_start = fiscal_periods.period_start
           AND facts.fiscal_month = fiscal_periods.fiscal_month
           AND facts.fiscal_year = fiscal_periods.fiscal_year
          ORDER BY expected_codes.indicator_code, fiscal_periods.period_start
  ) AS b_SH0103
  UNION ALL
  SELECT * FROM (
    WITH
          ipd AS (
        SELECT
          i.an,
          i.hn,
          i.regdate,
          i.regtime,
          i.dchdate,
          COALESCE(i.bw, 0) AS bw,
          s.age_y,
          s.los,
          REPLACE(UPPER(TRIM(s.pdx)), '.', '') AS pdx,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
          ) AS died,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') <> REPLACE(UPPER(TRIM(s.pdx)), '.', '')
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
          ) AS has_acs_sdx,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
              AND (
                REPLACE(UPPER(TRIM(d.death_diag_icd10)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_cause)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_1)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_2)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_3)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_4)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
              )
          ) AS died_from_acs,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') <> REPLACE(UPPER(TRIM(s.pdx)), '.', '')
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
          ) AS has_stemi_sdx,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') <> REPLACE(UPPER(TRIM(s.pdx)), '.', '')
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') IN ('I214', 'I219')
          ) AS has_nste_sdx,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
              AND d.death_date IS NOT NULL
              AND (d.death_date + COALESCE(d.death_time, TIME '23:59:59')) >=
                (i.regdate + COALESCE(i.regtime, TIME '00:00:00'))
              AND (d.death_date + COALESCE(d.death_time, TIME '23:59:59')) <=
                (i.regdate + COALESCE(i.regtime, TIME '00:00:00')) + INTERVAL '48 hours'
          ) AS died_within_48h,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
              AND (
                REPLACE(UPPER(TRIM(d.death_diag_icd10)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
                OR REPLACE(UPPER(TRIM(d.death_cause)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
                OR REPLACE(UPPER(TRIM(d.death_diag_1)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
                OR REPLACE(UPPER(TRIM(d.death_diag_2)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
                OR REPLACE(UPPER(TRIM(d.death_diag_3)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
                OR REPLACE(UPPER(TRIM(d.death_diag_4)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
              )
          ) AS died_from_stemi,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
              AND (
                REPLACE(UPPER(TRIM(d.death_diag_icd10)), '.', '') IN ('I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_cause)), '.', '') IN ('I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_1)), '.', '') IN ('I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_2)), '.', '') IN ('I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_3)), '.', '') IN ('I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_4)), '.', '') IN ('I214', 'I219')
              )
          ) AS died_from_nste,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') <> REPLACE(UPPER(TRIM(s.pdx)), '.', '')
              AND (
                LEFT(REPLACE(UPPER(TRIM(sd.icd10)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(sd.icd10)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
              )
          ) AS has_pneumonia_sdx,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
              AND (
                LEFT(REPLACE(UPPER(TRIM(d.death_diag_icd10)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_icd10)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_cause)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_cause)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_1)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_1)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_2)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_2)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_3)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_3)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_4)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_4)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
              )
          ) AS died_from_pneumonia,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') IN ('A400', 'A419', 'R572', 'R651')
          ) AS has_ce0101_sepsis,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') IN ('A400', 'A409', 'A410', 'A419', 'R572', 'R651')
          ) AS has_ci0101_sepsis
        FROM ipt i
        JOIN an_stat s ON s.an = i.an
        WHERE i.dchdate >= (SELECT fy_start FROM thip_params)
          AND i.dchdate < (SELECT fy_end FROM thip_params)
          AND i.regdate IS NOT NULL
          AND EXTRACT(EPOCH FROM (
            (i.dchdate + COALESCE(i.dchtime, TIME '23:59:59')) -
            (i.regdate + COALESCE(i.regtime, TIME '00:00:00'))
          )) >= 14400
      ),
      periodized AS (
        SELECT
          *,
          DATE_TRUNC('month', dchdate)::date AS period_start,
          EXTRACT(MONTH FROM dchdate)::integer AS calendar_month
        FROM ipd
      ),
          opd_periodized AS (
        SELECT
          v.vn,
          v.hn,
          v.an,
          EXTRACT(YEAR FROM AGE(v.vstdate, pd.birthday))::integer AS age_y,
          pd.sex,
          (SELECT REPLACE(UPPER(TRIM(sd.icd10)), '.', '')
             FROM ovstdiag sd
            WHERE sd.vn = v.vn AND sd.diagtype = '1'
            ORDER BY sd.ovst_diag_id
            LIMIT 1) AS pdx,
          v.vstdate AS event_date,
          er.enter_er_time,
          er.triage_datetime,
          er.doctor_tx_time,
          er.finish_time,
          er.antibiotics_datetime,
          er.stroke_needle_datetime,
          er.stemi_balloon_datetime,
          er.er_emergency_level_id,
          er.unplanned_return,
          er.news2_score,
          DATE_TRUNC('month', v.vstdate)::date AS period_start,
          EXTRACT(MONTH FROM v.vstdate)::integer AS calendar_month
        FROM ovst v
        LEFT JOIN patient pd ON pd.hn = v.hn
        LEFT JOIN er_regist er ON er.vn = v.vn
        WHERE v.vstdate >= (SELECT fy_start FROM thip_params)
          AND v.vstdate < (SELECT fy_end FROM thip_params)
      ),
      chronic_periodized AS (
        SELECT
          cm.clinicmember_id,
          cm.clinic,
          cm.hn,
          cm.regdate,
          cm.lastvisit,
          cm.dchdate,
          cm.current_status,
          cm.clinic_member_status_id,
          cm.age_y,
          cm.sex,
          cm.chronic_type,
          cm.begin_year,
          cm.last_hba1c_value,
          cm.last_hba1c_date,
          cm.last_bp_bps_value,
          cm.last_bp_bpd_value,
          cm.last_bp_date,
          DATE_TRUNC('month', cm.regdate)::date AS period_start,
          EXTRACT(MONTH FROM cm.regdate)::integer AS calendar_month
        FROM clinicmember cm
        WHERE cm.regdate >= (SELECT fy_start FROM thip_params)
          AND cm.regdate < (SELECT fy_end FROM thip_params)
      ),
      delivery_periodized AS (
        SELECT
          l.laborid,
          l.an,
          l.hage AS mother_age_y,
          l.labor_type,
          l.mother_method,
          l.infant_sex,
          l.infant_weight,
          l.infant_apgarscore1,
          l.infant_apgarscore5,
          l.infant_apgarscore10,
          l.placenta_bloodloss,
          l.labour_startdate,
          l.labour_finishdate,
          DATE_TRUNC('month', COALESCE(l.labour_startdate, i.regdate))::date AS period_start,
          EXTRACT(MONTH FROM COALESCE(l.labour_startdate, i.regdate))::integer AS calendar_month
        FROM labor l
        LEFT JOIN ipt i ON i.an = l.an
        WHERE COALESCE(l.labour_startdate, i.regdate) >= (SELECT fy_start FROM thip_params)
          AND COALESCE(l.labour_startdate, i.regdate) < (SELECT fy_end FROM thip_params)
      ),
      newborn_periodized AS (
        SELECT
          nb.an,
          nb.mother_an,
          nb.born_date,
          nb.birth_weight,
          nb.apgar1,
          nb.apgar2,
          nb.dead,
          nb.has_asphyxia,
          nb.birthcondition1,
          nb.birthcondition2,
          nb.anc_complete,
          DATE_TRUNC('month', nb.born_date)::date AS period_start,
          EXTRACT(MONTH FROM nb.born_date)::integer AS calendar_month
        FROM ipt_newborn nb
        WHERE nb.born_date >= (SELECT fy_start FROM thip_params)
          AND nb.born_date < (SELECT fy_end FROM thip_params)
      ),
      emp_periodized AS (
        SELECT
          e.emp_id,
          e.emp_sex_id,
          e.emp_birthdate,
          e.emp_status_id,
          e.emp_type_id,
          e.emp_dep_id,
          e.emp_position_main_id,
          e.emp_work_begindate,
          e.emp_resign_enddate,
          e.emp_resign_type_id,
          DATE_TRUNC('month', e.emp_work_begindate)::date AS period_start,
          EXTRACT(MONTH FROM e.emp_work_begindate)::integer AS calendar_month
        FROM emp e
        WHERE e.emp_work_begindate >= (SELECT fy_start FROM thip_params)
          AND e.emp_work_begindate < (SELECT fy_end FROM thip_params)
      ),
          facts AS (
      
          SELECT
            'SH0104' AS indicator_code,
            DATE_TRUNC('month', period_start)::date - MAKE_INTERVAL(months => (CASE WHEN calendar_month >= 10 THEN calendar_month - 9 ELSE calendar_month + 3 END) - (CASE WHEN (CASE WHEN calendar_month >= 10 THEN calendar_month - 9 ELSE calendar_month + 3 END) <= 3 THEN 1 WHEN (CASE WHEN calendar_month >= 10 THEN calendar_month - 9 ELSE calendar_month + 3 END) <= 6 THEN 4 WHEN (CASE WHEN calendar_month >= 10 THEN calendar_month - 9 ELSE calendar_month + 3 END) <= 9 THEN 7 ELSE 10 END)) AS period_start,
            CASE WHEN (CASE WHEN calendar_month >= 10 THEN calendar_month - 9 ELSE calendar_month + 3 END) <= 3 THEN 1 WHEN (CASE WHEN calendar_month >= 10 THEN calendar_month - 9 ELSE calendar_month + 3 END) <= 6 THEN 4 WHEN (CASE WHEN calendar_month >= 10 THEN calendar_month - 9 ELSE calendar_month + 3 END) <= 9 THEN 7 ELSE 10 END AS fiscal_month,
            CASE WHEN calendar_month >= 10 THEN EXTRACT(YEAR FROM period_start)::integer + 1 ELSE EXTRACT(YEAR FROM period_start)::integer END AS fiscal_year,
            SUM(hr.voluntary_resign_cnt) AS numerator,
            COUNT(DISTINCT hr.staff_key) FILTER (WHERE hr.active_at_period_end) AS denominator,
            ROUND((SUM(hr.voluntary_resign_cnt)) * 100 / NULLIF(COUNT(DISTINCT hr.staff_key) FILTER (WHERE hr.active_at_period_end), 0), 2) AS value
          FROM (
            SELECT
              e.emp_id AS staff_key,
              DATE_TRUNC('month', months.work_month)::date AS period_start,
              EXTRACT(MONTH FROM months.work_month)::integer AS calendar_month,
              (SELECT COUNT(*)
                FROM emp_resign rr
                LEFT JOIN emp_resign_type rt ON rt.emp_resign_type_id = rr.emp_resign_type_id
                WHERE rr.emp_id = e.emp_id
                  AND rr.emp_resign_date >= months.work_month
                  AND rr.emp_resign_date < months.work_month + INTERVAL '1 month'
                  AND (rt.emp_resign_type_name IS NULL OR rt.emp_resign_type_name NOT ILIKE ANY (ARRAY[U&'%\0E43\0E2B\0E49\0E2D\0E2D\0E01%', U&'%\0E44\0E25\0E48\0E2D\0E2D\0E01%', U&'%\0E1B\0E25\0E14%', U&'%\0E40\0E01\0E29\0E35\0E22\0E13%', U&'%\0E40\0E2A\0E35\0E22\0E0A\0E35\0E27\0E34\0E15%', U&'%\0E16\0E36\0E07\0E41\0E01\0E48\0E01\0E23\0E23\0E21%', U&'%\0E42\0E2D\0E19%', U&'%\0E22\0E49\0E32\0E22%', U&'%\0E15\0E32\0E22%']))) AS voluntary_resign_cnt,
              ((e.emp_work_begindate IS NULL OR e.emp_work_begindate <= (DATE_TRUNC('quarter', months.work_month) + INTERVAL '3 months' - INTERVAL '1 day')) AND (e.emp_resign_enddate IS NULL OR e.emp_resign_enddate >= (DATE_TRUNC('quarter', months.work_month) + INTERVAL '3 months' - INTERVAL '1 day'))) AS active_at_period_end,
              ((COALESCE(pm.emp_position_main_name, '') ILIKE U&'%\0E41\0E1E\0E17\0E22\0E4C%' AND COALESCE(pm.emp_position_main_name, '') NOT ILIKE U&'%\0E40\0E17\0E04\0E19\0E34\0E04\0E01\0E32\0E23\0E41\0E1E\0E17\0E22\0E4C%' AND COALESCE(pm.emp_position_main_name, '') NOT ILIKE U&'%\0E1C\0E39\0E49\0E0A\0E48\0E27\0E22\0E41\0E1E\0E17\0E22\0E4C%' AND COALESCE(pm.emp_position_main_name, '') NOT ILIKE U&'%\0E41\0E1E\0E17\0E22\0E4C\0E41\0E1C\0E19%')) AS is_physician
            FROM emp e
            LEFT JOIN emp_position_main pm ON pm.emp_position_main_id = e.emp_position_main_id
            JOIN GENERATE_SERIES(
              DATE_TRUNC('month', GREATEST(COALESCE(e.emp_work_begindate, (SELECT fy_start FROM thip_params)), (SELECT fy_start FROM thip_params))),
              DATE_TRUNC('month', LEAST(COALESCE(e.emp_resign_enddate, (SELECT fy_end FROM thip_params)), (SELECT fy_end FROM thip_params)) - INTERVAL '1 day'),
              INTERVAL '1 month'
            ) AS months(work_month) ON TRUE
          ) hr
          WHERE hr.is_physician
          GROUP BY 2, 3, 4
          ), expected_codes(indicator_code, fiscal_month, indicator_name_th, indicator_name_en) AS (
            VALUES
              ('SH0104', 1, U&'\0E2D\0E31\0E15\0E23\0E32\0E01\0E32\0E23\0E25\0E32\0E2D\0E2D\0E01\0020\0E02\0E2D\0E07\0E41\0E1E\0E17\0E22\0E4C\002F\0E17\0E31\0E19\0E15\0E41\0E1E\0E17\0E22\0E4C', 'HRM: Turnover rate of physician and dentist'), ('SH0104', 4, U&'\0E2D\0E31\0E15\0E23\0E32\0E01\0E32\0E23\0E25\0E32\0E2D\0E2D\0E01\0020\0E02\0E2D\0E07\0E41\0E1E\0E17\0E22\0E4C\002F\0E17\0E31\0E19\0E15\0E41\0E1E\0E17\0E22\0E4C', 'HRM: Turnover rate of physician and dentist'), ('SH0104', 7, U&'\0E2D\0E31\0E15\0E23\0E32\0E01\0E32\0E23\0E25\0E32\0E2D\0E2D\0E01\0020\0E02\0E2D\0E07\0E41\0E1E\0E17\0E22\0E4C\002F\0E17\0E31\0E19\0E15\0E41\0E1E\0E17\0E22\0E4C', 'HRM: Turnover rate of physician and dentist'), ('SH0104', 10, U&'\0E2D\0E31\0E15\0E23\0E32\0E01\0E32\0E23\0E25\0E32\0E2D\0E2D\0E01\0020\0E02\0E2D\0E07\0E41\0E1E\0E17\0E22\0E4C\002F\0E17\0E31\0E19\0E15\0E41\0E1E\0E17\0E22\0E4C', 'HRM: Turnover rate of physician and dentist')
          ), fiscal_periods AS (
            SELECT
              generated.period_start::date AS period_start,
              CASE
                WHEN EXTRACT(MONTH FROM generated.period_start) >= 10
                  THEN EXTRACT(MONTH FROM generated.period_start)::integer - 9
                ELSE EXTRACT(MONTH FROM generated.period_start)::integer + 3
              END AS fiscal_month,
              CASE
                WHEN EXTRACT(MONTH FROM generated.period_start) >= 10
                  THEN EXTRACT(YEAR FROM generated.period_start)::integer + 1
                ELSE EXTRACT(YEAR FROM generated.period_start)::integer
              END AS fiscal_year
            FROM generate_series(
              CAST((SELECT fy_start FROM thip_params) AS date),
              CAST((SELECT fy_end FROM thip_params) AS date) - INTERVAL '1 month',
              INTERVAL '1 month'
            ) AS generated(period_start)
          )
          SELECT
            expected_codes.indicator_code,
            expected_codes.indicator_name_th AS indicator_name_th,
            expected_codes.indicator_name_en AS indicator_name_en,
            fiscal_periods.period_start,
            fiscal_periods.fiscal_month,
            fiscal_periods.fiscal_year,
            COALESCE(facts.numerator, 0) AS numerator,
            COALESCE(facts.denominator, 0) AS denominator,
            facts.value
          FROM expected_codes
          JOIN fiscal_periods
            ON fiscal_periods.fiscal_month = expected_codes.fiscal_month
          LEFT JOIN facts
            ON facts.indicator_code = expected_codes.indicator_code
           AND facts.period_start = fiscal_periods.period_start
           AND facts.fiscal_month = fiscal_periods.fiscal_month
           AND facts.fiscal_year = fiscal_periods.fiscal_year
          ORDER BY expected_codes.indicator_code, fiscal_periods.period_start
  ) AS b_SH0104
  UNION ALL
  SELECT * FROM (
    WITH
          ipd AS (
        SELECT
          i.an,
          i.hn,
          i.regdate,
          i.regtime,
          i.dchdate,
          COALESCE(i.bw, 0) AS bw,
          s.age_y,
          s.los,
          REPLACE(UPPER(TRIM(s.pdx)), '.', '') AS pdx,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
          ) AS died,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') <> REPLACE(UPPER(TRIM(s.pdx)), '.', '')
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
          ) AS has_acs_sdx,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
              AND (
                REPLACE(UPPER(TRIM(d.death_diag_icd10)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_cause)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_1)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_2)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_3)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_4)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
              )
          ) AS died_from_acs,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') <> REPLACE(UPPER(TRIM(s.pdx)), '.', '')
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
          ) AS has_stemi_sdx,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') <> REPLACE(UPPER(TRIM(s.pdx)), '.', '')
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') IN ('I214', 'I219')
          ) AS has_nste_sdx,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
              AND d.death_date IS NOT NULL
              AND (d.death_date + COALESCE(d.death_time, TIME '23:59:59')) >=
                (i.regdate + COALESCE(i.regtime, TIME '00:00:00'))
              AND (d.death_date + COALESCE(d.death_time, TIME '23:59:59')) <=
                (i.regdate + COALESCE(i.regtime, TIME '00:00:00')) + INTERVAL '48 hours'
          ) AS died_within_48h,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
              AND (
                REPLACE(UPPER(TRIM(d.death_diag_icd10)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
                OR REPLACE(UPPER(TRIM(d.death_cause)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
                OR REPLACE(UPPER(TRIM(d.death_diag_1)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
                OR REPLACE(UPPER(TRIM(d.death_diag_2)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
                OR REPLACE(UPPER(TRIM(d.death_diag_3)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
                OR REPLACE(UPPER(TRIM(d.death_diag_4)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
              )
          ) AS died_from_stemi,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
              AND (
                REPLACE(UPPER(TRIM(d.death_diag_icd10)), '.', '') IN ('I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_cause)), '.', '') IN ('I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_1)), '.', '') IN ('I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_2)), '.', '') IN ('I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_3)), '.', '') IN ('I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_4)), '.', '') IN ('I214', 'I219')
              )
          ) AS died_from_nste,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') <> REPLACE(UPPER(TRIM(s.pdx)), '.', '')
              AND (
                LEFT(REPLACE(UPPER(TRIM(sd.icd10)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(sd.icd10)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
              )
          ) AS has_pneumonia_sdx,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
              AND (
                LEFT(REPLACE(UPPER(TRIM(d.death_diag_icd10)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_icd10)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_cause)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_cause)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_1)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_1)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_2)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_2)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_3)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_3)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_4)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_4)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
              )
          ) AS died_from_pneumonia,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') IN ('A400', 'A419', 'R572', 'R651')
          ) AS has_ce0101_sepsis,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') IN ('A400', 'A409', 'A410', 'A419', 'R572', 'R651')
          ) AS has_ci0101_sepsis
        FROM ipt i
        JOIN an_stat s ON s.an = i.an
        WHERE i.dchdate >= (SELECT fy_start FROM thip_params)
          AND i.dchdate < (SELECT fy_end FROM thip_params)
          AND i.regdate IS NOT NULL
          AND EXTRACT(EPOCH FROM (
            (i.dchdate + COALESCE(i.dchtime, TIME '23:59:59')) -
            (i.regdate + COALESCE(i.regtime, TIME '00:00:00'))
          )) >= 14400
      ),
      periodized AS (
        SELECT
          *,
          DATE_TRUNC('month', dchdate)::date AS period_start,
          EXTRACT(MONTH FROM dchdate)::integer AS calendar_month
        FROM ipd
      ),
          opd_periodized AS (
        SELECT
          v.vn,
          v.hn,
          v.an,
          EXTRACT(YEAR FROM AGE(v.vstdate, pd.birthday))::integer AS age_y,
          pd.sex,
          (SELECT REPLACE(UPPER(TRIM(sd.icd10)), '.', '')
             FROM ovstdiag sd
            WHERE sd.vn = v.vn AND sd.diagtype = '1'
            ORDER BY sd.ovst_diag_id
            LIMIT 1) AS pdx,
          v.vstdate AS event_date,
          er.enter_er_time,
          er.triage_datetime,
          er.doctor_tx_time,
          er.finish_time,
          er.antibiotics_datetime,
          er.stroke_needle_datetime,
          er.stemi_balloon_datetime,
          er.er_emergency_level_id,
          er.unplanned_return,
          er.news2_score,
          DATE_TRUNC('month', v.vstdate)::date AS period_start,
          EXTRACT(MONTH FROM v.vstdate)::integer AS calendar_month
        FROM ovst v
        LEFT JOIN patient pd ON pd.hn = v.hn
        LEFT JOIN er_regist er ON er.vn = v.vn
        WHERE v.vstdate >= (SELECT fy_start FROM thip_params)
          AND v.vstdate < (SELECT fy_end FROM thip_params)
      ),
      chronic_periodized AS (
        SELECT
          cm.clinicmember_id,
          cm.clinic,
          cm.hn,
          cm.regdate,
          cm.lastvisit,
          cm.dchdate,
          cm.current_status,
          cm.clinic_member_status_id,
          cm.age_y,
          cm.sex,
          cm.chronic_type,
          cm.begin_year,
          cm.last_hba1c_value,
          cm.last_hba1c_date,
          cm.last_bp_bps_value,
          cm.last_bp_bpd_value,
          cm.last_bp_date,
          DATE_TRUNC('month', cm.regdate)::date AS period_start,
          EXTRACT(MONTH FROM cm.regdate)::integer AS calendar_month
        FROM clinicmember cm
        WHERE cm.regdate >= (SELECT fy_start FROM thip_params)
          AND cm.regdate < (SELECT fy_end FROM thip_params)
      ),
      delivery_periodized AS (
        SELECT
          l.laborid,
          l.an,
          l.hage AS mother_age_y,
          l.labor_type,
          l.mother_method,
          l.infant_sex,
          l.infant_weight,
          l.infant_apgarscore1,
          l.infant_apgarscore5,
          l.infant_apgarscore10,
          l.placenta_bloodloss,
          l.labour_startdate,
          l.labour_finishdate,
          DATE_TRUNC('month', COALESCE(l.labour_startdate, i.regdate))::date AS period_start,
          EXTRACT(MONTH FROM COALESCE(l.labour_startdate, i.regdate))::integer AS calendar_month
        FROM labor l
        LEFT JOIN ipt i ON i.an = l.an
        WHERE COALESCE(l.labour_startdate, i.regdate) >= (SELECT fy_start FROM thip_params)
          AND COALESCE(l.labour_startdate, i.regdate) < (SELECT fy_end FROM thip_params)
      ),
      newborn_periodized AS (
        SELECT
          nb.an,
          nb.mother_an,
          nb.born_date,
          nb.birth_weight,
          nb.apgar1,
          nb.apgar2,
          nb.dead,
          nb.has_asphyxia,
          nb.birthcondition1,
          nb.birthcondition2,
          nb.anc_complete,
          DATE_TRUNC('month', nb.born_date)::date AS period_start,
          EXTRACT(MONTH FROM nb.born_date)::integer AS calendar_month
        FROM ipt_newborn nb
        WHERE nb.born_date >= (SELECT fy_start FROM thip_params)
          AND nb.born_date < (SELECT fy_end FROM thip_params)
      ),
      emp_periodized AS (
        SELECT
          e.emp_id,
          e.emp_sex_id,
          e.emp_birthdate,
          e.emp_status_id,
          e.emp_type_id,
          e.emp_dep_id,
          e.emp_position_main_id,
          e.emp_work_begindate,
          e.emp_resign_enddate,
          e.emp_resign_type_id,
          DATE_TRUNC('month', e.emp_work_begindate)::date AS period_start,
          EXTRACT(MONTH FROM e.emp_work_begindate)::integer AS calendar_month
        FROM emp e
        WHERE e.emp_work_begindate >= (SELECT fy_start FROM thip_params)
          AND e.emp_work_begindate < (SELECT fy_end FROM thip_params)
      ),
          facts AS (
      
          SELECT
            'SH0105' AS indicator_code,
            DATE_TRUNC('month', period_start)::date - MAKE_INTERVAL(months => (CASE WHEN calendar_month >= 10 THEN calendar_month - 9 ELSE calendar_month + 3 END) - (CASE WHEN (CASE WHEN calendar_month >= 10 THEN calendar_month - 9 ELSE calendar_month + 3 END) <= 3 THEN 1 WHEN (CASE WHEN calendar_month >= 10 THEN calendar_month - 9 ELSE calendar_month + 3 END) <= 6 THEN 4 WHEN (CASE WHEN calendar_month >= 10 THEN calendar_month - 9 ELSE calendar_month + 3 END) <= 9 THEN 7 ELSE 10 END)) AS period_start,
            CASE WHEN (CASE WHEN calendar_month >= 10 THEN calendar_month - 9 ELSE calendar_month + 3 END) <= 3 THEN 1 WHEN (CASE WHEN calendar_month >= 10 THEN calendar_month - 9 ELSE calendar_month + 3 END) <= 6 THEN 4 WHEN (CASE WHEN calendar_month >= 10 THEN calendar_month - 9 ELSE calendar_month + 3 END) <= 9 THEN 7 ELSE 10 END AS fiscal_month,
            CASE WHEN calendar_month >= 10 THEN EXTRACT(YEAR FROM period_start)::integer + 1 ELSE EXTRACT(YEAR FROM period_start)::integer END AS fiscal_year,
            SUM(hr.voluntary_resign_cnt) AS numerator,
            COUNT(DISTINCT hr.staff_key) FILTER (WHERE hr.active_at_period_end) AS denominator,
            ROUND((SUM(hr.voluntary_resign_cnt)) * 100 / NULLIF(COUNT(DISTINCT hr.staff_key) FILTER (WHERE hr.active_at_period_end), 0), 2) AS value
          FROM (
            SELECT
              e.emp_id AS staff_key,
              DATE_TRUNC('month', months.work_month)::date AS period_start,
              EXTRACT(MONTH FROM months.work_month)::integer AS calendar_month,
              (SELECT COUNT(*)
                FROM emp_resign rr
                LEFT JOIN emp_resign_type rt ON rt.emp_resign_type_id = rr.emp_resign_type_id
                WHERE rr.emp_id = e.emp_id
                  AND rr.emp_resign_date >= months.work_month
                  AND rr.emp_resign_date < months.work_month + INTERVAL '1 month'
                  AND (rt.emp_resign_type_name IS NULL OR rt.emp_resign_type_name NOT ILIKE ANY (ARRAY[U&'%\0E43\0E2B\0E49\0E2D\0E2D\0E01%', U&'%\0E44\0E25\0E48\0E2D\0E2D\0E01%', U&'%\0E1B\0E25\0E14%', U&'%\0E40\0E01\0E29\0E35\0E22\0E13%', U&'%\0E40\0E2A\0E35\0E22\0E0A\0E35\0E27\0E34\0E15%', U&'%\0E16\0E36\0E07\0E41\0E01\0E48\0E01\0E23\0E23\0E21%', U&'%\0E42\0E2D\0E19%', U&'%\0E22\0E49\0E32\0E22%', U&'%\0E15\0E32\0E22%']))) AS voluntary_resign_cnt,
              ((e.emp_work_begindate IS NULL OR e.emp_work_begindate <= (DATE_TRUNC('quarter', months.work_month) + INTERVAL '3 months' - INTERVAL '1 day')) AND (e.emp_resign_enddate IS NULL OR e.emp_resign_enddate >= (DATE_TRUNC('quarter', months.work_month) + INTERVAL '3 months' - INTERVAL '1 day'))) AS active_at_period_end,
              ((COALESCE(pm.emp_position_main_name, '') ILIKE U&'%\0E1E\0E22\0E32\0E1A\0E32\0E25\0E27\0E34\0E0A\0E32\0E0A\0E35\0E1E%' OR (COALESCE(pm.emp_position_main_name, '') ILIKE U&'%\0E1E\0E22\0E32\0E1A\0E32\0E25%' AND COALESCE(pm.emp_position_main_name, '') NOT ILIKE U&'%\0E1C\0E39\0E49\0E0A\0E48\0E27\0E22%' AND COALESCE(pm.emp_position_main_name, '') NOT ILIKE U&'%\0E1E\0E19\0E31\0E01\0E07\0E32\0E19%'))) AS is_nurse
            FROM emp e
            LEFT JOIN emp_position_main pm ON pm.emp_position_main_id = e.emp_position_main_id
            JOIN GENERATE_SERIES(
              DATE_TRUNC('month', GREATEST(COALESCE(e.emp_work_begindate, (SELECT fy_start FROM thip_params)), (SELECT fy_start FROM thip_params))),
              DATE_TRUNC('month', LEAST(COALESCE(e.emp_resign_enddate, (SELECT fy_end FROM thip_params)), (SELECT fy_end FROM thip_params)) - INTERVAL '1 day'),
              INTERVAL '1 month'
            ) AS months(work_month) ON TRUE
          ) hr
          WHERE hr.is_nurse
          GROUP BY 2, 3, 4
          ), expected_codes(indicator_code, fiscal_month, indicator_name_th, indicator_name_en) AS (
            VALUES
              ('SH0105', 1, U&'\0E2D\0E31\0E15\0E23\0E32\0E01\0E32\0E23\0E25\0E32\0E2D\0E2D\0E01\0020\0E02\0E2D\0E07\0E1E\0E22\0E32\0E1A\0E32\0E25\0E27\0E34\0E0A\0E32\0E0A\0E35\0E1E', 'HRM: Turnover rate of nurses'), ('SH0105', 4, U&'\0E2D\0E31\0E15\0E23\0E32\0E01\0E32\0E23\0E25\0E32\0E2D\0E2D\0E01\0020\0E02\0E2D\0E07\0E1E\0E22\0E32\0E1A\0E32\0E25\0E27\0E34\0E0A\0E32\0E0A\0E35\0E1E', 'HRM: Turnover rate of nurses'), ('SH0105', 7, U&'\0E2D\0E31\0E15\0E23\0E32\0E01\0E32\0E23\0E25\0E32\0E2D\0E2D\0E01\0020\0E02\0E2D\0E07\0E1E\0E22\0E32\0E1A\0E32\0E25\0E27\0E34\0E0A\0E32\0E0A\0E35\0E1E', 'HRM: Turnover rate of nurses'), ('SH0105', 10, U&'\0E2D\0E31\0E15\0E23\0E32\0E01\0E32\0E23\0E25\0E32\0E2D\0E2D\0E01\0020\0E02\0E2D\0E07\0E1E\0E22\0E32\0E1A\0E32\0E25\0E27\0E34\0E0A\0E32\0E0A\0E35\0E1E', 'HRM: Turnover rate of nurses')
          ), fiscal_periods AS (
            SELECT
              generated.period_start::date AS period_start,
              CASE
                WHEN EXTRACT(MONTH FROM generated.period_start) >= 10
                  THEN EXTRACT(MONTH FROM generated.period_start)::integer - 9
                ELSE EXTRACT(MONTH FROM generated.period_start)::integer + 3
              END AS fiscal_month,
              CASE
                WHEN EXTRACT(MONTH FROM generated.period_start) >= 10
                  THEN EXTRACT(YEAR FROM generated.period_start)::integer + 1
                ELSE EXTRACT(YEAR FROM generated.period_start)::integer
              END AS fiscal_year
            FROM generate_series(
              CAST((SELECT fy_start FROM thip_params) AS date),
              CAST((SELECT fy_end FROM thip_params) AS date) - INTERVAL '1 month',
              INTERVAL '1 month'
            ) AS generated(period_start)
          )
          SELECT
            expected_codes.indicator_code,
            expected_codes.indicator_name_th AS indicator_name_th,
            expected_codes.indicator_name_en AS indicator_name_en,
            fiscal_periods.period_start,
            fiscal_periods.fiscal_month,
            fiscal_periods.fiscal_year,
            COALESCE(facts.numerator, 0) AS numerator,
            COALESCE(facts.denominator, 0) AS denominator,
            facts.value
          FROM expected_codes
          JOIN fiscal_periods
            ON fiscal_periods.fiscal_month = expected_codes.fiscal_month
          LEFT JOIN facts
            ON facts.indicator_code = expected_codes.indicator_code
           AND facts.period_start = fiscal_periods.period_start
           AND facts.fiscal_month = fiscal_periods.fiscal_month
           AND facts.fiscal_year = fiscal_periods.fiscal_year
          ORDER BY expected_codes.indicator_code, fiscal_periods.period_start
  ) AS b_SH0105
  UNION ALL
  SELECT * FROM (
    WITH
          ipd AS (
        SELECT
          i.an,
          i.hn,
          i.regdate,
          i.regtime,
          i.dchdate,
          COALESCE(i.bw, 0) AS bw,
          s.age_y,
          s.los,
          REPLACE(UPPER(TRIM(s.pdx)), '.', '') AS pdx,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
          ) AS died,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') <> REPLACE(UPPER(TRIM(s.pdx)), '.', '')
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
          ) AS has_acs_sdx,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
              AND (
                REPLACE(UPPER(TRIM(d.death_diag_icd10)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_cause)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_1)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_2)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_3)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_4)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
              )
          ) AS died_from_acs,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') <> REPLACE(UPPER(TRIM(s.pdx)), '.', '')
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
          ) AS has_stemi_sdx,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') <> REPLACE(UPPER(TRIM(s.pdx)), '.', '')
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') IN ('I214', 'I219')
          ) AS has_nste_sdx,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
              AND d.death_date IS NOT NULL
              AND (d.death_date + COALESCE(d.death_time, TIME '23:59:59')) >=
                (i.regdate + COALESCE(i.regtime, TIME '00:00:00'))
              AND (d.death_date + COALESCE(d.death_time, TIME '23:59:59')) <=
                (i.regdate + COALESCE(i.regtime, TIME '00:00:00')) + INTERVAL '48 hours'
          ) AS died_within_48h,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
              AND (
                REPLACE(UPPER(TRIM(d.death_diag_icd10)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
                OR REPLACE(UPPER(TRIM(d.death_cause)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
                OR REPLACE(UPPER(TRIM(d.death_diag_1)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
                OR REPLACE(UPPER(TRIM(d.death_diag_2)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
                OR REPLACE(UPPER(TRIM(d.death_diag_3)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
                OR REPLACE(UPPER(TRIM(d.death_diag_4)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
              )
          ) AS died_from_stemi,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
              AND (
                REPLACE(UPPER(TRIM(d.death_diag_icd10)), '.', '') IN ('I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_cause)), '.', '') IN ('I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_1)), '.', '') IN ('I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_2)), '.', '') IN ('I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_3)), '.', '') IN ('I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_4)), '.', '') IN ('I214', 'I219')
              )
          ) AS died_from_nste,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') <> REPLACE(UPPER(TRIM(s.pdx)), '.', '')
              AND (
                LEFT(REPLACE(UPPER(TRIM(sd.icd10)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(sd.icd10)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
              )
          ) AS has_pneumonia_sdx,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
              AND (
                LEFT(REPLACE(UPPER(TRIM(d.death_diag_icd10)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_icd10)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_cause)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_cause)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_1)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_1)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_2)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_2)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_3)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_3)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_4)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_4)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
              )
          ) AS died_from_pneumonia,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') IN ('A400', 'A419', 'R572', 'R651')
          ) AS has_ce0101_sepsis,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') IN ('A400', 'A409', 'A410', 'A419', 'R572', 'R651')
          ) AS has_ci0101_sepsis
        FROM ipt i
        JOIN an_stat s ON s.an = i.an
        WHERE i.dchdate >= (SELECT fy_start FROM thip_params)
          AND i.dchdate < (SELECT fy_end FROM thip_params)
          AND i.regdate IS NOT NULL
          AND EXTRACT(EPOCH FROM (
            (i.dchdate + COALESCE(i.dchtime, TIME '23:59:59')) -
            (i.regdate + COALESCE(i.regtime, TIME '00:00:00'))
          )) >= 14400
      ),
      periodized AS (
        SELECT
          *,
          DATE_TRUNC('month', dchdate)::date AS period_start,
          EXTRACT(MONTH FROM dchdate)::integer AS calendar_month
        FROM ipd
      ),
          opd_periodized AS (
        SELECT
          v.vn,
          v.hn,
          v.an,
          EXTRACT(YEAR FROM AGE(v.vstdate, pd.birthday))::integer AS age_y,
          pd.sex,
          (SELECT REPLACE(UPPER(TRIM(sd.icd10)), '.', '')
             FROM ovstdiag sd
            WHERE sd.vn = v.vn AND sd.diagtype = '1'
            ORDER BY sd.ovst_diag_id
            LIMIT 1) AS pdx,
          v.vstdate AS event_date,
          er.enter_er_time,
          er.triage_datetime,
          er.doctor_tx_time,
          er.finish_time,
          er.antibiotics_datetime,
          er.stroke_needle_datetime,
          er.stemi_balloon_datetime,
          er.er_emergency_level_id,
          er.unplanned_return,
          er.news2_score,
          DATE_TRUNC('month', v.vstdate)::date AS period_start,
          EXTRACT(MONTH FROM v.vstdate)::integer AS calendar_month
        FROM ovst v
        LEFT JOIN patient pd ON pd.hn = v.hn
        LEFT JOIN er_regist er ON er.vn = v.vn
        WHERE v.vstdate >= (SELECT fy_start FROM thip_params)
          AND v.vstdate < (SELECT fy_end FROM thip_params)
      ),
      chronic_periodized AS (
        SELECT
          cm.clinicmember_id,
          cm.clinic,
          cm.hn,
          cm.regdate,
          cm.lastvisit,
          cm.dchdate,
          cm.current_status,
          cm.clinic_member_status_id,
          cm.age_y,
          cm.sex,
          cm.chronic_type,
          cm.begin_year,
          cm.last_hba1c_value,
          cm.last_hba1c_date,
          cm.last_bp_bps_value,
          cm.last_bp_bpd_value,
          cm.last_bp_date,
          DATE_TRUNC('month', cm.regdate)::date AS period_start,
          EXTRACT(MONTH FROM cm.regdate)::integer AS calendar_month
        FROM clinicmember cm
        WHERE cm.regdate >= (SELECT fy_start FROM thip_params)
          AND cm.regdate < (SELECT fy_end FROM thip_params)
      ),
      delivery_periodized AS (
        SELECT
          l.laborid,
          l.an,
          l.hage AS mother_age_y,
          l.labor_type,
          l.mother_method,
          l.infant_sex,
          l.infant_weight,
          l.infant_apgarscore1,
          l.infant_apgarscore5,
          l.infant_apgarscore10,
          l.placenta_bloodloss,
          l.labour_startdate,
          l.labour_finishdate,
          DATE_TRUNC('month', COALESCE(l.labour_startdate, i.regdate))::date AS period_start,
          EXTRACT(MONTH FROM COALESCE(l.labour_startdate, i.regdate))::integer AS calendar_month
        FROM labor l
        LEFT JOIN ipt i ON i.an = l.an
        WHERE COALESCE(l.labour_startdate, i.regdate) >= (SELECT fy_start FROM thip_params)
          AND COALESCE(l.labour_startdate, i.regdate) < (SELECT fy_end FROM thip_params)
      ),
      newborn_periodized AS (
        SELECT
          nb.an,
          nb.mother_an,
          nb.born_date,
          nb.birth_weight,
          nb.apgar1,
          nb.apgar2,
          nb.dead,
          nb.has_asphyxia,
          nb.birthcondition1,
          nb.birthcondition2,
          nb.anc_complete,
          DATE_TRUNC('month', nb.born_date)::date AS period_start,
          EXTRACT(MONTH FROM nb.born_date)::integer AS calendar_month
        FROM ipt_newborn nb
        WHERE nb.born_date >= (SELECT fy_start FROM thip_params)
          AND nb.born_date < (SELECT fy_end FROM thip_params)
      ),
      emp_periodized AS (
        SELECT
          e.emp_id,
          e.emp_sex_id,
          e.emp_birthdate,
          e.emp_status_id,
          e.emp_type_id,
          e.emp_dep_id,
          e.emp_position_main_id,
          e.emp_work_begindate,
          e.emp_resign_enddate,
          e.emp_resign_type_id,
          DATE_TRUNC('month', e.emp_work_begindate)::date AS period_start,
          EXTRACT(MONTH FROM e.emp_work_begindate)::integer AS calendar_month
        FROM emp e
        WHERE e.emp_work_begindate >= (SELECT fy_start FROM thip_params)
          AND e.emp_work_begindate < (SELECT fy_end FROM thip_params)
      ),
          facts AS (
      
          SELECT
            'SH0106' AS indicator_code,
            DATE_TRUNC('month', period_start)::date - MAKE_INTERVAL(months => (CASE WHEN calendar_month >= 10 THEN calendar_month - 9 ELSE calendar_month + 3 END) - (CASE WHEN (CASE WHEN calendar_month >= 10 THEN calendar_month - 9 ELSE calendar_month + 3 END) <= 3 THEN 1 WHEN (CASE WHEN calendar_month >= 10 THEN calendar_month - 9 ELSE calendar_month + 3 END) <= 6 THEN 4 WHEN (CASE WHEN calendar_month >= 10 THEN calendar_month - 9 ELSE calendar_month + 3 END) <= 9 THEN 7 ELSE 10 END)) AS period_start,
            CASE WHEN (CASE WHEN calendar_month >= 10 THEN calendar_month - 9 ELSE calendar_month + 3 END) <= 3 THEN 1 WHEN (CASE WHEN calendar_month >= 10 THEN calendar_month - 9 ELSE calendar_month + 3 END) <= 6 THEN 4 WHEN (CASE WHEN calendar_month >= 10 THEN calendar_month - 9 ELSE calendar_month + 3 END) <= 9 THEN 7 ELSE 10 END AS fiscal_month,
            CASE WHEN calendar_month >= 10 THEN EXTRACT(YEAR FROM period_start)::integer + 1 ELSE EXTRACT(YEAR FROM period_start)::integer END AS fiscal_year,
            SUM(hr.voluntary_resign_cnt) AS numerator,
            COUNT(DISTINCT hr.staff_key) FILTER (WHERE hr.active_at_period_end) AS denominator,
            ROUND((SUM(hr.voluntary_resign_cnt)) * 100 / NULLIF(COUNT(DISTINCT hr.staff_key) FILTER (WHERE hr.active_at_period_end), 0), 2) AS value
          FROM (
            SELECT
              e.emp_id AS staff_key,
              DATE_TRUNC('month', months.work_month)::date AS period_start,
              EXTRACT(MONTH FROM months.work_month)::integer AS calendar_month,
              (SELECT COUNT(*)
                FROM emp_resign rr
                LEFT JOIN emp_resign_type rt ON rt.emp_resign_type_id = rr.emp_resign_type_id
                WHERE rr.emp_id = e.emp_id
                  AND rr.emp_resign_date >= months.work_month
                  AND rr.emp_resign_date < months.work_month + INTERVAL '1 month'
                  AND (rt.emp_resign_type_name IS NULL OR rt.emp_resign_type_name NOT ILIKE ANY (ARRAY[U&'%\0E43\0E2B\0E49\0E2D\0E2D\0E01%', U&'%\0E44\0E25\0E48\0E2D\0E2D\0E01%', U&'%\0E1B\0E25\0E14%', U&'%\0E40\0E01\0E29\0E35\0E22\0E13%', U&'%\0E40\0E2A\0E35\0E22\0E0A\0E35\0E27\0E34\0E15%', U&'%\0E16\0E36\0E07\0E41\0E01\0E48\0E01\0E23\0E23\0E21%', U&'%\0E42\0E2D\0E19%', U&'%\0E22\0E49\0E32\0E22%', U&'%\0E15\0E32\0E22%']))) AS voluntary_resign_cnt,
              ((e.emp_work_begindate IS NULL OR e.emp_work_begindate <= (DATE_TRUNC('quarter', months.work_month) + INTERVAL '3 months' - INTERVAL '1 day')) AND (e.emp_resign_enddate IS NULL OR e.emp_resign_enddate >= (DATE_TRUNC('quarter', months.work_month) + INTERVAL '3 months' - INTERVAL '1 day'))) AS active_at_period_end,
              (((NOT (COALESCE(pm.emp_position_main_name, '') ILIKE U&'%\0E41\0E1E\0E17\0E22\0E4C%' AND COALESCE(pm.emp_position_main_name, '') NOT ILIKE U&'%\0E40\0E17\0E04\0E19\0E34\0E04\0E01\0E32\0E23\0E41\0E1E\0E17\0E22\0E4C%' AND COALESCE(pm.emp_position_main_name, '') NOT ILIKE U&'%\0E1C\0E39\0E49\0E0A\0E48\0E27\0E22\0E41\0E1E\0E17\0E22\0E4C%' AND COALESCE(pm.emp_position_main_name, '') NOT ILIKE U&'%\0E41\0E1E\0E17\0E22\0E4C\0E41\0E1C\0E19%')) AND (NOT (COALESCE(pm.emp_position_main_name, '') ILIKE U&'%\0E1E\0E22\0E32\0E1A\0E32\0E25\0E27\0E34\0E0A\0E32\0E0A\0E35\0E1E%' OR (COALESCE(pm.emp_position_main_name, '') ILIKE U&'%\0E1E\0E22\0E32\0E1A\0E32\0E25%' AND COALESCE(pm.emp_position_main_name, '') NOT ILIKE U&'%\0E1C\0E39\0E49\0E0A\0E48\0E27\0E22%' AND COALESCE(pm.emp_position_main_name, '') NOT ILIKE U&'%\0E1E\0E19\0E31\0E01\0E07\0E32\0E19%'))) AND (COALESCE(pm.emp_position_main_name, '') ILIKE ANY (ARRAY[U&'%\0E1C\0E14\0E38\0E07\0E04\0E23\0E23\0E20\0E4C%', U&'%\0E40\0E20\0E2A\0E31\0E0A%', U&'%\0E1C\0E39\0E49\0E0A\0E48\0E27\0E22\0E41\0E1E\0E17\0E22\0E4C%', U&'%\0E2D\0E32\0E0A\0E35\0E27\0E2D\0E19\0E32\0E21\0E31\0E22%', U&'%\0E2A\0E34\0E48\0E07\0E41\0E27\0E14\0E25\0E49\0E2D\0E21%', U&'%\0E01\0E32\0E22\0E20\0E32\0E1E%', U&'%\0E42\0E20\0E0A\0E19\0E32%', U&'%\0E2A\0E37\0E48\0E2D\0E04\0E27\0E32\0E21\0E2B\0E21\0E32\0E22%', U&'%\0E17\0E31\0E28\0E19\0E21\0E32\0E15\0E23%', U&'%\0E2D\0E32\0E0A\0E35\0E27\0E1A\0E33\0E1A\0E31\0E14%', U&'%\0E01\0E34\0E08\0E01\0E23\0E23\0E21\0E1A\0E33\0E1A\0E31\0E14%', U&'%\0E40\0E17\0E04\0E19\0E34\0E04\0E01\0E32\0E23\0E41\0E1E\0E17\0E22\0E4C%', U&'%\0E40\0E17\0E04\0E19\0E34\0E04\0E1E\0E22\0E32\0E18\0E34%', U&'%\0E1E\0E22\0E32\0E18\0E34%', U&'%\0E1C\0E39\0E49\0E0A\0E48\0E27\0E22\0E40\0E20\0E2A\0E31\0E0A%', U&'%\0E2D\0E38\0E1B\0E01\0E23\0E13\0E4C\0E01\0E32\0E23\0E41\0E1E\0E17\0E22\0E4C\0E40\0E17\0E35\0E22\0E21%', U&'%\0E1E\0E19\0E31\0E01\0E07\0E32\0E19\0E01\0E32\0E23\0E1E\0E22\0E32\0E1A\0E32\0E25%', U&'%\0E1C\0E39\0E49\0E0A\0E48\0E27\0E22\0E17\0E31\0E19\0E15%', U&'%\0E17\0E31\0E19\0E15\0E20\0E34\0E1A\0E32\0E25%', U&'%\0E40\0E27\0E0A\0E23\0E30\0E40\0E1A\0E35\0E22\0E19%', U&'%\0E2A\0E38\0E02\0E20\0E32\0E1E\0E0A\0E38\0E21\0E0A\0E19%', U&'%\0E1B\0E23\0E30\0E01\0E2D\0E1A\0E41\0E27\0E48\0E19%', U&'%\0E1C\0E39\0E49\0E0A\0E48\0E27\0E22\0E19\0E31\0E01\0E01\0E32\0E22\0E20\0E32\0E1E%', U&'%\0E1C\0E39\0E49\0E15\0E23\0E27\0E08\0E2A\0E2D\0E1A%', U&'%\0E23\0E16\0E1E\0E22\0E32\0E1A\0E32\0E25%', U&'%\0E08\0E48\0E32\0E22\0E01\0E25\0E32\0E07%', U&'%\0E40\0E27\0E0A\0E20\0E31\0E13\0E11\0E4C\0E01\0E25\0E32\0E07%', U&'%\0E41\0E1E\0E17\0E22\0E4C\0E41\0E1C\0E19%'])))) AS is_allied_health
            FROM emp e
            LEFT JOIN emp_position_main pm ON pm.emp_position_main_id = e.emp_position_main_id
            JOIN GENERATE_SERIES(
              DATE_TRUNC('month', GREATEST(COALESCE(e.emp_work_begindate, (SELECT fy_start FROM thip_params)), (SELECT fy_start FROM thip_params))),
              DATE_TRUNC('month', LEAST(COALESCE(e.emp_resign_enddate, (SELECT fy_end FROM thip_params)), (SELECT fy_end FROM thip_params)) - INTERVAL '1 day'),
              INTERVAL '1 month'
            ) AS months(work_month) ON TRUE
          ) hr
          WHERE hr.is_allied_health
          GROUP BY 2, 3, 4
          ), expected_codes(indicator_code, fiscal_month, indicator_name_th, indicator_name_en) AS (
            VALUES
              ('SH0106', 1, U&'\0E2D\0E31\0E15\0E23\0E32\0E01\0E32\0E23\0E25\0E32\0E2D\0E2D\0E01\0020\0E02\0E2D\0E07\0E1A\0E38\0E04\0E25\0E32\0E01\0E23\0E2A\0E32\0E22\0020\0061\006C\006C\0069\0065\0064\0020\0068\0065\0061\006C\0074\0068', 'HRM: Turnover rate of allied health personnel'), ('SH0106', 4, U&'\0E2D\0E31\0E15\0E23\0E32\0E01\0E32\0E23\0E25\0E32\0E2D\0E2D\0E01\0020\0E02\0E2D\0E07\0E1A\0E38\0E04\0E25\0E32\0E01\0E23\0E2A\0E32\0E22\0020\0061\006C\006C\0069\0065\0064\0020\0068\0065\0061\006C\0074\0068', 'HRM: Turnover rate of allied health personnel'), ('SH0106', 7, U&'\0E2D\0E31\0E15\0E23\0E32\0E01\0E32\0E23\0E25\0E32\0E2D\0E2D\0E01\0020\0E02\0E2D\0E07\0E1A\0E38\0E04\0E25\0E32\0E01\0E23\0E2A\0E32\0E22\0020\0061\006C\006C\0069\0065\0064\0020\0068\0065\0061\006C\0074\0068', 'HRM: Turnover rate of allied health personnel'), ('SH0106', 10, U&'\0E2D\0E31\0E15\0E23\0E32\0E01\0E32\0E23\0E25\0E32\0E2D\0E2D\0E01\0020\0E02\0E2D\0E07\0E1A\0E38\0E04\0E25\0E32\0E01\0E23\0E2A\0E32\0E22\0020\0061\006C\006C\0069\0065\0064\0020\0068\0065\0061\006C\0074\0068', 'HRM: Turnover rate of allied health personnel')
          ), fiscal_periods AS (
            SELECT
              generated.period_start::date AS period_start,
              CASE
                WHEN EXTRACT(MONTH FROM generated.period_start) >= 10
                  THEN EXTRACT(MONTH FROM generated.period_start)::integer - 9
                ELSE EXTRACT(MONTH FROM generated.period_start)::integer + 3
              END AS fiscal_month,
              CASE
                WHEN EXTRACT(MONTH FROM generated.period_start) >= 10
                  THEN EXTRACT(YEAR FROM generated.period_start)::integer + 1
                ELSE EXTRACT(YEAR FROM generated.period_start)::integer
              END AS fiscal_year
            FROM generate_series(
              CAST((SELECT fy_start FROM thip_params) AS date),
              CAST((SELECT fy_end FROM thip_params) AS date) - INTERVAL '1 month',
              INTERVAL '1 month'
            ) AS generated(period_start)
          )
          SELECT
            expected_codes.indicator_code,
            expected_codes.indicator_name_th AS indicator_name_th,
            expected_codes.indicator_name_en AS indicator_name_en,
            fiscal_periods.period_start,
            fiscal_periods.fiscal_month,
            fiscal_periods.fiscal_year,
            COALESCE(facts.numerator, 0) AS numerator,
            COALESCE(facts.denominator, 0) AS denominator,
            facts.value
          FROM expected_codes
          JOIN fiscal_periods
            ON fiscal_periods.fiscal_month = expected_codes.fiscal_month
          LEFT JOIN facts
            ON facts.indicator_code = expected_codes.indicator_code
           AND facts.period_start = fiscal_periods.period_start
           AND facts.fiscal_month = fiscal_periods.fiscal_month
           AND facts.fiscal_year = fiscal_periods.fiscal_year
          ORDER BY expected_codes.indicator_code, fiscal_periods.period_start
  ) AS b_SH0106
  UNION ALL
  SELECT * FROM (
    WITH
          ipd AS (
        SELECT
          i.an,
          i.hn,
          i.regdate,
          i.regtime,
          i.dchdate,
          COALESCE(i.bw, 0) AS bw,
          s.age_y,
          s.los,
          REPLACE(UPPER(TRIM(s.pdx)), '.', '') AS pdx,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
          ) AS died,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') <> REPLACE(UPPER(TRIM(s.pdx)), '.', '')
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
          ) AS has_acs_sdx,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
              AND (
                REPLACE(UPPER(TRIM(d.death_diag_icd10)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_cause)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_1)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_2)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_3)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_4)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
              )
          ) AS died_from_acs,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') <> REPLACE(UPPER(TRIM(s.pdx)), '.', '')
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
          ) AS has_stemi_sdx,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') <> REPLACE(UPPER(TRIM(s.pdx)), '.', '')
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') IN ('I214', 'I219')
          ) AS has_nste_sdx,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
              AND d.death_date IS NOT NULL
              AND (d.death_date + COALESCE(d.death_time, TIME '23:59:59')) >=
                (i.regdate + COALESCE(i.regtime, TIME '00:00:00'))
              AND (d.death_date + COALESCE(d.death_time, TIME '23:59:59')) <=
                (i.regdate + COALESCE(i.regtime, TIME '00:00:00')) + INTERVAL '48 hours'
          ) AS died_within_48h,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
              AND (
                REPLACE(UPPER(TRIM(d.death_diag_icd10)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
                OR REPLACE(UPPER(TRIM(d.death_cause)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
                OR REPLACE(UPPER(TRIM(d.death_diag_1)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
                OR REPLACE(UPPER(TRIM(d.death_diag_2)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
                OR REPLACE(UPPER(TRIM(d.death_diag_3)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
                OR REPLACE(UPPER(TRIM(d.death_diag_4)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
              )
          ) AS died_from_stemi,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
              AND (
                REPLACE(UPPER(TRIM(d.death_diag_icd10)), '.', '') IN ('I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_cause)), '.', '') IN ('I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_1)), '.', '') IN ('I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_2)), '.', '') IN ('I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_3)), '.', '') IN ('I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_4)), '.', '') IN ('I214', 'I219')
              )
          ) AS died_from_nste,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') <> REPLACE(UPPER(TRIM(s.pdx)), '.', '')
              AND (
                LEFT(REPLACE(UPPER(TRIM(sd.icd10)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(sd.icd10)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
              )
          ) AS has_pneumonia_sdx,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
              AND (
                LEFT(REPLACE(UPPER(TRIM(d.death_diag_icd10)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_icd10)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_cause)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_cause)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_1)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_1)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_2)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_2)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_3)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_3)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_4)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_4)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
              )
          ) AS died_from_pneumonia,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') IN ('A400', 'A419', 'R572', 'R651')
          ) AS has_ce0101_sepsis,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') IN ('A400', 'A409', 'A410', 'A419', 'R572', 'R651')
          ) AS has_ci0101_sepsis
        FROM ipt i
        JOIN an_stat s ON s.an = i.an
        WHERE i.dchdate >= (SELECT fy_start FROM thip_params)
          AND i.dchdate < (SELECT fy_end FROM thip_params)
          AND i.regdate IS NOT NULL
          AND EXTRACT(EPOCH FROM (
            (i.dchdate + COALESCE(i.dchtime, TIME '23:59:59')) -
            (i.regdate + COALESCE(i.regtime, TIME '00:00:00'))
          )) >= 14400
      ),
      periodized AS (
        SELECT
          *,
          DATE_TRUNC('month', dchdate)::date AS period_start,
          EXTRACT(MONTH FROM dchdate)::integer AS calendar_month
        FROM ipd
      ),
          opd_periodized AS (
        SELECT
          v.vn,
          v.hn,
          v.an,
          EXTRACT(YEAR FROM AGE(v.vstdate, pd.birthday))::integer AS age_y,
          pd.sex,
          (SELECT REPLACE(UPPER(TRIM(sd.icd10)), '.', '')
             FROM ovstdiag sd
            WHERE sd.vn = v.vn AND sd.diagtype = '1'
            ORDER BY sd.ovst_diag_id
            LIMIT 1) AS pdx,
          v.vstdate AS event_date,
          er.enter_er_time,
          er.triage_datetime,
          er.doctor_tx_time,
          er.finish_time,
          er.antibiotics_datetime,
          er.stroke_needle_datetime,
          er.stemi_balloon_datetime,
          er.er_emergency_level_id,
          er.unplanned_return,
          er.news2_score,
          DATE_TRUNC('month', v.vstdate)::date AS period_start,
          EXTRACT(MONTH FROM v.vstdate)::integer AS calendar_month
        FROM ovst v
        LEFT JOIN patient pd ON pd.hn = v.hn
        LEFT JOIN er_regist er ON er.vn = v.vn
        WHERE v.vstdate >= (SELECT fy_start FROM thip_params)
          AND v.vstdate < (SELECT fy_end FROM thip_params)
      ),
      chronic_periodized AS (
        SELECT
          cm.clinicmember_id,
          cm.clinic,
          cm.hn,
          cm.regdate,
          cm.lastvisit,
          cm.dchdate,
          cm.current_status,
          cm.clinic_member_status_id,
          cm.age_y,
          cm.sex,
          cm.chronic_type,
          cm.begin_year,
          cm.last_hba1c_value,
          cm.last_hba1c_date,
          cm.last_bp_bps_value,
          cm.last_bp_bpd_value,
          cm.last_bp_date,
          DATE_TRUNC('month', cm.regdate)::date AS period_start,
          EXTRACT(MONTH FROM cm.regdate)::integer AS calendar_month
        FROM clinicmember cm
        WHERE cm.regdate >= (SELECT fy_start FROM thip_params)
          AND cm.regdate < (SELECT fy_end FROM thip_params)
      ),
      delivery_periodized AS (
        SELECT
          l.laborid,
          l.an,
          l.hage AS mother_age_y,
          l.labor_type,
          l.mother_method,
          l.infant_sex,
          l.infant_weight,
          l.infant_apgarscore1,
          l.infant_apgarscore5,
          l.infant_apgarscore10,
          l.placenta_bloodloss,
          l.labour_startdate,
          l.labour_finishdate,
          DATE_TRUNC('month', COALESCE(l.labour_startdate, i.regdate))::date AS period_start,
          EXTRACT(MONTH FROM COALESCE(l.labour_startdate, i.regdate))::integer AS calendar_month
        FROM labor l
        LEFT JOIN ipt i ON i.an = l.an
        WHERE COALESCE(l.labour_startdate, i.regdate) >= (SELECT fy_start FROM thip_params)
          AND COALESCE(l.labour_startdate, i.regdate) < (SELECT fy_end FROM thip_params)
      ),
      newborn_periodized AS (
        SELECT
          nb.an,
          nb.mother_an,
          nb.born_date,
          nb.birth_weight,
          nb.apgar1,
          nb.apgar2,
          nb.dead,
          nb.has_asphyxia,
          nb.birthcondition1,
          nb.birthcondition2,
          nb.anc_complete,
          DATE_TRUNC('month', nb.born_date)::date AS period_start,
          EXTRACT(MONTH FROM nb.born_date)::integer AS calendar_month
        FROM ipt_newborn nb
        WHERE nb.born_date >= (SELECT fy_start FROM thip_params)
          AND nb.born_date < (SELECT fy_end FROM thip_params)
      ),
      emp_periodized AS (
        SELECT
          e.emp_id,
          e.emp_sex_id,
          e.emp_birthdate,
          e.emp_status_id,
          e.emp_type_id,
          e.emp_dep_id,
          e.emp_position_main_id,
          e.emp_work_begindate,
          e.emp_resign_enddate,
          e.emp_resign_type_id,
          DATE_TRUNC('month', e.emp_work_begindate)::date AS period_start,
          EXTRACT(MONTH FROM e.emp_work_begindate)::integer AS calendar_month
        FROM emp e
        WHERE e.emp_work_begindate >= (SELECT fy_start FROM thip_params)
          AND e.emp_work_begindate < (SELECT fy_end FROM thip_params)
      ),
          facts AS (
      
          SELECT
            'SH0107' AS indicator_code,
            DATE_TRUNC('month', period_start)::date - MAKE_INTERVAL(months => (CASE WHEN calendar_month >= 10 THEN calendar_month - 9 ELSE calendar_month + 3 END) - (CASE WHEN (CASE WHEN calendar_month >= 10 THEN calendar_month - 9 ELSE calendar_month + 3 END) <= 3 THEN 1 WHEN (CASE WHEN calendar_month >= 10 THEN calendar_month - 9 ELSE calendar_month + 3 END) <= 6 THEN 4 WHEN (CASE WHEN calendar_month >= 10 THEN calendar_month - 9 ELSE calendar_month + 3 END) <= 9 THEN 7 ELSE 10 END)) AS period_start,
            CASE WHEN (CASE WHEN calendar_month >= 10 THEN calendar_month - 9 ELSE calendar_month + 3 END) <= 3 THEN 1 WHEN (CASE WHEN calendar_month >= 10 THEN calendar_month - 9 ELSE calendar_month + 3 END) <= 6 THEN 4 WHEN (CASE WHEN calendar_month >= 10 THEN calendar_month - 9 ELSE calendar_month + 3 END) <= 9 THEN 7 ELSE 10 END AS fiscal_month,
            CASE WHEN calendar_month >= 10 THEN EXTRACT(YEAR FROM period_start)::integer + 1 ELSE EXTRACT(YEAR FROM period_start)::integer END AS fiscal_year,
            SUM(hr.voluntary_resign_cnt) AS numerator,
            COUNT(DISTINCT hr.staff_key) FILTER (WHERE hr.active_at_period_end) AS denominator,
            ROUND((SUM(hr.voluntary_resign_cnt)) * 100 / NULLIF(COUNT(DISTINCT hr.staff_key) FILTER (WHERE hr.active_at_period_end), 0), 2) AS value
          FROM (
            SELECT
              e.emp_id AS staff_key,
              DATE_TRUNC('month', months.work_month)::date AS period_start,
              EXTRACT(MONTH FROM months.work_month)::integer AS calendar_month,
              (SELECT COUNT(*)
                FROM emp_resign rr
                LEFT JOIN emp_resign_type rt ON rt.emp_resign_type_id = rr.emp_resign_type_id
                WHERE rr.emp_id = e.emp_id
                  AND rr.emp_resign_date >= months.work_month
                  AND rr.emp_resign_date < months.work_month + INTERVAL '1 month'
                  AND (rt.emp_resign_type_name IS NULL OR rt.emp_resign_type_name NOT ILIKE ANY (ARRAY[U&'%\0E43\0E2B\0E49\0E2D\0E2D\0E01%', U&'%\0E44\0E25\0E48\0E2D\0E2D\0E01%', U&'%\0E1B\0E25\0E14%', U&'%\0E40\0E01\0E29\0E35\0E22\0E13%', U&'%\0E40\0E2A\0E35\0E22\0E0A\0E35\0E27\0E34\0E15%', U&'%\0E16\0E36\0E07\0E41\0E01\0E48\0E01\0E23\0E23\0E21%', U&'%\0E42\0E2D\0E19%', U&'%\0E22\0E49\0E32\0E22%', U&'%\0E15\0E32\0E22%']))) AS voluntary_resign_cnt,
              ((e.emp_work_begindate IS NULL OR e.emp_work_begindate <= (DATE_TRUNC('quarter', months.work_month) + INTERVAL '3 months' - INTERVAL '1 day')) AND (e.emp_resign_enddate IS NULL OR e.emp_resign_enddate >= (DATE_TRUNC('quarter', months.work_month) + INTERVAL '3 months' - INTERVAL '1 day'))) AS active_at_period_end,
              (((NOT (COALESCE(pm.emp_position_main_name, '') ILIKE U&'%\0E41\0E1E\0E17\0E22\0E4C%' AND COALESCE(pm.emp_position_main_name, '') NOT ILIKE U&'%\0E40\0E17\0E04\0E19\0E34\0E04\0E01\0E32\0E23\0E41\0E1E\0E17\0E22\0E4C%' AND COALESCE(pm.emp_position_main_name, '') NOT ILIKE U&'%\0E1C\0E39\0E49\0E0A\0E48\0E27\0E22\0E41\0E1E\0E17\0E22\0E4C%' AND COALESCE(pm.emp_position_main_name, '') NOT ILIKE U&'%\0E41\0E1E\0E17\0E22\0E4C\0E41\0E1C\0E19%')) AND (NOT (COALESCE(pm.emp_position_main_name, '') ILIKE U&'%\0E1E\0E22\0E32\0E1A\0E32\0E25\0E27\0E34\0E0A\0E32\0E0A\0E35\0E1E%' OR (COALESCE(pm.emp_position_main_name, '') ILIKE U&'%\0E1E\0E22\0E32\0E1A\0E32\0E25%' AND COALESCE(pm.emp_position_main_name, '') NOT ILIKE U&'%\0E1C\0E39\0E49\0E0A\0E48\0E27\0E22%' AND COALESCE(pm.emp_position_main_name, '') NOT ILIKE U&'%\0E1E\0E19\0E31\0E01\0E07\0E32\0E19%'))) AND (NOT (COALESCE(pm.emp_position_main_name, '') ILIKE ANY (ARRAY[U&'%\0E1C\0E14\0E38\0E07\0E04\0E23\0E23\0E20\0E4C%', U&'%\0E40\0E20\0E2A\0E31\0E0A%', U&'%\0E1C\0E39\0E49\0E0A\0E48\0E27\0E22\0E41\0E1E\0E17\0E22\0E4C%', U&'%\0E2D\0E32\0E0A\0E35\0E27\0E2D\0E19\0E32\0E21\0E31\0E22%', U&'%\0E2A\0E34\0E48\0E07\0E41\0E27\0E14\0E25\0E49\0E2D\0E21%', U&'%\0E01\0E32\0E22\0E20\0E32\0E1E%', U&'%\0E42\0E20\0E0A\0E19\0E32%', U&'%\0E2A\0E37\0E48\0E2D\0E04\0E27\0E32\0E21\0E2B\0E21\0E32\0E22%', U&'%\0E17\0E31\0E28\0E19\0E21\0E32\0E15\0E23%', U&'%\0E2D\0E32\0E0A\0E35\0E27\0E1A\0E33\0E1A\0E31\0E14%', U&'%\0E01\0E34\0E08\0E01\0E23\0E23\0E21\0E1A\0E33\0E1A\0E31\0E14%', U&'%\0E40\0E17\0E04\0E19\0E34\0E04\0E01\0E32\0E23\0E41\0E1E\0E17\0E22\0E4C%', U&'%\0E40\0E17\0E04\0E19\0E34\0E04\0E1E\0E22\0E32\0E18\0E34%', U&'%\0E1E\0E22\0E32\0E18\0E34%', U&'%\0E1C\0E39\0E49\0E0A\0E48\0E27\0E22\0E40\0E20\0E2A\0E31\0E0A%', U&'%\0E2D\0E38\0E1B\0E01\0E23\0E13\0E4C\0E01\0E32\0E23\0E41\0E1E\0E17\0E22\0E4C\0E40\0E17\0E35\0E22\0E21%', U&'%\0E1E\0E19\0E31\0E01\0E07\0E32\0E19\0E01\0E32\0E23\0E1E\0E22\0E32\0E1A\0E32\0E25%', U&'%\0E1C\0E39\0E49\0E0A\0E48\0E27\0E22\0E17\0E31\0E19\0E15%', U&'%\0E17\0E31\0E19\0E15\0E20\0E34\0E1A\0E32\0E25%', U&'%\0E40\0E27\0E0A\0E23\0E30\0E40\0E1A\0E35\0E22\0E19%', U&'%\0E2A\0E38\0E02\0E20\0E32\0E1E\0E0A\0E38\0E21\0E0A\0E19%', U&'%\0E1B\0E23\0E30\0E01\0E2D\0E1A\0E41\0E27\0E48\0E19%', U&'%\0E1C\0E39\0E49\0E0A\0E48\0E27\0E22\0E19\0E31\0E01\0E01\0E32\0E22\0E20\0E32\0E1E%', U&'%\0E1C\0E39\0E49\0E15\0E23\0E27\0E08\0E2A\0E2D\0E1A%', U&'%\0E23\0E16\0E1E\0E22\0E32\0E1A\0E32\0E25%', U&'%\0E08\0E48\0E32\0E22\0E01\0E25\0E32\0E07%', U&'%\0E40\0E27\0E0A\0E20\0E31\0E13\0E11\0E4C\0E01\0E25\0E32\0E07%', U&'%\0E41\0E1E\0E17\0E22\0E4C\0E41\0E1C\0E19%']))))) AS is_back_office
            FROM emp e
            LEFT JOIN emp_position_main pm ON pm.emp_position_main_id = e.emp_position_main_id
            JOIN GENERATE_SERIES(
              DATE_TRUNC('month', GREATEST(COALESCE(e.emp_work_begindate, (SELECT fy_start FROM thip_params)), (SELECT fy_start FROM thip_params))),
              DATE_TRUNC('month', LEAST(COALESCE(e.emp_resign_enddate, (SELECT fy_end FROM thip_params)), (SELECT fy_end FROM thip_params)) - INTERVAL '1 day'),
              INTERVAL '1 month'
            ) AS months(work_month) ON TRUE
          ) hr
          WHERE hr.is_back_office
          GROUP BY 2, 3, 4
          ), expected_codes(indicator_code, fiscal_month, indicator_name_th, indicator_name_en) AS (
            VALUES
              ('SH0107', 1, U&'\0E2D\0E31\0E15\0E23\0E32\0E01\0E32\0E23\0E25\0E32\0E2D\0E2D\0E01\0020\0E02\0E2D\0E07\0E1A\0E38\0E04\0E25\0E32\0E01\0E23\0E2A\0E32\0E22\0E2A\0E19\0E31\0E1A\0E2A\0E19\0E38\0E19', 'HRM : Turnover rate of back office personnel'), ('SH0107', 4, U&'\0E2D\0E31\0E15\0E23\0E32\0E01\0E32\0E23\0E25\0E32\0E2D\0E2D\0E01\0020\0E02\0E2D\0E07\0E1A\0E38\0E04\0E25\0E32\0E01\0E23\0E2A\0E32\0E22\0E2A\0E19\0E31\0E1A\0E2A\0E19\0E38\0E19', 'HRM : Turnover rate of back office personnel'), ('SH0107', 7, U&'\0E2D\0E31\0E15\0E23\0E32\0E01\0E32\0E23\0E25\0E32\0E2D\0E2D\0E01\0020\0E02\0E2D\0E07\0E1A\0E38\0E04\0E25\0E32\0E01\0E23\0E2A\0E32\0E22\0E2A\0E19\0E31\0E1A\0E2A\0E19\0E38\0E19', 'HRM : Turnover rate of back office personnel'), ('SH0107', 10, U&'\0E2D\0E31\0E15\0E23\0E32\0E01\0E32\0E23\0E25\0E32\0E2D\0E2D\0E01\0020\0E02\0E2D\0E07\0E1A\0E38\0E04\0E25\0E32\0E01\0E23\0E2A\0E32\0E22\0E2A\0E19\0E31\0E1A\0E2A\0E19\0E38\0E19', 'HRM : Turnover rate of back office personnel')
          ), fiscal_periods AS (
            SELECT
              generated.period_start::date AS period_start,
              CASE
                WHEN EXTRACT(MONTH FROM generated.period_start) >= 10
                  THEN EXTRACT(MONTH FROM generated.period_start)::integer - 9
                ELSE EXTRACT(MONTH FROM generated.period_start)::integer + 3
              END AS fiscal_month,
              CASE
                WHEN EXTRACT(MONTH FROM generated.period_start) >= 10
                  THEN EXTRACT(YEAR FROM generated.period_start)::integer + 1
                ELSE EXTRACT(YEAR FROM generated.period_start)::integer
              END AS fiscal_year
            FROM generate_series(
              CAST((SELECT fy_start FROM thip_params) AS date),
              CAST((SELECT fy_end FROM thip_params) AS date) - INTERVAL '1 month',
              INTERVAL '1 month'
            ) AS generated(period_start)
          )
          SELECT
            expected_codes.indicator_code,
            expected_codes.indicator_name_th AS indicator_name_th,
            expected_codes.indicator_name_en AS indicator_name_en,
            fiscal_periods.period_start,
            fiscal_periods.fiscal_month,
            fiscal_periods.fiscal_year,
            COALESCE(facts.numerator, 0) AS numerator,
            COALESCE(facts.denominator, 0) AS denominator,
            facts.value
          FROM expected_codes
          JOIN fiscal_periods
            ON fiscal_periods.fiscal_month = expected_codes.fiscal_month
          LEFT JOIN facts
            ON facts.indicator_code = expected_codes.indicator_code
           AND facts.period_start = fiscal_periods.period_start
           AND facts.fiscal_month = fiscal_periods.fiscal_month
           AND facts.fiscal_year = fiscal_periods.fiscal_year
          ORDER BY expected_codes.indicator_code, fiscal_periods.period_start
  ) AS b_SH0107
  UNION ALL
  SELECT * FROM (
    WITH
          ipd AS (
        SELECT
          i.an,
          i.hn,
          i.regdate,
          i.regtime,
          i.dchdate,
          COALESCE(i.bw, 0) AS bw,
          s.age_y,
          s.los,
          REPLACE(UPPER(TRIM(s.pdx)), '.', '') AS pdx,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
          ) AS died,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') <> REPLACE(UPPER(TRIM(s.pdx)), '.', '')
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
          ) AS has_acs_sdx,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
              AND (
                REPLACE(UPPER(TRIM(d.death_diag_icd10)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_cause)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_1)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_2)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_3)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_4)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
              )
          ) AS died_from_acs,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') <> REPLACE(UPPER(TRIM(s.pdx)), '.', '')
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
          ) AS has_stemi_sdx,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') <> REPLACE(UPPER(TRIM(s.pdx)), '.', '')
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') IN ('I214', 'I219')
          ) AS has_nste_sdx,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
              AND d.death_date IS NOT NULL
              AND (d.death_date + COALESCE(d.death_time, TIME '23:59:59')) >=
                (i.regdate + COALESCE(i.regtime, TIME '00:00:00'))
              AND (d.death_date + COALESCE(d.death_time, TIME '23:59:59')) <=
                (i.regdate + COALESCE(i.regtime, TIME '00:00:00')) + INTERVAL '48 hours'
          ) AS died_within_48h,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
              AND (
                REPLACE(UPPER(TRIM(d.death_diag_icd10)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
                OR REPLACE(UPPER(TRIM(d.death_cause)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
                OR REPLACE(UPPER(TRIM(d.death_diag_1)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
                OR REPLACE(UPPER(TRIM(d.death_diag_2)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
                OR REPLACE(UPPER(TRIM(d.death_diag_3)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
                OR REPLACE(UPPER(TRIM(d.death_diag_4)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
              )
          ) AS died_from_stemi,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
              AND (
                REPLACE(UPPER(TRIM(d.death_diag_icd10)), '.', '') IN ('I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_cause)), '.', '') IN ('I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_1)), '.', '') IN ('I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_2)), '.', '') IN ('I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_3)), '.', '') IN ('I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_4)), '.', '') IN ('I214', 'I219')
              )
          ) AS died_from_nste,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') <> REPLACE(UPPER(TRIM(s.pdx)), '.', '')
              AND (
                LEFT(REPLACE(UPPER(TRIM(sd.icd10)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(sd.icd10)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
              )
          ) AS has_pneumonia_sdx,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
              AND (
                LEFT(REPLACE(UPPER(TRIM(d.death_diag_icd10)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_icd10)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_cause)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_cause)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_1)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_1)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_2)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_2)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_3)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_3)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_4)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_4)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
              )
          ) AS died_from_pneumonia,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') IN ('A400', 'A419', 'R572', 'R651')
          ) AS has_ce0101_sepsis,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') IN ('A400', 'A409', 'A410', 'A419', 'R572', 'R651')
          ) AS has_ci0101_sepsis
        FROM ipt i
        JOIN an_stat s ON s.an = i.an
        WHERE i.dchdate >= (SELECT fy_start FROM thip_params)
          AND i.dchdate < (SELECT fy_end FROM thip_params)
          AND i.regdate IS NOT NULL
          AND EXTRACT(EPOCH FROM (
            (i.dchdate + COALESCE(i.dchtime, TIME '23:59:59')) -
            (i.regdate + COALESCE(i.regtime, TIME '00:00:00'))
          )) >= 14400
      ),
      periodized AS (
        SELECT
          *,
          DATE_TRUNC('month', dchdate)::date AS period_start,
          EXTRACT(MONTH FROM dchdate)::integer AS calendar_month
        FROM ipd
      ),
          opd_periodized AS (
        SELECT
          v.vn,
          v.hn,
          v.an,
          EXTRACT(YEAR FROM AGE(v.vstdate, pd.birthday))::integer AS age_y,
          pd.sex,
          (SELECT REPLACE(UPPER(TRIM(sd.icd10)), '.', '')
             FROM ovstdiag sd
            WHERE sd.vn = v.vn AND sd.diagtype = '1'
            ORDER BY sd.ovst_diag_id
            LIMIT 1) AS pdx,
          v.vstdate AS event_date,
          er.enter_er_time,
          er.triage_datetime,
          er.doctor_tx_time,
          er.finish_time,
          er.antibiotics_datetime,
          er.stroke_needle_datetime,
          er.stemi_balloon_datetime,
          er.er_emergency_level_id,
          er.unplanned_return,
          er.news2_score,
          DATE_TRUNC('month', v.vstdate)::date AS period_start,
          EXTRACT(MONTH FROM v.vstdate)::integer AS calendar_month
        FROM ovst v
        LEFT JOIN patient pd ON pd.hn = v.hn
        LEFT JOIN er_regist er ON er.vn = v.vn
        WHERE v.vstdate >= (SELECT fy_start FROM thip_params)
          AND v.vstdate < (SELECT fy_end FROM thip_params)
      ),
      chronic_periodized AS (
        SELECT
          cm.clinicmember_id,
          cm.clinic,
          cm.hn,
          cm.regdate,
          cm.lastvisit,
          cm.dchdate,
          cm.current_status,
          cm.clinic_member_status_id,
          cm.age_y,
          cm.sex,
          cm.chronic_type,
          cm.begin_year,
          cm.last_hba1c_value,
          cm.last_hba1c_date,
          cm.last_bp_bps_value,
          cm.last_bp_bpd_value,
          cm.last_bp_date,
          DATE_TRUNC('month', cm.regdate)::date AS period_start,
          EXTRACT(MONTH FROM cm.regdate)::integer AS calendar_month
        FROM clinicmember cm
        WHERE cm.regdate >= (SELECT fy_start FROM thip_params)
          AND cm.regdate < (SELECT fy_end FROM thip_params)
      ),
      delivery_periodized AS (
        SELECT
          l.laborid,
          l.an,
          l.hage AS mother_age_y,
          l.labor_type,
          l.mother_method,
          l.infant_sex,
          l.infant_weight,
          l.infant_apgarscore1,
          l.infant_apgarscore5,
          l.infant_apgarscore10,
          l.placenta_bloodloss,
          l.labour_startdate,
          l.labour_finishdate,
          DATE_TRUNC('month', COALESCE(l.labour_startdate, i.regdate))::date AS period_start,
          EXTRACT(MONTH FROM COALESCE(l.labour_startdate, i.regdate))::integer AS calendar_month
        FROM labor l
        LEFT JOIN ipt i ON i.an = l.an
        WHERE COALESCE(l.labour_startdate, i.regdate) >= (SELECT fy_start FROM thip_params)
          AND COALESCE(l.labour_startdate, i.regdate) < (SELECT fy_end FROM thip_params)
      ),
      newborn_periodized AS (
        SELECT
          nb.an,
          nb.mother_an,
          nb.born_date,
          nb.birth_weight,
          nb.apgar1,
          nb.apgar2,
          nb.dead,
          nb.has_asphyxia,
          nb.birthcondition1,
          nb.birthcondition2,
          nb.anc_complete,
          DATE_TRUNC('month', nb.born_date)::date AS period_start,
          EXTRACT(MONTH FROM nb.born_date)::integer AS calendar_month
        FROM ipt_newborn nb
        WHERE nb.born_date >= (SELECT fy_start FROM thip_params)
          AND nb.born_date < (SELECT fy_end FROM thip_params)
      ),
      emp_periodized AS (
        SELECT
          e.emp_id,
          e.emp_sex_id,
          e.emp_birthdate,
          e.emp_status_id,
          e.emp_type_id,
          e.emp_dep_id,
          e.emp_position_main_id,
          e.emp_work_begindate,
          e.emp_resign_enddate,
          e.emp_resign_type_id,
          DATE_TRUNC('month', e.emp_work_begindate)::date AS period_start,
          EXTRACT(MONTH FROM e.emp_work_begindate)::integer AS calendar_month
        FROM emp e
        WHERE e.emp_work_begindate >= (SELECT fy_start FROM thip_params)
          AND e.emp_work_begindate < (SELECT fy_end FROM thip_params)
      ),
          facts AS (
      
          SELECT
            'SH0301' AS indicator_code,
            DATE_TRUNC('month', period_start)::date - MAKE_INTERVAL(months => (CASE WHEN calendar_month >= 10 THEN calendar_month - 9 ELSE calendar_month + 3 END) - (CASE WHEN calendar_month >= 10 THEN calendar_month - 9 ELSE calendar_month + 3 END)) AS period_start,
            CASE WHEN calendar_month >= 10 THEN calendar_month - 9 ELSE calendar_month + 3 END AS fiscal_month,
            CASE WHEN calendar_month >= 10 THEN EXTRACT(YEAR FROM period_start)::integer + 1 ELSE EXTRACT(YEAR FROM period_start)::integer END AS fiscal_year,
            SUM(hr.work_injury_event_cnt) + SUM(hr.work_illness_event_cnt) AS numerator,
            SUM(hr.work_hours) AS denominator,
            ROUND((SUM(hr.work_injury_event_cnt) + SUM(hr.work_illness_event_cnt)) * 1000000 / NULLIF(SUM(hr.work_hours), 0), 2) AS value
          FROM (
            SELECT
              e.emp_id AS staff_key,
              DATE_TRUNC('month', months.work_month)::date AS period_start,
              EXTRACT(MONTH FROM months.work_month)::integer AS calendar_month,
              (SELECT COUNT(*)
                FROM emp_work_sick es
                JOIN emp_work_sick_type st ON st.emp_work_sick_type_id = es.emp_work_sick_type_id
                WHERE es.emp_id = e.emp_id
                  AND es.emp_work_sick_sdatetime >= months.work_month
                  AND es.emp_work_sick_sdatetime < months.work_month + INTERVAL '1 month'
                  AND (st.emp_work_sick_type_name ILIKE U&'%\0E2D\0E31\0E19\0E15\0E23\0E32\0E22%' OR st.emp_work_sick_type_name ILIKE U&'%\0E1A\0E32\0E14\0E40\0E08\0E47\0E1A%' OR st.emp_work_sick_type_name ILIKE U&'%\0E2D\0E38\0E1A\0E31\0E15\0E34\0E40\0E2B\0E15\0E38%')) AS work_injury_event_cnt,
              (SELECT COUNT(*)
                FROM emp_work_sick es
                JOIN emp_work_sick_type st ON st.emp_work_sick_type_id = es.emp_work_sick_type_id
                WHERE es.emp_id = e.emp_id
                  AND es.emp_work_sick_sdatetime >= months.work_month
                  AND es.emp_work_sick_sdatetime < months.work_month + INTERVAL '1 month'
                  AND (st.emp_work_sick_type_name ILIKE U&'%\0E40\0E08\0E47\0E1A\0E1B\0E48\0E27\0E22%' OR st.emp_work_sick_type_name ILIKE U&'%\0E1B\0E27\0E14\0E2B\0E25\0E31\0E07%' OR st.emp_work_sick_type_name ILIKE U&'%\0E40\0E04\0E23\0E35\0E22\0E14%' OR st.emp_work_sick_type_name ILIKE U&'%\0E42\0E23\0E04\0E08\0E32\0E01\0E01\0E32\0E23\0E17\0E33\0E07\0E32\0E19%')) AS work_illness_event_cnt,
              ((SELECT COUNT(*)
                FROM emp_work_schedule wsc
                LEFT JOIN emp_work_status wst ON wst.emp_work_status_id = wsc.emp_work_status_id
                WHERE wsc.emp_id = e.emp_id
                  AND wsc.emp_work_schedule_workdate >= months.work_month
                  AND wsc.emp_work_schedule_workdate < months.work_month + INTERVAL '1 month'
                  AND COALESCE(wst.emp_work_status_name, '') NOT ILIKE U&'%\0E25\0E32%'
                  AND COALESCE(wst.emp_work_status_name, '') NOT ILIKE U&'%\0E2B\0E22\0E38\0E14%'
              ) * 8) AS work_hours
            FROM emp e
            LEFT JOIN emp_position_main pm ON pm.emp_position_main_id = e.emp_position_main_id
            JOIN GENERATE_SERIES(
              DATE_TRUNC('month', GREATEST(COALESCE(e.emp_work_begindate, (SELECT fy_start FROM thip_params)), (SELECT fy_start FROM thip_params))),
              DATE_TRUNC('month', LEAST(COALESCE(e.emp_resign_enddate, (SELECT fy_end FROM thip_params)), (SELECT fy_end FROM thip_params)) - INTERVAL '1 day'),
              INTERVAL '1 month'
            ) AS months(work_month) ON TRUE
          ) hr
          WHERE TRUE
          GROUP BY 2, 3, 4
          ), expected_codes(indicator_code, fiscal_month, indicator_name_th, indicator_name_en) AS (
            VALUES
              ('SH0301', 1, U&'\0E2D\0E31\0E15\0E23\0E32\0E04\0E27\0E32\0E21\0E16\0E35\0E48\0E01\0E32\0E23\0E1A\0E32\0E14\0E40\0E08\0E47\0E1A\002F\0020\0E40\0E08\0E47\0E1A\0E1B\0E48\0E27\0E22\0E02\0E2D\0E07\0E1A\0E38\0E04\0E25\0E32\0E01\0E23\0E17\0E35\0E48\0E40\0E01\0E35\0E48\0E22\0E27\0E40\0E19\0E37\0E48\0E2D\0E07\0E08\0E32\0E01\0E07\0E32\0E19', 'HRH: Injury (illnesses) frequency rate : IFR'), ('SH0301', 2, U&'\0E2D\0E31\0E15\0E23\0E32\0E04\0E27\0E32\0E21\0E16\0E35\0E48\0E01\0E32\0E23\0E1A\0E32\0E14\0E40\0E08\0E47\0E1A\002F\0020\0E40\0E08\0E47\0E1A\0E1B\0E48\0E27\0E22\0E02\0E2D\0E07\0E1A\0E38\0E04\0E25\0E32\0E01\0E23\0E17\0E35\0E48\0E40\0E01\0E35\0E48\0E22\0E27\0E40\0E19\0E37\0E48\0E2D\0E07\0E08\0E32\0E01\0E07\0E32\0E19', 'HRH: Injury (illnesses) frequency rate : IFR'), ('SH0301', 3, U&'\0E2D\0E31\0E15\0E23\0E32\0E04\0E27\0E32\0E21\0E16\0E35\0E48\0E01\0E32\0E23\0E1A\0E32\0E14\0E40\0E08\0E47\0E1A\002F\0020\0E40\0E08\0E47\0E1A\0E1B\0E48\0E27\0E22\0E02\0E2D\0E07\0E1A\0E38\0E04\0E25\0E32\0E01\0E23\0E17\0E35\0E48\0E40\0E01\0E35\0E48\0E22\0E27\0E40\0E19\0E37\0E48\0E2D\0E07\0E08\0E32\0E01\0E07\0E32\0E19', 'HRH: Injury (illnesses) frequency rate : IFR'), ('SH0301', 4, U&'\0E2D\0E31\0E15\0E23\0E32\0E04\0E27\0E32\0E21\0E16\0E35\0E48\0E01\0E32\0E23\0E1A\0E32\0E14\0E40\0E08\0E47\0E1A\002F\0020\0E40\0E08\0E47\0E1A\0E1B\0E48\0E27\0E22\0E02\0E2D\0E07\0E1A\0E38\0E04\0E25\0E32\0E01\0E23\0E17\0E35\0E48\0E40\0E01\0E35\0E48\0E22\0E27\0E40\0E19\0E37\0E48\0E2D\0E07\0E08\0E32\0E01\0E07\0E32\0E19', 'HRH: Injury (illnesses) frequency rate : IFR'), ('SH0301', 5, U&'\0E2D\0E31\0E15\0E23\0E32\0E04\0E27\0E32\0E21\0E16\0E35\0E48\0E01\0E32\0E23\0E1A\0E32\0E14\0E40\0E08\0E47\0E1A\002F\0020\0E40\0E08\0E47\0E1A\0E1B\0E48\0E27\0E22\0E02\0E2D\0E07\0E1A\0E38\0E04\0E25\0E32\0E01\0E23\0E17\0E35\0E48\0E40\0E01\0E35\0E48\0E22\0E27\0E40\0E19\0E37\0E48\0E2D\0E07\0E08\0E32\0E01\0E07\0E32\0E19', 'HRH: Injury (illnesses) frequency rate : IFR'), ('SH0301', 6, U&'\0E2D\0E31\0E15\0E23\0E32\0E04\0E27\0E32\0E21\0E16\0E35\0E48\0E01\0E32\0E23\0E1A\0E32\0E14\0E40\0E08\0E47\0E1A\002F\0020\0E40\0E08\0E47\0E1A\0E1B\0E48\0E27\0E22\0E02\0E2D\0E07\0E1A\0E38\0E04\0E25\0E32\0E01\0E23\0E17\0E35\0E48\0E40\0E01\0E35\0E48\0E22\0E27\0E40\0E19\0E37\0E48\0E2D\0E07\0E08\0E32\0E01\0E07\0E32\0E19', 'HRH: Injury (illnesses) frequency rate : IFR'), ('SH0301', 7, U&'\0E2D\0E31\0E15\0E23\0E32\0E04\0E27\0E32\0E21\0E16\0E35\0E48\0E01\0E32\0E23\0E1A\0E32\0E14\0E40\0E08\0E47\0E1A\002F\0020\0E40\0E08\0E47\0E1A\0E1B\0E48\0E27\0E22\0E02\0E2D\0E07\0E1A\0E38\0E04\0E25\0E32\0E01\0E23\0E17\0E35\0E48\0E40\0E01\0E35\0E48\0E22\0E27\0E40\0E19\0E37\0E48\0E2D\0E07\0E08\0E32\0E01\0E07\0E32\0E19', 'HRH: Injury (illnesses) frequency rate : IFR'), ('SH0301', 8, U&'\0E2D\0E31\0E15\0E23\0E32\0E04\0E27\0E32\0E21\0E16\0E35\0E48\0E01\0E32\0E23\0E1A\0E32\0E14\0E40\0E08\0E47\0E1A\002F\0020\0E40\0E08\0E47\0E1A\0E1B\0E48\0E27\0E22\0E02\0E2D\0E07\0E1A\0E38\0E04\0E25\0E32\0E01\0E23\0E17\0E35\0E48\0E40\0E01\0E35\0E48\0E22\0E27\0E40\0E19\0E37\0E48\0E2D\0E07\0E08\0E32\0E01\0E07\0E32\0E19', 'HRH: Injury (illnesses) frequency rate : IFR'), ('SH0301', 9, U&'\0E2D\0E31\0E15\0E23\0E32\0E04\0E27\0E32\0E21\0E16\0E35\0E48\0E01\0E32\0E23\0E1A\0E32\0E14\0E40\0E08\0E47\0E1A\002F\0020\0E40\0E08\0E47\0E1A\0E1B\0E48\0E27\0E22\0E02\0E2D\0E07\0E1A\0E38\0E04\0E25\0E32\0E01\0E23\0E17\0E35\0E48\0E40\0E01\0E35\0E48\0E22\0E27\0E40\0E19\0E37\0E48\0E2D\0E07\0E08\0E32\0E01\0E07\0E32\0E19', 'HRH: Injury (illnesses) frequency rate : IFR'), ('SH0301', 10, U&'\0E2D\0E31\0E15\0E23\0E32\0E04\0E27\0E32\0E21\0E16\0E35\0E48\0E01\0E32\0E23\0E1A\0E32\0E14\0E40\0E08\0E47\0E1A\002F\0020\0E40\0E08\0E47\0E1A\0E1B\0E48\0E27\0E22\0E02\0E2D\0E07\0E1A\0E38\0E04\0E25\0E32\0E01\0E23\0E17\0E35\0E48\0E40\0E01\0E35\0E48\0E22\0E27\0E40\0E19\0E37\0E48\0E2D\0E07\0E08\0E32\0E01\0E07\0E32\0E19', 'HRH: Injury (illnesses) frequency rate : IFR'), ('SH0301', 11, U&'\0E2D\0E31\0E15\0E23\0E32\0E04\0E27\0E32\0E21\0E16\0E35\0E48\0E01\0E32\0E23\0E1A\0E32\0E14\0E40\0E08\0E47\0E1A\002F\0020\0E40\0E08\0E47\0E1A\0E1B\0E48\0E27\0E22\0E02\0E2D\0E07\0E1A\0E38\0E04\0E25\0E32\0E01\0E23\0E17\0E35\0E48\0E40\0E01\0E35\0E48\0E22\0E27\0E40\0E19\0E37\0E48\0E2D\0E07\0E08\0E32\0E01\0E07\0E32\0E19', 'HRH: Injury (illnesses) frequency rate : IFR'), ('SH0301', 12, U&'\0E2D\0E31\0E15\0E23\0E32\0E04\0E27\0E32\0E21\0E16\0E35\0E48\0E01\0E32\0E23\0E1A\0E32\0E14\0E40\0E08\0E47\0E1A\002F\0020\0E40\0E08\0E47\0E1A\0E1B\0E48\0E27\0E22\0E02\0E2D\0E07\0E1A\0E38\0E04\0E25\0E32\0E01\0E23\0E17\0E35\0E48\0E40\0E01\0E35\0E48\0E22\0E27\0E40\0E19\0E37\0E48\0E2D\0E07\0E08\0E32\0E01\0E07\0E32\0E19', 'HRH: Injury (illnesses) frequency rate : IFR')
          ), fiscal_periods AS (
            SELECT
              generated.period_start::date AS period_start,
              CASE
                WHEN EXTRACT(MONTH FROM generated.period_start) >= 10
                  THEN EXTRACT(MONTH FROM generated.period_start)::integer - 9
                ELSE EXTRACT(MONTH FROM generated.period_start)::integer + 3
              END AS fiscal_month,
              CASE
                WHEN EXTRACT(MONTH FROM generated.period_start) >= 10
                  THEN EXTRACT(YEAR FROM generated.period_start)::integer + 1
                ELSE EXTRACT(YEAR FROM generated.period_start)::integer
              END AS fiscal_year
            FROM generate_series(
              CAST((SELECT fy_start FROM thip_params) AS date),
              CAST((SELECT fy_end FROM thip_params) AS date) - INTERVAL '1 month',
              INTERVAL '1 month'
            ) AS generated(period_start)
          )
          SELECT
            expected_codes.indicator_code,
            expected_codes.indicator_name_th AS indicator_name_th,
            expected_codes.indicator_name_en AS indicator_name_en,
            fiscal_periods.period_start,
            fiscal_periods.fiscal_month,
            fiscal_periods.fiscal_year,
            COALESCE(facts.numerator, 0) AS numerator,
            COALESCE(facts.denominator, 0) AS denominator,
            facts.value
          FROM expected_codes
          JOIN fiscal_periods
            ON fiscal_periods.fiscal_month = expected_codes.fiscal_month
          LEFT JOIN facts
            ON facts.indicator_code = expected_codes.indicator_code
           AND facts.period_start = fiscal_periods.period_start
           AND facts.fiscal_month = fiscal_periods.fiscal_month
           AND facts.fiscal_year = fiscal_periods.fiscal_year
          ORDER BY expected_codes.indicator_code, fiscal_periods.period_start
  ) AS b_SH0301
  UNION ALL
  SELECT * FROM (
    WITH
          ipd AS (
        SELECT
          i.an,
          i.hn,
          i.regdate,
          i.regtime,
          i.dchdate,
          COALESCE(i.bw, 0) AS bw,
          s.age_y,
          s.los,
          REPLACE(UPPER(TRIM(s.pdx)), '.', '') AS pdx,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
          ) AS died,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') <> REPLACE(UPPER(TRIM(s.pdx)), '.', '')
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
          ) AS has_acs_sdx,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
              AND (
                REPLACE(UPPER(TRIM(d.death_diag_icd10)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_cause)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_1)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_2)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_3)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_4)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
              )
          ) AS died_from_acs,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') <> REPLACE(UPPER(TRIM(s.pdx)), '.', '')
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
          ) AS has_stemi_sdx,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') <> REPLACE(UPPER(TRIM(s.pdx)), '.', '')
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') IN ('I214', 'I219')
          ) AS has_nste_sdx,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
              AND d.death_date IS NOT NULL
              AND (d.death_date + COALESCE(d.death_time, TIME '23:59:59')) >=
                (i.regdate + COALESCE(i.regtime, TIME '00:00:00'))
              AND (d.death_date + COALESCE(d.death_time, TIME '23:59:59')) <=
                (i.regdate + COALESCE(i.regtime, TIME '00:00:00')) + INTERVAL '48 hours'
          ) AS died_within_48h,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
              AND (
                REPLACE(UPPER(TRIM(d.death_diag_icd10)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
                OR REPLACE(UPPER(TRIM(d.death_cause)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
                OR REPLACE(UPPER(TRIM(d.death_diag_1)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
                OR REPLACE(UPPER(TRIM(d.death_diag_2)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
                OR REPLACE(UPPER(TRIM(d.death_diag_3)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
                OR REPLACE(UPPER(TRIM(d.death_diag_4)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
              )
          ) AS died_from_stemi,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
              AND (
                REPLACE(UPPER(TRIM(d.death_diag_icd10)), '.', '') IN ('I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_cause)), '.', '') IN ('I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_1)), '.', '') IN ('I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_2)), '.', '') IN ('I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_3)), '.', '') IN ('I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_4)), '.', '') IN ('I214', 'I219')
              )
          ) AS died_from_nste,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') <> REPLACE(UPPER(TRIM(s.pdx)), '.', '')
              AND (
                LEFT(REPLACE(UPPER(TRIM(sd.icd10)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(sd.icd10)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
              )
          ) AS has_pneumonia_sdx,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
              AND (
                LEFT(REPLACE(UPPER(TRIM(d.death_diag_icd10)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_icd10)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_cause)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_cause)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_1)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_1)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_2)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_2)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_3)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_3)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_4)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_4)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
              )
          ) AS died_from_pneumonia,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') IN ('A400', 'A419', 'R572', 'R651')
          ) AS has_ce0101_sepsis,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') IN ('A400', 'A409', 'A410', 'A419', 'R572', 'R651')
          ) AS has_ci0101_sepsis
        FROM ipt i
        JOIN an_stat s ON s.an = i.an
        WHERE i.dchdate >= (SELECT fy_start FROM thip_params)
          AND i.dchdate < (SELECT fy_end FROM thip_params)
          AND i.regdate IS NOT NULL
          AND EXTRACT(EPOCH FROM (
            (i.dchdate + COALESCE(i.dchtime, TIME '23:59:59')) -
            (i.regdate + COALESCE(i.regtime, TIME '00:00:00'))
          )) >= 14400
      ),
      periodized AS (
        SELECT
          *,
          DATE_TRUNC('month', dchdate)::date AS period_start,
          EXTRACT(MONTH FROM dchdate)::integer AS calendar_month
        FROM ipd
      ),
          opd_periodized AS (
        SELECT
          v.vn,
          v.hn,
          v.an,
          EXTRACT(YEAR FROM AGE(v.vstdate, pd.birthday))::integer AS age_y,
          pd.sex,
          (SELECT REPLACE(UPPER(TRIM(sd.icd10)), '.', '')
             FROM ovstdiag sd
            WHERE sd.vn = v.vn AND sd.diagtype = '1'
            ORDER BY sd.ovst_diag_id
            LIMIT 1) AS pdx,
          v.vstdate AS event_date,
          er.enter_er_time,
          er.triage_datetime,
          er.doctor_tx_time,
          er.finish_time,
          er.antibiotics_datetime,
          er.stroke_needle_datetime,
          er.stemi_balloon_datetime,
          er.er_emergency_level_id,
          er.unplanned_return,
          er.news2_score,
          DATE_TRUNC('month', v.vstdate)::date AS period_start,
          EXTRACT(MONTH FROM v.vstdate)::integer AS calendar_month
        FROM ovst v
        LEFT JOIN patient pd ON pd.hn = v.hn
        LEFT JOIN er_regist er ON er.vn = v.vn
        WHERE v.vstdate >= (SELECT fy_start FROM thip_params)
          AND v.vstdate < (SELECT fy_end FROM thip_params)
      ),
      chronic_periodized AS (
        SELECT
          cm.clinicmember_id,
          cm.clinic,
          cm.hn,
          cm.regdate,
          cm.lastvisit,
          cm.dchdate,
          cm.current_status,
          cm.clinic_member_status_id,
          cm.age_y,
          cm.sex,
          cm.chronic_type,
          cm.begin_year,
          cm.last_hba1c_value,
          cm.last_hba1c_date,
          cm.last_bp_bps_value,
          cm.last_bp_bpd_value,
          cm.last_bp_date,
          DATE_TRUNC('month', cm.regdate)::date AS period_start,
          EXTRACT(MONTH FROM cm.regdate)::integer AS calendar_month
        FROM clinicmember cm
        WHERE cm.regdate >= (SELECT fy_start FROM thip_params)
          AND cm.regdate < (SELECT fy_end FROM thip_params)
      ),
      delivery_periodized AS (
        SELECT
          l.laborid,
          l.an,
          l.hage AS mother_age_y,
          l.labor_type,
          l.mother_method,
          l.infant_sex,
          l.infant_weight,
          l.infant_apgarscore1,
          l.infant_apgarscore5,
          l.infant_apgarscore10,
          l.placenta_bloodloss,
          l.labour_startdate,
          l.labour_finishdate,
          DATE_TRUNC('month', COALESCE(l.labour_startdate, i.regdate))::date AS period_start,
          EXTRACT(MONTH FROM COALESCE(l.labour_startdate, i.regdate))::integer AS calendar_month
        FROM labor l
        LEFT JOIN ipt i ON i.an = l.an
        WHERE COALESCE(l.labour_startdate, i.regdate) >= (SELECT fy_start FROM thip_params)
          AND COALESCE(l.labour_startdate, i.regdate) < (SELECT fy_end FROM thip_params)
      ),
      newborn_periodized AS (
        SELECT
          nb.an,
          nb.mother_an,
          nb.born_date,
          nb.birth_weight,
          nb.apgar1,
          nb.apgar2,
          nb.dead,
          nb.has_asphyxia,
          nb.birthcondition1,
          nb.birthcondition2,
          nb.anc_complete,
          DATE_TRUNC('month', nb.born_date)::date AS period_start,
          EXTRACT(MONTH FROM nb.born_date)::integer AS calendar_month
        FROM ipt_newborn nb
        WHERE nb.born_date >= (SELECT fy_start FROM thip_params)
          AND nb.born_date < (SELECT fy_end FROM thip_params)
      ),
      emp_periodized AS (
        SELECT
          e.emp_id,
          e.emp_sex_id,
          e.emp_birthdate,
          e.emp_status_id,
          e.emp_type_id,
          e.emp_dep_id,
          e.emp_position_main_id,
          e.emp_work_begindate,
          e.emp_resign_enddate,
          e.emp_resign_type_id,
          DATE_TRUNC('month', e.emp_work_begindate)::date AS period_start,
          EXTRACT(MONTH FROM e.emp_work_begindate)::integer AS calendar_month
        FROM emp e
        WHERE e.emp_work_begindate >= (SELECT fy_start FROM thip_params)
          AND e.emp_work_begindate < (SELECT fy_end FROM thip_params)
      ),
          facts AS (
      
          SELECT
            'SH0302' AS indicator_code,
            DATE_TRUNC('month', period_start)::date - MAKE_INTERVAL(months => (CASE WHEN calendar_month >= 10 THEN calendar_month - 9 ELSE calendar_month + 3 END) - (CASE WHEN calendar_month >= 10 THEN calendar_month - 9 ELSE calendar_month + 3 END)) AS period_start,
            CASE WHEN calendar_month >= 10 THEN calendar_month - 9 ELSE calendar_month + 3 END AS fiscal_month,
            CASE WHEN calendar_month >= 10 THEN EXTRACT(YEAR FROM period_start)::integer + 1 ELSE EXTRACT(YEAR FROM period_start)::integer END AS fiscal_year,
            SUM(hr.injury_lost_days) AS numerator,
            SUM(hr.work_hours) AS denominator,
            ROUND((SUM(hr.injury_lost_days)) * 1000000 / NULLIF(SUM(hr.work_hours), 0), 2) AS value
          FROM (
            SELECT
              e.emp_id AS staff_key,
              DATE_TRUNC('month', months.work_month)::date AS period_start,
              EXTRACT(MONTH FROM months.work_month)::integer AS calendar_month,
              (SELECT COALESCE(SUM(es.emp_work_sick_countday), 0)
                FROM emp_work_sick es
                JOIN emp_work_sick_type st ON st.emp_work_sick_type_id = es.emp_work_sick_type_id
                WHERE es.emp_id = e.emp_id
                  AND es.emp_work_sick_sdatetime >= months.work_month
                  AND es.emp_work_sick_sdatetime < months.work_month + INTERVAL '1 month'
                  AND (st.emp_work_sick_type_name ILIKE U&'%\0E2D\0E31\0E19\0E15\0E23\0E32\0E22%' OR st.emp_work_sick_type_name ILIKE U&'%\0E1A\0E32\0E14\0E40\0E08\0E47\0E1A%' OR st.emp_work_sick_type_name ILIKE U&'%\0E2D\0E38\0E1A\0E31\0E15\0E34\0E40\0E2B\0E15\0E38%')) AS injury_lost_days,
              ((SELECT COUNT(*)
                FROM emp_work_schedule wsc
                LEFT JOIN emp_work_status wst ON wst.emp_work_status_id = wsc.emp_work_status_id
                WHERE wsc.emp_id = e.emp_id
                  AND wsc.emp_work_schedule_workdate >= months.work_month
                  AND wsc.emp_work_schedule_workdate < months.work_month + INTERVAL '1 month'
                  AND COALESCE(wst.emp_work_status_name, '') NOT ILIKE U&'%\0E25\0E32%'
                  AND COALESCE(wst.emp_work_status_name, '') NOT ILIKE U&'%\0E2B\0E22\0E38\0E14%'
              ) * 8) AS work_hours,
              (((COALESCE(pm.emp_position_main_name, '') ILIKE U&'%\0E41\0E1E\0E17\0E22\0E4C%' AND COALESCE(pm.emp_position_main_name, '') NOT ILIKE U&'%\0E40\0E17\0E04\0E19\0E34\0E04\0E01\0E32\0E23\0E41\0E1E\0E17\0E22\0E4C%' AND COALESCE(pm.emp_position_main_name, '') NOT ILIKE U&'%\0E1C\0E39\0E49\0E0A\0E48\0E27\0E22\0E41\0E1E\0E17\0E22\0E4C%' AND COALESCE(pm.emp_position_main_name, '') NOT ILIKE U&'%\0E41\0E1E\0E17\0E22\0E4C\0E41\0E1C\0E19%') OR (COALESCE(pm.emp_position_main_name, '') ILIKE U&'%\0E1E\0E22\0E32\0E1A\0E32\0E25\0E27\0E34\0E0A\0E32\0E0A\0E35\0E1E%' OR (COALESCE(pm.emp_position_main_name, '') ILIKE U&'%\0E1E\0E22\0E32\0E1A\0E32\0E25%' AND COALESCE(pm.emp_position_main_name, '') NOT ILIKE U&'%\0E1C\0E39\0E49\0E0A\0E48\0E27\0E22%' AND COALESCE(pm.emp_position_main_name, '') NOT ILIKE U&'%\0E1E\0E19\0E31\0E01\0E07\0E32\0E19%')) OR ((NOT (COALESCE(pm.emp_position_main_name, '') ILIKE U&'%\0E41\0E1E\0E17\0E22\0E4C%' AND COALESCE(pm.emp_position_main_name, '') NOT ILIKE U&'%\0E40\0E17\0E04\0E19\0E34\0E04\0E01\0E32\0E23\0E41\0E1E\0E17\0E22\0E4C%' AND COALESCE(pm.emp_position_main_name, '') NOT ILIKE U&'%\0E1C\0E39\0E49\0E0A\0E48\0E27\0E22\0E41\0E1E\0E17\0E22\0E4C%' AND COALESCE(pm.emp_position_main_name, '') NOT ILIKE U&'%\0E41\0E1E\0E17\0E22\0E4C\0E41\0E1C\0E19%')) AND (NOT (COALESCE(pm.emp_position_main_name, '') ILIKE U&'%\0E1E\0E22\0E32\0E1A\0E32\0E25\0E27\0E34\0E0A\0E32\0E0A\0E35\0E1E%' OR (COALESCE(pm.emp_position_main_name, '') ILIKE U&'%\0E1E\0E22\0E32\0E1A\0E32\0E25%' AND COALESCE(pm.emp_position_main_name, '') NOT ILIKE U&'%\0E1C\0E39\0E49\0E0A\0E48\0E27\0E22%' AND COALESCE(pm.emp_position_main_name, '') NOT ILIKE U&'%\0E1E\0E19\0E31\0E01\0E07\0E32\0E19%'))) AND (COALESCE(pm.emp_position_main_name, '') ILIKE ANY (ARRAY[U&'%\0E1C\0E14\0E38\0E07\0E04\0E23\0E23\0E20\0E4C%', U&'%\0E40\0E20\0E2A\0E31\0E0A%', U&'%\0E1C\0E39\0E49\0E0A\0E48\0E27\0E22\0E41\0E1E\0E17\0E22\0E4C%', U&'%\0E2D\0E32\0E0A\0E35\0E27\0E2D\0E19\0E32\0E21\0E31\0E22%', U&'%\0E2A\0E34\0E48\0E07\0E41\0E27\0E14\0E25\0E49\0E2D\0E21%', U&'%\0E01\0E32\0E22\0E20\0E32\0E1E%', U&'%\0E42\0E20\0E0A\0E19\0E32%', U&'%\0E2A\0E37\0E48\0E2D\0E04\0E27\0E32\0E21\0E2B\0E21\0E32\0E22%', U&'%\0E17\0E31\0E28\0E19\0E21\0E32\0E15\0E23%', U&'%\0E2D\0E32\0E0A\0E35\0E27\0E1A\0E33\0E1A\0E31\0E14%', U&'%\0E01\0E34\0E08\0E01\0E23\0E23\0E21\0E1A\0E33\0E1A\0E31\0E14%', U&'%\0E40\0E17\0E04\0E19\0E34\0E04\0E01\0E32\0E23\0E41\0E1E\0E17\0E22\0E4C%', U&'%\0E40\0E17\0E04\0E19\0E34\0E04\0E1E\0E22\0E32\0E18\0E34%', U&'%\0E1E\0E22\0E32\0E18\0E34%', U&'%\0E1C\0E39\0E49\0E0A\0E48\0E27\0E22\0E40\0E20\0E2A\0E31\0E0A%', U&'%\0E2D\0E38\0E1B\0E01\0E23\0E13\0E4C\0E01\0E32\0E23\0E41\0E1E\0E17\0E22\0E4C\0E40\0E17\0E35\0E22\0E21%', U&'%\0E1E\0E19\0E31\0E01\0E07\0E32\0E19\0E01\0E32\0E23\0E1E\0E22\0E32\0E1A\0E32\0E25%', U&'%\0E1C\0E39\0E49\0E0A\0E48\0E27\0E22\0E17\0E31\0E19\0E15%', U&'%\0E17\0E31\0E19\0E15\0E20\0E34\0E1A\0E32\0E25%', U&'%\0E40\0E27\0E0A\0E23\0E30\0E40\0E1A\0E35\0E22\0E19%', U&'%\0E2A\0E38\0E02\0E20\0E32\0E1E\0E0A\0E38\0E21\0E0A\0E19%', U&'%\0E1B\0E23\0E30\0E01\0E2D\0E1A\0E41\0E27\0E48\0E19%', U&'%\0E1C\0E39\0E49\0E0A\0E48\0E27\0E22\0E19\0E31\0E01\0E01\0E32\0E22\0E20\0E32\0E1E%', U&'%\0E1C\0E39\0E49\0E15\0E23\0E27\0E08\0E2A\0E2D\0E1A%', U&'%\0E23\0E16\0E1E\0E22\0E32\0E1A\0E32\0E25%', U&'%\0E08\0E48\0E32\0E22\0E01\0E25\0E32\0E07%', U&'%\0E40\0E27\0E0A\0E20\0E31\0E13\0E11\0E4C\0E01\0E25\0E32\0E07%', U&'%\0E41\0E1E\0E17\0E22\0E4C\0E41\0E1C\0E19%']))))) AS is_direct_contact
            FROM emp e
            LEFT JOIN emp_position_main pm ON pm.emp_position_main_id = e.emp_position_main_id
            JOIN GENERATE_SERIES(
              DATE_TRUNC('month', GREATEST(COALESCE(e.emp_work_begindate, (SELECT fy_start FROM thip_params)), (SELECT fy_start FROM thip_params))),
              DATE_TRUNC('month', LEAST(COALESCE(e.emp_resign_enddate, (SELECT fy_end FROM thip_params)), (SELECT fy_end FROM thip_params)) - INTERVAL '1 day'),
              INTERVAL '1 month'
            ) AS months(work_month) ON TRUE
          ) hr
          WHERE hr.is_direct_contact
          GROUP BY 2, 3, 4
          ), expected_codes(indicator_code, fiscal_month, indicator_name_th, indicator_name_en) AS (
            VALUES
              ('SH0302', 1, U&'\0E2D\0E31\0E15\0E23\0E32\0E04\0E27\0E32\0E21\0E23\0E38\0E19\0E41\0E23\0E07\0E02\0E2D\0E07\0E01\0E32\0E23\0E1A\0E32\0E14\0E40\0E08\0E47\0E1A\0E02\0E2D\0E07\0E1A\0E38\0E04\0E25\0E32\0E01\0E23\0E01\0E25\0E38\0E48\0E21\0E2A\0E31\0E21\0E1C\0E31\0E2A\0E1C\0E39\0E49\0E1B\0E48\0E27\0E22\0E42\0E14\0E22\0E15\0E23\0E07', 'HRH: Injury severity rate (ISR) of direct contact with patients'), ('SH0302', 2, U&'\0E2D\0E31\0E15\0E23\0E32\0E04\0E27\0E32\0E21\0E23\0E38\0E19\0E41\0E23\0E07\0E02\0E2D\0E07\0E01\0E32\0E23\0E1A\0E32\0E14\0E40\0E08\0E47\0E1A\0E02\0E2D\0E07\0E1A\0E38\0E04\0E25\0E32\0E01\0E23\0E01\0E25\0E38\0E48\0E21\0E2A\0E31\0E21\0E1C\0E31\0E2A\0E1C\0E39\0E49\0E1B\0E48\0E27\0E22\0E42\0E14\0E22\0E15\0E23\0E07', 'HRH: Injury severity rate (ISR) of direct contact with patients'), ('SH0302', 3, U&'\0E2D\0E31\0E15\0E23\0E32\0E04\0E27\0E32\0E21\0E23\0E38\0E19\0E41\0E23\0E07\0E02\0E2D\0E07\0E01\0E32\0E23\0E1A\0E32\0E14\0E40\0E08\0E47\0E1A\0E02\0E2D\0E07\0E1A\0E38\0E04\0E25\0E32\0E01\0E23\0E01\0E25\0E38\0E48\0E21\0E2A\0E31\0E21\0E1C\0E31\0E2A\0E1C\0E39\0E49\0E1B\0E48\0E27\0E22\0E42\0E14\0E22\0E15\0E23\0E07', 'HRH: Injury severity rate (ISR) of direct contact with patients'), ('SH0302', 4, U&'\0E2D\0E31\0E15\0E23\0E32\0E04\0E27\0E32\0E21\0E23\0E38\0E19\0E41\0E23\0E07\0E02\0E2D\0E07\0E01\0E32\0E23\0E1A\0E32\0E14\0E40\0E08\0E47\0E1A\0E02\0E2D\0E07\0E1A\0E38\0E04\0E25\0E32\0E01\0E23\0E01\0E25\0E38\0E48\0E21\0E2A\0E31\0E21\0E1C\0E31\0E2A\0E1C\0E39\0E49\0E1B\0E48\0E27\0E22\0E42\0E14\0E22\0E15\0E23\0E07', 'HRH: Injury severity rate (ISR) of direct contact with patients'), ('SH0302', 5, U&'\0E2D\0E31\0E15\0E23\0E32\0E04\0E27\0E32\0E21\0E23\0E38\0E19\0E41\0E23\0E07\0E02\0E2D\0E07\0E01\0E32\0E23\0E1A\0E32\0E14\0E40\0E08\0E47\0E1A\0E02\0E2D\0E07\0E1A\0E38\0E04\0E25\0E32\0E01\0E23\0E01\0E25\0E38\0E48\0E21\0E2A\0E31\0E21\0E1C\0E31\0E2A\0E1C\0E39\0E49\0E1B\0E48\0E27\0E22\0E42\0E14\0E22\0E15\0E23\0E07', 'HRH: Injury severity rate (ISR) of direct contact with patients'), ('SH0302', 6, U&'\0E2D\0E31\0E15\0E23\0E32\0E04\0E27\0E32\0E21\0E23\0E38\0E19\0E41\0E23\0E07\0E02\0E2D\0E07\0E01\0E32\0E23\0E1A\0E32\0E14\0E40\0E08\0E47\0E1A\0E02\0E2D\0E07\0E1A\0E38\0E04\0E25\0E32\0E01\0E23\0E01\0E25\0E38\0E48\0E21\0E2A\0E31\0E21\0E1C\0E31\0E2A\0E1C\0E39\0E49\0E1B\0E48\0E27\0E22\0E42\0E14\0E22\0E15\0E23\0E07', 'HRH: Injury severity rate (ISR) of direct contact with patients'), ('SH0302', 7, U&'\0E2D\0E31\0E15\0E23\0E32\0E04\0E27\0E32\0E21\0E23\0E38\0E19\0E41\0E23\0E07\0E02\0E2D\0E07\0E01\0E32\0E23\0E1A\0E32\0E14\0E40\0E08\0E47\0E1A\0E02\0E2D\0E07\0E1A\0E38\0E04\0E25\0E32\0E01\0E23\0E01\0E25\0E38\0E48\0E21\0E2A\0E31\0E21\0E1C\0E31\0E2A\0E1C\0E39\0E49\0E1B\0E48\0E27\0E22\0E42\0E14\0E22\0E15\0E23\0E07', 'HRH: Injury severity rate (ISR) of direct contact with patients'), ('SH0302', 8, U&'\0E2D\0E31\0E15\0E23\0E32\0E04\0E27\0E32\0E21\0E23\0E38\0E19\0E41\0E23\0E07\0E02\0E2D\0E07\0E01\0E32\0E23\0E1A\0E32\0E14\0E40\0E08\0E47\0E1A\0E02\0E2D\0E07\0E1A\0E38\0E04\0E25\0E32\0E01\0E23\0E01\0E25\0E38\0E48\0E21\0E2A\0E31\0E21\0E1C\0E31\0E2A\0E1C\0E39\0E49\0E1B\0E48\0E27\0E22\0E42\0E14\0E22\0E15\0E23\0E07', 'HRH: Injury severity rate (ISR) of direct contact with patients'), ('SH0302', 9, U&'\0E2D\0E31\0E15\0E23\0E32\0E04\0E27\0E32\0E21\0E23\0E38\0E19\0E41\0E23\0E07\0E02\0E2D\0E07\0E01\0E32\0E23\0E1A\0E32\0E14\0E40\0E08\0E47\0E1A\0E02\0E2D\0E07\0E1A\0E38\0E04\0E25\0E32\0E01\0E23\0E01\0E25\0E38\0E48\0E21\0E2A\0E31\0E21\0E1C\0E31\0E2A\0E1C\0E39\0E49\0E1B\0E48\0E27\0E22\0E42\0E14\0E22\0E15\0E23\0E07', 'HRH: Injury severity rate (ISR) of direct contact with patients'), ('SH0302', 10, U&'\0E2D\0E31\0E15\0E23\0E32\0E04\0E27\0E32\0E21\0E23\0E38\0E19\0E41\0E23\0E07\0E02\0E2D\0E07\0E01\0E32\0E23\0E1A\0E32\0E14\0E40\0E08\0E47\0E1A\0E02\0E2D\0E07\0E1A\0E38\0E04\0E25\0E32\0E01\0E23\0E01\0E25\0E38\0E48\0E21\0E2A\0E31\0E21\0E1C\0E31\0E2A\0E1C\0E39\0E49\0E1B\0E48\0E27\0E22\0E42\0E14\0E22\0E15\0E23\0E07', 'HRH: Injury severity rate (ISR) of direct contact with patients'), ('SH0302', 11, U&'\0E2D\0E31\0E15\0E23\0E32\0E04\0E27\0E32\0E21\0E23\0E38\0E19\0E41\0E23\0E07\0E02\0E2D\0E07\0E01\0E32\0E23\0E1A\0E32\0E14\0E40\0E08\0E47\0E1A\0E02\0E2D\0E07\0E1A\0E38\0E04\0E25\0E32\0E01\0E23\0E01\0E25\0E38\0E48\0E21\0E2A\0E31\0E21\0E1C\0E31\0E2A\0E1C\0E39\0E49\0E1B\0E48\0E27\0E22\0E42\0E14\0E22\0E15\0E23\0E07', 'HRH: Injury severity rate (ISR) of direct contact with patients'), ('SH0302', 12, U&'\0E2D\0E31\0E15\0E23\0E32\0E04\0E27\0E32\0E21\0E23\0E38\0E19\0E41\0E23\0E07\0E02\0E2D\0E07\0E01\0E32\0E23\0E1A\0E32\0E14\0E40\0E08\0E47\0E1A\0E02\0E2D\0E07\0E1A\0E38\0E04\0E25\0E32\0E01\0E23\0E01\0E25\0E38\0E48\0E21\0E2A\0E31\0E21\0E1C\0E31\0E2A\0E1C\0E39\0E49\0E1B\0E48\0E27\0E22\0E42\0E14\0E22\0E15\0E23\0E07', 'HRH: Injury severity rate (ISR) of direct contact with patients')
          ), fiscal_periods AS (
            SELECT
              generated.period_start::date AS period_start,
              CASE
                WHEN EXTRACT(MONTH FROM generated.period_start) >= 10
                  THEN EXTRACT(MONTH FROM generated.period_start)::integer - 9
                ELSE EXTRACT(MONTH FROM generated.period_start)::integer + 3
              END AS fiscal_month,
              CASE
                WHEN EXTRACT(MONTH FROM generated.period_start) >= 10
                  THEN EXTRACT(YEAR FROM generated.period_start)::integer + 1
                ELSE EXTRACT(YEAR FROM generated.period_start)::integer
              END AS fiscal_year
            FROM generate_series(
              CAST((SELECT fy_start FROM thip_params) AS date),
              CAST((SELECT fy_end FROM thip_params) AS date) - INTERVAL '1 month',
              INTERVAL '1 month'
            ) AS generated(period_start)
          )
          SELECT
            expected_codes.indicator_code,
            expected_codes.indicator_name_th AS indicator_name_th,
            expected_codes.indicator_name_en AS indicator_name_en,
            fiscal_periods.period_start,
            fiscal_periods.fiscal_month,
            fiscal_periods.fiscal_year,
            COALESCE(facts.numerator, 0) AS numerator,
            COALESCE(facts.denominator, 0) AS denominator,
            facts.value
          FROM expected_codes
          JOIN fiscal_periods
            ON fiscal_periods.fiscal_month = expected_codes.fiscal_month
          LEFT JOIN facts
            ON facts.indicator_code = expected_codes.indicator_code
           AND facts.period_start = fiscal_periods.period_start
           AND facts.fiscal_month = fiscal_periods.fiscal_month
           AND facts.fiscal_year = fiscal_periods.fiscal_year
          ORDER BY expected_codes.indicator_code, fiscal_periods.period_start
  ) AS b_SH0302
  UNION ALL
  SELECT * FROM (
    WITH
          ipd AS (
        SELECT
          i.an,
          i.hn,
          i.regdate,
          i.regtime,
          i.dchdate,
          COALESCE(i.bw, 0) AS bw,
          s.age_y,
          s.los,
          REPLACE(UPPER(TRIM(s.pdx)), '.', '') AS pdx,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
          ) AS died,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') <> REPLACE(UPPER(TRIM(s.pdx)), '.', '')
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
          ) AS has_acs_sdx,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
              AND (
                REPLACE(UPPER(TRIM(d.death_diag_icd10)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_cause)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_1)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_2)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_3)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_4)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
              )
          ) AS died_from_acs,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') <> REPLACE(UPPER(TRIM(s.pdx)), '.', '')
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
          ) AS has_stemi_sdx,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') <> REPLACE(UPPER(TRIM(s.pdx)), '.', '')
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') IN ('I214', 'I219')
          ) AS has_nste_sdx,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
              AND d.death_date IS NOT NULL
              AND (d.death_date + COALESCE(d.death_time, TIME '23:59:59')) >=
                (i.regdate + COALESCE(i.regtime, TIME '00:00:00'))
              AND (d.death_date + COALESCE(d.death_time, TIME '23:59:59')) <=
                (i.regdate + COALESCE(i.regtime, TIME '00:00:00')) + INTERVAL '48 hours'
          ) AS died_within_48h,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
              AND (
                REPLACE(UPPER(TRIM(d.death_diag_icd10)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
                OR REPLACE(UPPER(TRIM(d.death_cause)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
                OR REPLACE(UPPER(TRIM(d.death_diag_1)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
                OR REPLACE(UPPER(TRIM(d.death_diag_2)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
                OR REPLACE(UPPER(TRIM(d.death_diag_3)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
                OR REPLACE(UPPER(TRIM(d.death_diag_4)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
              )
          ) AS died_from_stemi,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
              AND (
                REPLACE(UPPER(TRIM(d.death_diag_icd10)), '.', '') IN ('I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_cause)), '.', '') IN ('I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_1)), '.', '') IN ('I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_2)), '.', '') IN ('I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_3)), '.', '') IN ('I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_4)), '.', '') IN ('I214', 'I219')
              )
          ) AS died_from_nste,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') <> REPLACE(UPPER(TRIM(s.pdx)), '.', '')
              AND (
                LEFT(REPLACE(UPPER(TRIM(sd.icd10)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(sd.icd10)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
              )
          ) AS has_pneumonia_sdx,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
              AND (
                LEFT(REPLACE(UPPER(TRIM(d.death_diag_icd10)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_icd10)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_cause)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_cause)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_1)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_1)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_2)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_2)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_3)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_3)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_4)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_4)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
              )
          ) AS died_from_pneumonia,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') IN ('A400', 'A419', 'R572', 'R651')
          ) AS has_ce0101_sepsis,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') IN ('A400', 'A409', 'A410', 'A419', 'R572', 'R651')
          ) AS has_ci0101_sepsis
        FROM ipt i
        JOIN an_stat s ON s.an = i.an
        WHERE i.dchdate >= (SELECT fy_start FROM thip_params)
          AND i.dchdate < (SELECT fy_end FROM thip_params)
          AND i.regdate IS NOT NULL
          AND EXTRACT(EPOCH FROM (
            (i.dchdate + COALESCE(i.dchtime, TIME '23:59:59')) -
            (i.regdate + COALESCE(i.regtime, TIME '00:00:00'))
          )) >= 14400
      ),
      periodized AS (
        SELECT
          *,
          DATE_TRUNC('month', dchdate)::date AS period_start,
          EXTRACT(MONTH FROM dchdate)::integer AS calendar_month
        FROM ipd
      ),
          opd_periodized AS (
        SELECT
          v.vn,
          v.hn,
          v.an,
          EXTRACT(YEAR FROM AGE(v.vstdate, pd.birthday))::integer AS age_y,
          pd.sex,
          (SELECT REPLACE(UPPER(TRIM(sd.icd10)), '.', '')
             FROM ovstdiag sd
            WHERE sd.vn = v.vn AND sd.diagtype = '1'
            ORDER BY sd.ovst_diag_id
            LIMIT 1) AS pdx,
          v.vstdate AS event_date,
          er.enter_er_time,
          er.triage_datetime,
          er.doctor_tx_time,
          er.finish_time,
          er.antibiotics_datetime,
          er.stroke_needle_datetime,
          er.stemi_balloon_datetime,
          er.er_emergency_level_id,
          er.unplanned_return,
          er.news2_score,
          DATE_TRUNC('month', v.vstdate)::date AS period_start,
          EXTRACT(MONTH FROM v.vstdate)::integer AS calendar_month
        FROM ovst v
        LEFT JOIN patient pd ON pd.hn = v.hn
        LEFT JOIN er_regist er ON er.vn = v.vn
        WHERE v.vstdate >= (SELECT fy_start FROM thip_params)
          AND v.vstdate < (SELECT fy_end FROM thip_params)
      ),
      chronic_periodized AS (
        SELECT
          cm.clinicmember_id,
          cm.clinic,
          cm.hn,
          cm.regdate,
          cm.lastvisit,
          cm.dchdate,
          cm.current_status,
          cm.clinic_member_status_id,
          cm.age_y,
          cm.sex,
          cm.chronic_type,
          cm.begin_year,
          cm.last_hba1c_value,
          cm.last_hba1c_date,
          cm.last_bp_bps_value,
          cm.last_bp_bpd_value,
          cm.last_bp_date,
          DATE_TRUNC('month', cm.regdate)::date AS period_start,
          EXTRACT(MONTH FROM cm.regdate)::integer AS calendar_month
        FROM clinicmember cm
        WHERE cm.regdate >= (SELECT fy_start FROM thip_params)
          AND cm.regdate < (SELECT fy_end FROM thip_params)
      ),
      delivery_periodized AS (
        SELECT
          l.laborid,
          l.an,
          l.hage AS mother_age_y,
          l.labor_type,
          l.mother_method,
          l.infant_sex,
          l.infant_weight,
          l.infant_apgarscore1,
          l.infant_apgarscore5,
          l.infant_apgarscore10,
          l.placenta_bloodloss,
          l.labour_startdate,
          l.labour_finishdate,
          DATE_TRUNC('month', COALESCE(l.labour_startdate, i.regdate))::date AS period_start,
          EXTRACT(MONTH FROM COALESCE(l.labour_startdate, i.regdate))::integer AS calendar_month
        FROM labor l
        LEFT JOIN ipt i ON i.an = l.an
        WHERE COALESCE(l.labour_startdate, i.regdate) >= (SELECT fy_start FROM thip_params)
          AND COALESCE(l.labour_startdate, i.regdate) < (SELECT fy_end FROM thip_params)
      ),
      newborn_periodized AS (
        SELECT
          nb.an,
          nb.mother_an,
          nb.born_date,
          nb.birth_weight,
          nb.apgar1,
          nb.apgar2,
          nb.dead,
          nb.has_asphyxia,
          nb.birthcondition1,
          nb.birthcondition2,
          nb.anc_complete,
          DATE_TRUNC('month', nb.born_date)::date AS period_start,
          EXTRACT(MONTH FROM nb.born_date)::integer AS calendar_month
        FROM ipt_newborn nb
        WHERE nb.born_date >= (SELECT fy_start FROM thip_params)
          AND nb.born_date < (SELECT fy_end FROM thip_params)
      ),
      emp_periodized AS (
        SELECT
          e.emp_id,
          e.emp_sex_id,
          e.emp_birthdate,
          e.emp_status_id,
          e.emp_type_id,
          e.emp_dep_id,
          e.emp_position_main_id,
          e.emp_work_begindate,
          e.emp_resign_enddate,
          e.emp_resign_type_id,
          DATE_TRUNC('month', e.emp_work_begindate)::date AS period_start,
          EXTRACT(MONTH FROM e.emp_work_begindate)::integer AS calendar_month
        FROM emp e
        WHERE e.emp_work_begindate >= (SELECT fy_start FROM thip_params)
          AND e.emp_work_begindate < (SELECT fy_end FROM thip_params)
      ),
          facts AS (
      
          SELECT
            'SH0303' AS indicator_code,
            DATE_TRUNC('month', period_start)::date - MAKE_INTERVAL(months => (CASE WHEN calendar_month >= 10 THEN calendar_month - 9 ELSE calendar_month + 3 END) - (CASE WHEN calendar_month >= 10 THEN calendar_month - 9 ELSE calendar_month + 3 END)) AS period_start,
            CASE WHEN calendar_month >= 10 THEN calendar_month - 9 ELSE calendar_month + 3 END AS fiscal_month,
            CASE WHEN calendar_month >= 10 THEN EXTRACT(YEAR FROM period_start)::integer + 1 ELSE EXTRACT(YEAR FROM period_start)::integer END AS fiscal_year,
            SUM(hr.injury_lost_days) AS numerator,
            SUM(hr.work_hours) AS denominator,
            ROUND((SUM(hr.injury_lost_days)) * 1000000 / NULLIF(SUM(hr.work_hours), 0), 2) AS value
          FROM (
            SELECT
              e.emp_id AS staff_key,
              DATE_TRUNC('month', months.work_month)::date AS period_start,
              EXTRACT(MONTH FROM months.work_month)::integer AS calendar_month,
              (SELECT COALESCE(SUM(es.emp_work_sick_countday), 0)
                FROM emp_work_sick es
                JOIN emp_work_sick_type st ON st.emp_work_sick_type_id = es.emp_work_sick_type_id
                WHERE es.emp_id = e.emp_id
                  AND es.emp_work_sick_sdatetime >= months.work_month
                  AND es.emp_work_sick_sdatetime < months.work_month + INTERVAL '1 month'
                  AND (st.emp_work_sick_type_name ILIKE U&'%\0E2D\0E31\0E19\0E15\0E23\0E32\0E22%' OR st.emp_work_sick_type_name ILIKE U&'%\0E1A\0E32\0E14\0E40\0E08\0E47\0E1A%' OR st.emp_work_sick_type_name ILIKE U&'%\0E2D\0E38\0E1A\0E31\0E15\0E34\0E40\0E2B\0E15\0E38%')) AS injury_lost_days,
              ((SELECT COUNT(*)
                FROM emp_work_schedule wsc
                LEFT JOIN emp_work_status wst ON wst.emp_work_status_id = wsc.emp_work_status_id
                WHERE wsc.emp_id = e.emp_id
                  AND wsc.emp_work_schedule_workdate >= months.work_month
                  AND wsc.emp_work_schedule_workdate < months.work_month + INTERVAL '1 month'
                  AND COALESCE(wst.emp_work_status_name, '') NOT ILIKE U&'%\0E25\0E32%'
                  AND COALESCE(wst.emp_work_status_name, '') NOT ILIKE U&'%\0E2B\0E22\0E38\0E14%'
              ) * 8) AS work_hours,
              (((NOT (COALESCE(pm.emp_position_main_name, '') ILIKE U&'%\0E41\0E1E\0E17\0E22\0E4C%' AND COALESCE(pm.emp_position_main_name, '') NOT ILIKE U&'%\0E40\0E17\0E04\0E19\0E34\0E04\0E01\0E32\0E23\0E41\0E1E\0E17\0E22\0E4C%' AND COALESCE(pm.emp_position_main_name, '') NOT ILIKE U&'%\0E1C\0E39\0E49\0E0A\0E48\0E27\0E22\0E41\0E1E\0E17\0E22\0E4C%' AND COALESCE(pm.emp_position_main_name, '') NOT ILIKE U&'%\0E41\0E1E\0E17\0E22\0E4C\0E41\0E1C\0E19%')) AND (NOT (COALESCE(pm.emp_position_main_name, '') ILIKE U&'%\0E1E\0E22\0E32\0E1A\0E32\0E25\0E27\0E34\0E0A\0E32\0E0A\0E35\0E1E%' OR (COALESCE(pm.emp_position_main_name, '') ILIKE U&'%\0E1E\0E22\0E32\0E1A\0E32\0E25%' AND COALESCE(pm.emp_position_main_name, '') NOT ILIKE U&'%\0E1C\0E39\0E49\0E0A\0E48\0E27\0E22%' AND COALESCE(pm.emp_position_main_name, '') NOT ILIKE U&'%\0E1E\0E19\0E31\0E01\0E07\0E32\0E19%'))) AND (NOT (COALESCE(pm.emp_position_main_name, '') ILIKE ANY (ARRAY[U&'%\0E1C\0E14\0E38\0E07\0E04\0E23\0E23\0E20\0E4C%', U&'%\0E40\0E20\0E2A\0E31\0E0A%', U&'%\0E1C\0E39\0E49\0E0A\0E48\0E27\0E22\0E41\0E1E\0E17\0E22\0E4C%', U&'%\0E2D\0E32\0E0A\0E35\0E27\0E2D\0E19\0E32\0E21\0E31\0E22%', U&'%\0E2A\0E34\0E48\0E07\0E41\0E27\0E14\0E25\0E49\0E2D\0E21%', U&'%\0E01\0E32\0E22\0E20\0E32\0E1E%', U&'%\0E42\0E20\0E0A\0E19\0E32%', U&'%\0E2A\0E37\0E48\0E2D\0E04\0E27\0E32\0E21\0E2B\0E21\0E32\0E22%', U&'%\0E17\0E31\0E28\0E19\0E21\0E32\0E15\0E23%', U&'%\0E2D\0E32\0E0A\0E35\0E27\0E1A\0E33\0E1A\0E31\0E14%', U&'%\0E01\0E34\0E08\0E01\0E23\0E23\0E21\0E1A\0E33\0E1A\0E31\0E14%', U&'%\0E40\0E17\0E04\0E19\0E34\0E04\0E01\0E32\0E23\0E41\0E1E\0E17\0E22\0E4C%', U&'%\0E40\0E17\0E04\0E19\0E34\0E04\0E1E\0E22\0E32\0E18\0E34%', U&'%\0E1E\0E22\0E32\0E18\0E34%', U&'%\0E1C\0E39\0E49\0E0A\0E48\0E27\0E22\0E40\0E20\0E2A\0E31\0E0A%', U&'%\0E2D\0E38\0E1B\0E01\0E23\0E13\0E4C\0E01\0E32\0E23\0E41\0E1E\0E17\0E22\0E4C\0E40\0E17\0E35\0E22\0E21%', U&'%\0E1E\0E19\0E31\0E01\0E07\0E32\0E19\0E01\0E32\0E23\0E1E\0E22\0E32\0E1A\0E32\0E25%', U&'%\0E1C\0E39\0E49\0E0A\0E48\0E27\0E22\0E17\0E31\0E19\0E15%', U&'%\0E17\0E31\0E19\0E15\0E20\0E34\0E1A\0E32\0E25%', U&'%\0E40\0E27\0E0A\0E23\0E30\0E40\0E1A\0E35\0E22\0E19%', U&'%\0E2A\0E38\0E02\0E20\0E32\0E1E\0E0A\0E38\0E21\0E0A\0E19%', U&'%\0E1B\0E23\0E30\0E01\0E2D\0E1A\0E41\0E27\0E48\0E19%', U&'%\0E1C\0E39\0E49\0E0A\0E48\0E27\0E22\0E19\0E31\0E01\0E01\0E32\0E22\0E20\0E32\0E1E%', U&'%\0E1C\0E39\0E49\0E15\0E23\0E27\0E08\0E2A\0E2D\0E1A%', U&'%\0E23\0E16\0E1E\0E22\0E32\0E1A\0E32\0E25%', U&'%\0E08\0E48\0E32\0E22\0E01\0E25\0E32\0E07%', U&'%\0E40\0E27\0E0A\0E20\0E31\0E13\0E11\0E4C\0E01\0E25\0E32\0E07%', U&'%\0E41\0E1E\0E17\0E22\0E4C\0E41\0E1C\0E19%']))))) AS is_back_office
            FROM emp e
            LEFT JOIN emp_position_main pm ON pm.emp_position_main_id = e.emp_position_main_id
            JOIN GENERATE_SERIES(
              DATE_TRUNC('month', GREATEST(COALESCE(e.emp_work_begindate, (SELECT fy_start FROM thip_params)), (SELECT fy_start FROM thip_params))),
              DATE_TRUNC('month', LEAST(COALESCE(e.emp_resign_enddate, (SELECT fy_end FROM thip_params)), (SELECT fy_end FROM thip_params)) - INTERVAL '1 day'),
              INTERVAL '1 month'
            ) AS months(work_month) ON TRUE
          ) hr
          WHERE hr.is_back_office
          GROUP BY 2, 3, 4
          ), expected_codes(indicator_code, fiscal_month, indicator_name_th, indicator_name_en) AS (
            VALUES
              ('SH0303', 1, U&'\0E2D\0E31\0E15\0E23\0E32\0E04\0E27\0E32\0E21\0E23\0E38\0E19\0E41\0E23\0E07\0E02\0E2D\0E07\0E01\0E32\0E23\0E1A\0E32\0E14\0E40\0E08\0E47\0E1A\0E02\0E2D\0E07\0E1A\0E38\0E04\0E25\0E32\0E01\0E23\0E01\0E25\0E38\0E48\0E21\0E17\0E35\0E48\0E44\0E21\0E48\0E44\0E14\0E49\0E2A\0E31\0E21\0E1C\0E31\0E2A\0E1C\0E39\0E49\0E1B\0E48\0E27\0E22\0E42\0E14\0E22\0E15\0E23\0E07', 'HRH: Injury severity rate (ISR) of non direct contact with patients'), ('SH0303', 2, U&'\0E2D\0E31\0E15\0E23\0E32\0E04\0E27\0E32\0E21\0E23\0E38\0E19\0E41\0E23\0E07\0E02\0E2D\0E07\0E01\0E32\0E23\0E1A\0E32\0E14\0E40\0E08\0E47\0E1A\0E02\0E2D\0E07\0E1A\0E38\0E04\0E25\0E32\0E01\0E23\0E01\0E25\0E38\0E48\0E21\0E17\0E35\0E48\0E44\0E21\0E48\0E44\0E14\0E49\0E2A\0E31\0E21\0E1C\0E31\0E2A\0E1C\0E39\0E49\0E1B\0E48\0E27\0E22\0E42\0E14\0E22\0E15\0E23\0E07', 'HRH: Injury severity rate (ISR) of non direct contact with patients'), ('SH0303', 3, U&'\0E2D\0E31\0E15\0E23\0E32\0E04\0E27\0E32\0E21\0E23\0E38\0E19\0E41\0E23\0E07\0E02\0E2D\0E07\0E01\0E32\0E23\0E1A\0E32\0E14\0E40\0E08\0E47\0E1A\0E02\0E2D\0E07\0E1A\0E38\0E04\0E25\0E32\0E01\0E23\0E01\0E25\0E38\0E48\0E21\0E17\0E35\0E48\0E44\0E21\0E48\0E44\0E14\0E49\0E2A\0E31\0E21\0E1C\0E31\0E2A\0E1C\0E39\0E49\0E1B\0E48\0E27\0E22\0E42\0E14\0E22\0E15\0E23\0E07', 'HRH: Injury severity rate (ISR) of non direct contact with patients'), ('SH0303', 4, U&'\0E2D\0E31\0E15\0E23\0E32\0E04\0E27\0E32\0E21\0E23\0E38\0E19\0E41\0E23\0E07\0E02\0E2D\0E07\0E01\0E32\0E23\0E1A\0E32\0E14\0E40\0E08\0E47\0E1A\0E02\0E2D\0E07\0E1A\0E38\0E04\0E25\0E32\0E01\0E23\0E01\0E25\0E38\0E48\0E21\0E17\0E35\0E48\0E44\0E21\0E48\0E44\0E14\0E49\0E2A\0E31\0E21\0E1C\0E31\0E2A\0E1C\0E39\0E49\0E1B\0E48\0E27\0E22\0E42\0E14\0E22\0E15\0E23\0E07', 'HRH: Injury severity rate (ISR) of non direct contact with patients'), ('SH0303', 5, U&'\0E2D\0E31\0E15\0E23\0E32\0E04\0E27\0E32\0E21\0E23\0E38\0E19\0E41\0E23\0E07\0E02\0E2D\0E07\0E01\0E32\0E23\0E1A\0E32\0E14\0E40\0E08\0E47\0E1A\0E02\0E2D\0E07\0E1A\0E38\0E04\0E25\0E32\0E01\0E23\0E01\0E25\0E38\0E48\0E21\0E17\0E35\0E48\0E44\0E21\0E48\0E44\0E14\0E49\0E2A\0E31\0E21\0E1C\0E31\0E2A\0E1C\0E39\0E49\0E1B\0E48\0E27\0E22\0E42\0E14\0E22\0E15\0E23\0E07', 'HRH: Injury severity rate (ISR) of non direct contact with patients'), ('SH0303', 6, U&'\0E2D\0E31\0E15\0E23\0E32\0E04\0E27\0E32\0E21\0E23\0E38\0E19\0E41\0E23\0E07\0E02\0E2D\0E07\0E01\0E32\0E23\0E1A\0E32\0E14\0E40\0E08\0E47\0E1A\0E02\0E2D\0E07\0E1A\0E38\0E04\0E25\0E32\0E01\0E23\0E01\0E25\0E38\0E48\0E21\0E17\0E35\0E48\0E44\0E21\0E48\0E44\0E14\0E49\0E2A\0E31\0E21\0E1C\0E31\0E2A\0E1C\0E39\0E49\0E1B\0E48\0E27\0E22\0E42\0E14\0E22\0E15\0E23\0E07', 'HRH: Injury severity rate (ISR) of non direct contact with patients'), ('SH0303', 7, U&'\0E2D\0E31\0E15\0E23\0E32\0E04\0E27\0E32\0E21\0E23\0E38\0E19\0E41\0E23\0E07\0E02\0E2D\0E07\0E01\0E32\0E23\0E1A\0E32\0E14\0E40\0E08\0E47\0E1A\0E02\0E2D\0E07\0E1A\0E38\0E04\0E25\0E32\0E01\0E23\0E01\0E25\0E38\0E48\0E21\0E17\0E35\0E48\0E44\0E21\0E48\0E44\0E14\0E49\0E2A\0E31\0E21\0E1C\0E31\0E2A\0E1C\0E39\0E49\0E1B\0E48\0E27\0E22\0E42\0E14\0E22\0E15\0E23\0E07', 'HRH: Injury severity rate (ISR) of non direct contact with patients'), ('SH0303', 8, U&'\0E2D\0E31\0E15\0E23\0E32\0E04\0E27\0E32\0E21\0E23\0E38\0E19\0E41\0E23\0E07\0E02\0E2D\0E07\0E01\0E32\0E23\0E1A\0E32\0E14\0E40\0E08\0E47\0E1A\0E02\0E2D\0E07\0E1A\0E38\0E04\0E25\0E32\0E01\0E23\0E01\0E25\0E38\0E48\0E21\0E17\0E35\0E48\0E44\0E21\0E48\0E44\0E14\0E49\0E2A\0E31\0E21\0E1C\0E31\0E2A\0E1C\0E39\0E49\0E1B\0E48\0E27\0E22\0E42\0E14\0E22\0E15\0E23\0E07', 'HRH: Injury severity rate (ISR) of non direct contact with patients'), ('SH0303', 9, U&'\0E2D\0E31\0E15\0E23\0E32\0E04\0E27\0E32\0E21\0E23\0E38\0E19\0E41\0E23\0E07\0E02\0E2D\0E07\0E01\0E32\0E23\0E1A\0E32\0E14\0E40\0E08\0E47\0E1A\0E02\0E2D\0E07\0E1A\0E38\0E04\0E25\0E32\0E01\0E23\0E01\0E25\0E38\0E48\0E21\0E17\0E35\0E48\0E44\0E21\0E48\0E44\0E14\0E49\0E2A\0E31\0E21\0E1C\0E31\0E2A\0E1C\0E39\0E49\0E1B\0E48\0E27\0E22\0E42\0E14\0E22\0E15\0E23\0E07', 'HRH: Injury severity rate (ISR) of non direct contact with patients'), ('SH0303', 10, U&'\0E2D\0E31\0E15\0E23\0E32\0E04\0E27\0E32\0E21\0E23\0E38\0E19\0E41\0E23\0E07\0E02\0E2D\0E07\0E01\0E32\0E23\0E1A\0E32\0E14\0E40\0E08\0E47\0E1A\0E02\0E2D\0E07\0E1A\0E38\0E04\0E25\0E32\0E01\0E23\0E01\0E25\0E38\0E48\0E21\0E17\0E35\0E48\0E44\0E21\0E48\0E44\0E14\0E49\0E2A\0E31\0E21\0E1C\0E31\0E2A\0E1C\0E39\0E49\0E1B\0E48\0E27\0E22\0E42\0E14\0E22\0E15\0E23\0E07', 'HRH: Injury severity rate (ISR) of non direct contact with patients'), ('SH0303', 11, U&'\0E2D\0E31\0E15\0E23\0E32\0E04\0E27\0E32\0E21\0E23\0E38\0E19\0E41\0E23\0E07\0E02\0E2D\0E07\0E01\0E32\0E23\0E1A\0E32\0E14\0E40\0E08\0E47\0E1A\0E02\0E2D\0E07\0E1A\0E38\0E04\0E25\0E32\0E01\0E23\0E01\0E25\0E38\0E48\0E21\0E17\0E35\0E48\0E44\0E21\0E48\0E44\0E14\0E49\0E2A\0E31\0E21\0E1C\0E31\0E2A\0E1C\0E39\0E49\0E1B\0E48\0E27\0E22\0E42\0E14\0E22\0E15\0E23\0E07', 'HRH: Injury severity rate (ISR) of non direct contact with patients'), ('SH0303', 12, U&'\0E2D\0E31\0E15\0E23\0E32\0E04\0E27\0E32\0E21\0E23\0E38\0E19\0E41\0E23\0E07\0E02\0E2D\0E07\0E01\0E32\0E23\0E1A\0E32\0E14\0E40\0E08\0E47\0E1A\0E02\0E2D\0E07\0E1A\0E38\0E04\0E25\0E32\0E01\0E23\0E01\0E25\0E38\0E48\0E21\0E17\0E35\0E48\0E44\0E21\0E48\0E44\0E14\0E49\0E2A\0E31\0E21\0E1C\0E31\0E2A\0E1C\0E39\0E49\0E1B\0E48\0E27\0E22\0E42\0E14\0E22\0E15\0E23\0E07', 'HRH: Injury severity rate (ISR) of non direct contact with patients')
          ), fiscal_periods AS (
            SELECT
              generated.period_start::date AS period_start,
              CASE
                WHEN EXTRACT(MONTH FROM generated.period_start) >= 10
                  THEN EXTRACT(MONTH FROM generated.period_start)::integer - 9
                ELSE EXTRACT(MONTH FROM generated.period_start)::integer + 3
              END AS fiscal_month,
              CASE
                WHEN EXTRACT(MONTH FROM generated.period_start) >= 10
                  THEN EXTRACT(YEAR FROM generated.period_start)::integer + 1
                ELSE EXTRACT(YEAR FROM generated.period_start)::integer
              END AS fiscal_year
            FROM generate_series(
              CAST((SELECT fy_start FROM thip_params) AS date),
              CAST((SELECT fy_end FROM thip_params) AS date) - INTERVAL '1 month',
              INTERVAL '1 month'
            ) AS generated(period_start)
          )
          SELECT
            expected_codes.indicator_code,
            expected_codes.indicator_name_th AS indicator_name_th,
            expected_codes.indicator_name_en AS indicator_name_en,
            fiscal_periods.period_start,
            fiscal_periods.fiscal_month,
            fiscal_periods.fiscal_year,
            COALESCE(facts.numerator, 0) AS numerator,
            COALESCE(facts.denominator, 0) AS denominator,
            facts.value
          FROM expected_codes
          JOIN fiscal_periods
            ON fiscal_periods.fiscal_month = expected_codes.fiscal_month
          LEFT JOIN facts
            ON facts.indicator_code = expected_codes.indicator_code
           AND facts.period_start = fiscal_periods.period_start
           AND facts.fiscal_month = fiscal_periods.fiscal_month
           AND facts.fiscal_year = fiscal_periods.fiscal_year
          ORDER BY expected_codes.indicator_code, fiscal_periods.period_start
  ) AS b_SH0303
  UNION ALL
  SELECT * FROM (
    WITH
          ipd AS (
        SELECT
          i.an,
          i.hn,
          i.regdate,
          i.regtime,
          i.dchdate,
          COALESCE(i.bw, 0) AS bw,
          s.age_y,
          s.los,
          REPLACE(UPPER(TRIM(s.pdx)), '.', '') AS pdx,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
          ) AS died,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') <> REPLACE(UPPER(TRIM(s.pdx)), '.', '')
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
          ) AS has_acs_sdx,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
              AND (
                REPLACE(UPPER(TRIM(d.death_diag_icd10)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_cause)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_1)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_2)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_3)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_4)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
              )
          ) AS died_from_acs,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') <> REPLACE(UPPER(TRIM(s.pdx)), '.', '')
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
          ) AS has_stemi_sdx,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') <> REPLACE(UPPER(TRIM(s.pdx)), '.', '')
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') IN ('I214', 'I219')
          ) AS has_nste_sdx,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
              AND d.death_date IS NOT NULL
              AND (d.death_date + COALESCE(d.death_time, TIME '23:59:59')) >=
                (i.regdate + COALESCE(i.regtime, TIME '00:00:00'))
              AND (d.death_date + COALESCE(d.death_time, TIME '23:59:59')) <=
                (i.regdate + COALESCE(i.regtime, TIME '00:00:00')) + INTERVAL '48 hours'
          ) AS died_within_48h,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
              AND (
                REPLACE(UPPER(TRIM(d.death_diag_icd10)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
                OR REPLACE(UPPER(TRIM(d.death_cause)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
                OR REPLACE(UPPER(TRIM(d.death_diag_1)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
                OR REPLACE(UPPER(TRIM(d.death_diag_2)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
                OR REPLACE(UPPER(TRIM(d.death_diag_3)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
                OR REPLACE(UPPER(TRIM(d.death_diag_4)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
              )
          ) AS died_from_stemi,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
              AND (
                REPLACE(UPPER(TRIM(d.death_diag_icd10)), '.', '') IN ('I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_cause)), '.', '') IN ('I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_1)), '.', '') IN ('I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_2)), '.', '') IN ('I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_3)), '.', '') IN ('I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_4)), '.', '') IN ('I214', 'I219')
              )
          ) AS died_from_nste,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') <> REPLACE(UPPER(TRIM(s.pdx)), '.', '')
              AND (
                LEFT(REPLACE(UPPER(TRIM(sd.icd10)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(sd.icd10)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
              )
          ) AS has_pneumonia_sdx,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
              AND (
                LEFT(REPLACE(UPPER(TRIM(d.death_diag_icd10)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_icd10)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_cause)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_cause)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_1)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_1)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_2)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_2)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_3)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_3)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_4)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_4)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
              )
          ) AS died_from_pneumonia,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') IN ('A400', 'A419', 'R572', 'R651')
          ) AS has_ce0101_sepsis,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') IN ('A400', 'A409', 'A410', 'A419', 'R572', 'R651')
          ) AS has_ci0101_sepsis
        FROM ipt i
        JOIN an_stat s ON s.an = i.an
        WHERE i.dchdate >= (SELECT fy_start FROM thip_params)
          AND i.dchdate < (SELECT fy_end FROM thip_params)
          AND i.regdate IS NOT NULL
          AND EXTRACT(EPOCH FROM (
            (i.dchdate + COALESCE(i.dchtime, TIME '23:59:59')) -
            (i.regdate + COALESCE(i.regtime, TIME '00:00:00'))
          )) >= 14400
      ),
      periodized AS (
        SELECT
          *,
          DATE_TRUNC('month', dchdate)::date AS period_start,
          EXTRACT(MONTH FROM dchdate)::integer AS calendar_month
        FROM ipd
      ),
          opd_periodized AS (
        SELECT
          v.vn,
          v.hn,
          v.an,
          EXTRACT(YEAR FROM AGE(v.vstdate, pd.birthday))::integer AS age_y,
          pd.sex,
          (SELECT REPLACE(UPPER(TRIM(sd.icd10)), '.', '')
             FROM ovstdiag sd
            WHERE sd.vn = v.vn AND sd.diagtype = '1'
            ORDER BY sd.ovst_diag_id
            LIMIT 1) AS pdx,
          v.vstdate AS event_date,
          er.enter_er_time,
          er.triage_datetime,
          er.doctor_tx_time,
          er.finish_time,
          er.antibiotics_datetime,
          er.stroke_needle_datetime,
          er.stemi_balloon_datetime,
          er.er_emergency_level_id,
          er.unplanned_return,
          er.news2_score,
          DATE_TRUNC('month', v.vstdate)::date AS period_start,
          EXTRACT(MONTH FROM v.vstdate)::integer AS calendar_month
        FROM ovst v
        LEFT JOIN patient pd ON pd.hn = v.hn
        LEFT JOIN er_regist er ON er.vn = v.vn
        WHERE v.vstdate >= (SELECT fy_start FROM thip_params)
          AND v.vstdate < (SELECT fy_end FROM thip_params)
      ),
      chronic_periodized AS (
        SELECT
          cm.clinicmember_id,
          cm.clinic,
          cm.hn,
          cm.regdate,
          cm.lastvisit,
          cm.dchdate,
          cm.current_status,
          cm.clinic_member_status_id,
          cm.age_y,
          cm.sex,
          cm.chronic_type,
          cm.begin_year,
          cm.last_hba1c_value,
          cm.last_hba1c_date,
          cm.last_bp_bps_value,
          cm.last_bp_bpd_value,
          cm.last_bp_date,
          DATE_TRUNC('month', cm.regdate)::date AS period_start,
          EXTRACT(MONTH FROM cm.regdate)::integer AS calendar_month
        FROM clinicmember cm
        WHERE cm.regdate >= (SELECT fy_start FROM thip_params)
          AND cm.regdate < (SELECT fy_end FROM thip_params)
      ),
      delivery_periodized AS (
        SELECT
          l.laborid,
          l.an,
          l.hage AS mother_age_y,
          l.labor_type,
          l.mother_method,
          l.infant_sex,
          l.infant_weight,
          l.infant_apgarscore1,
          l.infant_apgarscore5,
          l.infant_apgarscore10,
          l.placenta_bloodloss,
          l.labour_startdate,
          l.labour_finishdate,
          DATE_TRUNC('month', COALESCE(l.labour_startdate, i.regdate))::date AS period_start,
          EXTRACT(MONTH FROM COALESCE(l.labour_startdate, i.regdate))::integer AS calendar_month
        FROM labor l
        LEFT JOIN ipt i ON i.an = l.an
        WHERE COALESCE(l.labour_startdate, i.regdate) >= (SELECT fy_start FROM thip_params)
          AND COALESCE(l.labour_startdate, i.regdate) < (SELECT fy_end FROM thip_params)
      ),
      newborn_periodized AS (
        SELECT
          nb.an,
          nb.mother_an,
          nb.born_date,
          nb.birth_weight,
          nb.apgar1,
          nb.apgar2,
          nb.dead,
          nb.has_asphyxia,
          nb.birthcondition1,
          nb.birthcondition2,
          nb.anc_complete,
          DATE_TRUNC('month', nb.born_date)::date AS period_start,
          EXTRACT(MONTH FROM nb.born_date)::integer AS calendar_month
        FROM ipt_newborn nb
        WHERE nb.born_date >= (SELECT fy_start FROM thip_params)
          AND nb.born_date < (SELECT fy_end FROM thip_params)
      ),
      emp_periodized AS (
        SELECT
          e.emp_id,
          e.emp_sex_id,
          e.emp_birthdate,
          e.emp_status_id,
          e.emp_type_id,
          e.emp_dep_id,
          e.emp_position_main_id,
          e.emp_work_begindate,
          e.emp_resign_enddate,
          e.emp_resign_type_id,
          DATE_TRUNC('month', e.emp_work_begindate)::date AS period_start,
          EXTRACT(MONTH FROM e.emp_work_begindate)::integer AS calendar_month
        FROM emp e
        WHERE e.emp_work_begindate >= (SELECT fy_start FROM thip_params)
          AND e.emp_work_begindate < (SELECT fy_end FROM thip_params)
      ),
          facts AS (
      
          SELECT
            'SH0306' AS indicator_code,
            DATE_TRUNC('month', period_start)::date - MAKE_INTERVAL(months => (CASE WHEN calendar_month >= 10 THEN calendar_month - 9 ELSE calendar_month + 3 END) - (CASE WHEN calendar_month >= 10 THEN calendar_month - 9 ELSE calendar_month + 3 END)) AS period_start,
            CASE WHEN calendar_month >= 10 THEN calendar_month - 9 ELSE calendar_month + 3 END AS fiscal_month,
            CASE WHEN calendar_month >= 10 THEN EXTRACT(YEAR FROM period_start)::integer + 1 ELSE EXTRACT(YEAR FROM period_start)::integer END AS fiscal_year,
            SUM(hr.work_injury_event_cnt) + SUM(hr.work_illness_event_cnt) AS numerator,
            SUM(hr.work_hours) AS denominator,
            ROUND((SUM(hr.work_injury_event_cnt) + SUM(hr.work_illness_event_cnt)) * 1000000 / NULLIF(SUM(hr.work_hours), 0), 2) AS value
          FROM (
            SELECT
              e.emp_id AS staff_key,
              DATE_TRUNC('month', months.work_month)::date AS period_start,
              EXTRACT(MONTH FROM months.work_month)::integer AS calendar_month,
              (SELECT COUNT(*)
                FROM emp_work_sick es
                JOIN emp_work_sick_type st ON st.emp_work_sick_type_id = es.emp_work_sick_type_id
                WHERE es.emp_id = e.emp_id
                  AND es.emp_work_sick_sdatetime >= months.work_month
                  AND es.emp_work_sick_sdatetime < months.work_month + INTERVAL '1 month'
                  AND (st.emp_work_sick_type_name ILIKE U&'%\0E2D\0E31\0E19\0E15\0E23\0E32\0E22%' OR st.emp_work_sick_type_name ILIKE U&'%\0E1A\0E32\0E14\0E40\0E08\0E47\0E1A%' OR st.emp_work_sick_type_name ILIKE U&'%\0E2D\0E38\0E1A\0E31\0E15\0E34\0E40\0E2B\0E15\0E38%')) AS work_injury_event_cnt,
              (SELECT COUNT(*)
                FROM emp_work_sick es
                JOIN emp_work_sick_type st ON st.emp_work_sick_type_id = es.emp_work_sick_type_id
                WHERE es.emp_id = e.emp_id
                  AND es.emp_work_sick_sdatetime >= months.work_month
                  AND es.emp_work_sick_sdatetime < months.work_month + INTERVAL '1 month'
                  AND (st.emp_work_sick_type_name ILIKE U&'%\0E40\0E08\0E47\0E1A\0E1B\0E48\0E27\0E22%' OR st.emp_work_sick_type_name ILIKE U&'%\0E1B\0E27\0E14\0E2B\0E25\0E31\0E07%' OR st.emp_work_sick_type_name ILIKE U&'%\0E40\0E04\0E23\0E35\0E22\0E14%' OR st.emp_work_sick_type_name ILIKE U&'%\0E42\0E23\0E04\0E08\0E32\0E01\0E01\0E32\0E23\0E17\0E33\0E07\0E32\0E19%')) AS work_illness_event_cnt,
              ((SELECT COUNT(*)
                FROM emp_work_schedule wsc
                LEFT JOIN emp_work_status wst ON wst.emp_work_status_id = wsc.emp_work_status_id
                WHERE wsc.emp_id = e.emp_id
                  AND wsc.emp_work_schedule_workdate >= months.work_month
                  AND wsc.emp_work_schedule_workdate < months.work_month + INTERVAL '1 month'
                  AND COALESCE(wst.emp_work_status_name, '') NOT ILIKE U&'%\0E25\0E32%'
                  AND COALESCE(wst.emp_work_status_name, '') NOT ILIKE U&'%\0E2B\0E22\0E38\0E14%'
              ) * 8) AS work_hours,
              (((COALESCE(pm.emp_position_main_name, '') ILIKE U&'%\0E41\0E1E\0E17\0E22\0E4C%' AND COALESCE(pm.emp_position_main_name, '') NOT ILIKE U&'%\0E40\0E17\0E04\0E19\0E34\0E04\0E01\0E32\0E23\0E41\0E1E\0E17\0E22\0E4C%' AND COALESCE(pm.emp_position_main_name, '') NOT ILIKE U&'%\0E1C\0E39\0E49\0E0A\0E48\0E27\0E22\0E41\0E1E\0E17\0E22\0E4C%' AND COALESCE(pm.emp_position_main_name, '') NOT ILIKE U&'%\0E41\0E1E\0E17\0E22\0E4C\0E41\0E1C\0E19%') OR (COALESCE(pm.emp_position_main_name, '') ILIKE U&'%\0E1E\0E22\0E32\0E1A\0E32\0E25\0E27\0E34\0E0A\0E32\0E0A\0E35\0E1E%' OR (COALESCE(pm.emp_position_main_name, '') ILIKE U&'%\0E1E\0E22\0E32\0E1A\0E32\0E25%' AND COALESCE(pm.emp_position_main_name, '') NOT ILIKE U&'%\0E1C\0E39\0E49\0E0A\0E48\0E27\0E22%' AND COALESCE(pm.emp_position_main_name, '') NOT ILIKE U&'%\0E1E\0E19\0E31\0E01\0E07\0E32\0E19%')) OR ((NOT (COALESCE(pm.emp_position_main_name, '') ILIKE U&'%\0E41\0E1E\0E17\0E22\0E4C%' AND COALESCE(pm.emp_position_main_name, '') NOT ILIKE U&'%\0E40\0E17\0E04\0E19\0E34\0E04\0E01\0E32\0E23\0E41\0E1E\0E17\0E22\0E4C%' AND COALESCE(pm.emp_position_main_name, '') NOT ILIKE U&'%\0E1C\0E39\0E49\0E0A\0E48\0E27\0E22\0E41\0E1E\0E17\0E22\0E4C%' AND COALESCE(pm.emp_position_main_name, '') NOT ILIKE U&'%\0E41\0E1E\0E17\0E22\0E4C\0E41\0E1C\0E19%')) AND (NOT (COALESCE(pm.emp_position_main_name, '') ILIKE U&'%\0E1E\0E22\0E32\0E1A\0E32\0E25\0E27\0E34\0E0A\0E32\0E0A\0E35\0E1E%' OR (COALESCE(pm.emp_position_main_name, '') ILIKE U&'%\0E1E\0E22\0E32\0E1A\0E32\0E25%' AND COALESCE(pm.emp_position_main_name, '') NOT ILIKE U&'%\0E1C\0E39\0E49\0E0A\0E48\0E27\0E22%' AND COALESCE(pm.emp_position_main_name, '') NOT ILIKE U&'%\0E1E\0E19\0E31\0E01\0E07\0E32\0E19%'))) AND (COALESCE(pm.emp_position_main_name, '') ILIKE ANY (ARRAY[U&'%\0E1C\0E14\0E38\0E07\0E04\0E23\0E23\0E20\0E4C%', U&'%\0E40\0E20\0E2A\0E31\0E0A%', U&'%\0E1C\0E39\0E49\0E0A\0E48\0E27\0E22\0E41\0E1E\0E17\0E22\0E4C%', U&'%\0E2D\0E32\0E0A\0E35\0E27\0E2D\0E19\0E32\0E21\0E31\0E22%', U&'%\0E2A\0E34\0E48\0E07\0E41\0E27\0E14\0E25\0E49\0E2D\0E21%', U&'%\0E01\0E32\0E22\0E20\0E32\0E1E%', U&'%\0E42\0E20\0E0A\0E19\0E32%', U&'%\0E2A\0E37\0E48\0E2D\0E04\0E27\0E32\0E21\0E2B\0E21\0E32\0E22%', U&'%\0E17\0E31\0E28\0E19\0E21\0E32\0E15\0E23%', U&'%\0E2D\0E32\0E0A\0E35\0E27\0E1A\0E33\0E1A\0E31\0E14%', U&'%\0E01\0E34\0E08\0E01\0E23\0E23\0E21\0E1A\0E33\0E1A\0E31\0E14%', U&'%\0E40\0E17\0E04\0E19\0E34\0E04\0E01\0E32\0E23\0E41\0E1E\0E17\0E22\0E4C%', U&'%\0E40\0E17\0E04\0E19\0E34\0E04\0E1E\0E22\0E32\0E18\0E34%', U&'%\0E1E\0E22\0E32\0E18\0E34%', U&'%\0E1C\0E39\0E49\0E0A\0E48\0E27\0E22\0E40\0E20\0E2A\0E31\0E0A%', U&'%\0E2D\0E38\0E1B\0E01\0E23\0E13\0E4C\0E01\0E32\0E23\0E41\0E1E\0E17\0E22\0E4C\0E40\0E17\0E35\0E22\0E21%', U&'%\0E1E\0E19\0E31\0E01\0E07\0E32\0E19\0E01\0E32\0E23\0E1E\0E22\0E32\0E1A\0E32\0E25%', U&'%\0E1C\0E39\0E49\0E0A\0E48\0E27\0E22\0E17\0E31\0E19\0E15%', U&'%\0E17\0E31\0E19\0E15\0E20\0E34\0E1A\0E32\0E25%', U&'%\0E40\0E27\0E0A\0E23\0E30\0E40\0E1A\0E35\0E22\0E19%', U&'%\0E2A\0E38\0E02\0E20\0E32\0E1E\0E0A\0E38\0E21\0E0A\0E19%', U&'%\0E1B\0E23\0E30\0E01\0E2D\0E1A\0E41\0E27\0E48\0E19%', U&'%\0E1C\0E39\0E49\0E0A\0E48\0E27\0E22\0E19\0E31\0E01\0E01\0E32\0E22\0E20\0E32\0E1E%', U&'%\0E1C\0E39\0E49\0E15\0E23\0E27\0E08\0E2A\0E2D\0E1A%', U&'%\0E23\0E16\0E1E\0E22\0E32\0E1A\0E32\0E25%', U&'%\0E08\0E48\0E32\0E22\0E01\0E25\0E32\0E07%', U&'%\0E40\0E27\0E0A\0E20\0E31\0E13\0E11\0E4C\0E01\0E25\0E32\0E07%', U&'%\0E41\0E1E\0E17\0E22\0E4C\0E41\0E1C\0E19%']))))) AS is_direct_contact
            FROM emp e
            LEFT JOIN emp_position_main pm ON pm.emp_position_main_id = e.emp_position_main_id
            JOIN GENERATE_SERIES(
              DATE_TRUNC('month', GREATEST(COALESCE(e.emp_work_begindate, (SELECT fy_start FROM thip_params)), (SELECT fy_start FROM thip_params))),
              DATE_TRUNC('month', LEAST(COALESCE(e.emp_resign_enddate, (SELECT fy_end FROM thip_params)), (SELECT fy_end FROM thip_params)) - INTERVAL '1 day'),
              INTERVAL '1 month'
            ) AS months(work_month) ON TRUE
          ) hr
          WHERE hr.is_direct_contact
          GROUP BY 2, 3, 4
          ), expected_codes(indicator_code, fiscal_month, indicator_name_th, indicator_name_en) AS (
            VALUES
              ('SH0306', 1, U&'\0E2D\0E31\0E15\0E23\0E32\0E04\0E27\0E32\0E21\0E16\0E35\0E48\0E01\0E32\0E23\0E1A\0E32\0E14\0E40\0E08\0E47\0E1A\002F\0E40\0E08\0E47\0E1A\0E1B\0E48\0E27\0E22\0E02\0E2D\0E07\0E1A\0E38\0E04\0E25\0E32\0E01\0E23\0E17\0E35\0E48\0E40\0E01\0E35\0E48\0E22\0E27\0E40\0E19\0E37\0E48\0E2D\0E07\0E08\0E32\0E01\0E07\0E32\0E19\0020\0E02\0E2D\0E07\0E1A\0E38\0E04\0E25\0E32\0E01\0E23\0E01\0E25\0E38\0E48\0E21\0020\0E2A\0E31\0E21\0E1C\0E31\0E2A\0E1C\0E39\0E49\0E1B\0E48\0E27\0E22\0E42\0E14\0E22\0E15\0E23\0E07', 'HRH: Injury (illnesses) frequency rate (IFR) of direct contact with patients'), ('SH0306', 2, U&'\0E2D\0E31\0E15\0E23\0E32\0E04\0E27\0E32\0E21\0E16\0E35\0E48\0E01\0E32\0E23\0E1A\0E32\0E14\0E40\0E08\0E47\0E1A\002F\0E40\0E08\0E47\0E1A\0E1B\0E48\0E27\0E22\0E02\0E2D\0E07\0E1A\0E38\0E04\0E25\0E32\0E01\0E23\0E17\0E35\0E48\0E40\0E01\0E35\0E48\0E22\0E27\0E40\0E19\0E37\0E48\0E2D\0E07\0E08\0E32\0E01\0E07\0E32\0E19\0020\0E02\0E2D\0E07\0E1A\0E38\0E04\0E25\0E32\0E01\0E23\0E01\0E25\0E38\0E48\0E21\0020\0E2A\0E31\0E21\0E1C\0E31\0E2A\0E1C\0E39\0E49\0E1B\0E48\0E27\0E22\0E42\0E14\0E22\0E15\0E23\0E07', 'HRH: Injury (illnesses) frequency rate (IFR) of direct contact with patients'), ('SH0306', 3, U&'\0E2D\0E31\0E15\0E23\0E32\0E04\0E27\0E32\0E21\0E16\0E35\0E48\0E01\0E32\0E23\0E1A\0E32\0E14\0E40\0E08\0E47\0E1A\002F\0E40\0E08\0E47\0E1A\0E1B\0E48\0E27\0E22\0E02\0E2D\0E07\0E1A\0E38\0E04\0E25\0E32\0E01\0E23\0E17\0E35\0E48\0E40\0E01\0E35\0E48\0E22\0E27\0E40\0E19\0E37\0E48\0E2D\0E07\0E08\0E32\0E01\0E07\0E32\0E19\0020\0E02\0E2D\0E07\0E1A\0E38\0E04\0E25\0E32\0E01\0E23\0E01\0E25\0E38\0E48\0E21\0020\0E2A\0E31\0E21\0E1C\0E31\0E2A\0E1C\0E39\0E49\0E1B\0E48\0E27\0E22\0E42\0E14\0E22\0E15\0E23\0E07', 'HRH: Injury (illnesses) frequency rate (IFR) of direct contact with patients'), ('SH0306', 4, U&'\0E2D\0E31\0E15\0E23\0E32\0E04\0E27\0E32\0E21\0E16\0E35\0E48\0E01\0E32\0E23\0E1A\0E32\0E14\0E40\0E08\0E47\0E1A\002F\0E40\0E08\0E47\0E1A\0E1B\0E48\0E27\0E22\0E02\0E2D\0E07\0E1A\0E38\0E04\0E25\0E32\0E01\0E23\0E17\0E35\0E48\0E40\0E01\0E35\0E48\0E22\0E27\0E40\0E19\0E37\0E48\0E2D\0E07\0E08\0E32\0E01\0E07\0E32\0E19\0020\0E02\0E2D\0E07\0E1A\0E38\0E04\0E25\0E32\0E01\0E23\0E01\0E25\0E38\0E48\0E21\0020\0E2A\0E31\0E21\0E1C\0E31\0E2A\0E1C\0E39\0E49\0E1B\0E48\0E27\0E22\0E42\0E14\0E22\0E15\0E23\0E07', 'HRH: Injury (illnesses) frequency rate (IFR) of direct contact with patients'), ('SH0306', 5, U&'\0E2D\0E31\0E15\0E23\0E32\0E04\0E27\0E32\0E21\0E16\0E35\0E48\0E01\0E32\0E23\0E1A\0E32\0E14\0E40\0E08\0E47\0E1A\002F\0E40\0E08\0E47\0E1A\0E1B\0E48\0E27\0E22\0E02\0E2D\0E07\0E1A\0E38\0E04\0E25\0E32\0E01\0E23\0E17\0E35\0E48\0E40\0E01\0E35\0E48\0E22\0E27\0E40\0E19\0E37\0E48\0E2D\0E07\0E08\0E32\0E01\0E07\0E32\0E19\0020\0E02\0E2D\0E07\0E1A\0E38\0E04\0E25\0E32\0E01\0E23\0E01\0E25\0E38\0E48\0E21\0020\0E2A\0E31\0E21\0E1C\0E31\0E2A\0E1C\0E39\0E49\0E1B\0E48\0E27\0E22\0E42\0E14\0E22\0E15\0E23\0E07', 'HRH: Injury (illnesses) frequency rate (IFR) of direct contact with patients'), ('SH0306', 6, U&'\0E2D\0E31\0E15\0E23\0E32\0E04\0E27\0E32\0E21\0E16\0E35\0E48\0E01\0E32\0E23\0E1A\0E32\0E14\0E40\0E08\0E47\0E1A\002F\0E40\0E08\0E47\0E1A\0E1B\0E48\0E27\0E22\0E02\0E2D\0E07\0E1A\0E38\0E04\0E25\0E32\0E01\0E23\0E17\0E35\0E48\0E40\0E01\0E35\0E48\0E22\0E27\0E40\0E19\0E37\0E48\0E2D\0E07\0E08\0E32\0E01\0E07\0E32\0E19\0020\0E02\0E2D\0E07\0E1A\0E38\0E04\0E25\0E32\0E01\0E23\0E01\0E25\0E38\0E48\0E21\0020\0E2A\0E31\0E21\0E1C\0E31\0E2A\0E1C\0E39\0E49\0E1B\0E48\0E27\0E22\0E42\0E14\0E22\0E15\0E23\0E07', 'HRH: Injury (illnesses) frequency rate (IFR) of direct contact with patients'), ('SH0306', 7, U&'\0E2D\0E31\0E15\0E23\0E32\0E04\0E27\0E32\0E21\0E16\0E35\0E48\0E01\0E32\0E23\0E1A\0E32\0E14\0E40\0E08\0E47\0E1A\002F\0E40\0E08\0E47\0E1A\0E1B\0E48\0E27\0E22\0E02\0E2D\0E07\0E1A\0E38\0E04\0E25\0E32\0E01\0E23\0E17\0E35\0E48\0E40\0E01\0E35\0E48\0E22\0E27\0E40\0E19\0E37\0E48\0E2D\0E07\0E08\0E32\0E01\0E07\0E32\0E19\0020\0E02\0E2D\0E07\0E1A\0E38\0E04\0E25\0E32\0E01\0E23\0E01\0E25\0E38\0E48\0E21\0020\0E2A\0E31\0E21\0E1C\0E31\0E