            JOIN emp_work_sick_type st ON st.emp_work_sick_type_id = es.emp_work_sick_type_id
            WHERE es.emp_id = e.emp_id
              AND es.emp_work_sick_sdatetime >= months.work_month
              AND es.emp_work_sick_sdatetime < months.work_month + INTERVAL '1 month'
              AND (st.emp_work_sick_type_name ILIKE U&'%\0E2D\0E31\0E19\0E15\0E23\0E32\0E22%' OR st.emp_work_sick_type_name ILIKE U&'%\0E1A\0E32\0E14\0E40\0E08\0E47\0E1A%' OR st.emp_work_sick_type_name ILIKE U&'%\0E2D\0E38\0E1A\0E31\0E15\0E34\0E40\0E2B\0E15\0E38%')) AS work_injury_event_cnt,
          (SELECT COUNT(*)
            FROM emp_work_sick es
            JOIN emp_work_sick_type st ON st.emp_work_sick_type_id = es.emp_work_sick_type_id
            WHERE es.emp_id = e.emp_id
              AND es.emp_work_sick_sdatetime >= months.work_month
              AND es.emp_work_sick_sdatetime < months.work_month + INTERVAL '1 month'
              AND (st.emp_work_sick_type_name ILIKE U&'%\0E40\0E08\0E47\0E1A\0E1B\0E48\0E27\0E22%' OR st.emp_work_sick_type_name ILIKE U&'%\0E1B\0E27\0E14\0E2B\0E25\0E31\0E07%' OR st.emp_work_sick_type_name ILIKE U&'%\0E40\0E04\0E23\0E35\0E22\0E14%' OR st.emp_work_sick_type_name ILIKE U&'%\0E42\0E23\0E04\0E08\0E32\0E01\0E01\0E32\0E23\0E17\0E33\0E07\0E32\0E19%')) AS work_illness_event_cnt,
          ((SELECT COUNT(*)
            FROM emp_work_schedule wsc
            LEFT JOIN emp_work_status wst ON wst.emp_work_status_id = wsc.emp_work_status_id
            WHERE wsc.emp_id = e.emp_id
              AND wsc.emp_work_schedule_workdate >= months.work_month
              AND wsc.emp_work_schedule_workdate < months.work_month + INTERVAL '1 month'
              AND COALESCE(wst.emp_work_status_name, '') NOT ILIKE U&'%\0E25\0E32%'
              AND COALESCE(wst.emp_work_status_name, '') NOT ILIKE U&'%\0E2B\0E22\0E38\0E14%'
          ) * 8) AS work_hours
        FROM emp e
        LEFT JOIN emp_position_main pm ON pm.emp_position_main_id = e.emp_position_main_id
        JOIN GENERATE_SERIES(
          DATE_TRUNC('month', GREATEST(COALESCE(e.emp_work_begindate, (SELECT fy_start FROM thip_params)), (SELECT fy_start FROM thip_params))),
          DATE_TRUNC('month', LEAST(COALESCE(e.emp_resign_enddate, (SELECT fy_end FROM thip_params)), (SELECT fy_end FROM thip_params)) - INTERVAL '1 day'),
          INTERVAL '1 month'
        ) AS months(work_month) ON TRUE
      ) hr
      WHERE TRUE
      GROUP BY 2, 3, 4

  UNION ALL

      SELECT
        'SH0302' AS indicator_code,
        DATE_TRUNC('month', period_start)::date - MAKE_INTERVAL(months => (CASE WHEN calendar_month >= 10 THEN calendar_month - 9 ELSE calendar_month + 3 END) - (CASE WHEN calendar_month >= 10 THEN calendar_month - 9 ELSE calendar_month + 3 END)) AS period_start,
        CASE WHEN calendar_month >= 10 THEN calendar_month - 9 ELSE calendar_month + 3 END AS fiscal_month,
        CASE WHEN calendar_month >= 10 THEN EXTRACT(YEAR FROM period_start)::integer + 1 ELSE EXTRACT(YEAR FROM period_start)::integer END AS fiscal_year,
        SUM(hr.injury_lost_days) AS numerator,
        SUM(hr.work_hours) AS denominator,
        ROUND((SUM(hr.injury_lost_days)) * 1000000 / NULLIF(SUM(hr.work_hours), 0), 2) AS value
      FROM (
        SELECT
          e.emp_id AS staff_key,
          DATE_TRUNC('month', months.work_month)::date AS period_start,
          EXTRACT(MONTH FROM months.work_month)::integer AS calendar_month,
          (SELECT COALESCE(SUM(es.emp_work_sick_countday), 0)
            FROM emp_work_sick es
            JOIN emp_work_sick_type st ON st.emp_work_sick_type_id = es.emp_work_sick_type_id
            WHERE es.emp_id = e.emp_id
              AND es.emp_work_sick_sdatetime >= months.work_month
              AND es.emp_work_sick_sdatetime < months.work_month + INTERVAL '1 month'
              AND (st.emp_work_sick_type_name ILIKE U&'%\0E2D\0E31\0E19\0E15\0E23\0E32\0E22%' OR st.emp_work_sick_type_name ILIKE U&'%\0E1A\0E32\0E14\0E40\0E08\0E47\0E1A%' OR st.emp_work_sick_type_name ILIKE U&'%\0E2D\0E38\0E1A\0E31\0E15\0E34\0E40\0E2B\0E15\0E38%')) AS injury_lost_days,
          ((SELECT COUNT(*)
            FROM emp_work_schedule wsc
            LEFT JOIN emp_work_status wst ON wst.emp_work_status_id = wsc.emp_work_status_id
            WHERE wsc.emp_id = e.emp_id
              AND wsc.emp_work_schedule_workdate >= months.work_month
              AND wsc.emp_work_schedule_workdate < months.work_month + INTERVAL '1 month'
              AND COALESCE(wst.emp_work_status_name, '') NOT ILIKE U&'%\0E25\0E32%'
              AND COALESCE(wst.emp_work_status_name, '') NOT ILIKE U&'%\0E2B\0E22\0E38\0E14%'
          ) * 8) AS work_hours,
          (((COALESCE(pm.emp_position_main_name, '') ILIKE U&'%\0E41\0E1E\0E17\0E22\0E4C%' AND COALESCE(pm.emp_position_main_name, '') NOT ILIKE U&'%\0E40\0E17\0E04\0E19\0E34\0E04\0E01\0E32\0E23\0E41\0E1E\0E17\0E22\0E4C%' AND COALESCE(pm.emp_position_main_name, '') NOT ILIKE U&'%\0E1C\0E39\0E49\0E0A\0E48\0E27\0E22\0E41\0E1E\0E17\0E22\0E4C%' AND COALESCE(pm.emp_position_main_name, '') NOT ILIKE U&'%\0E41\0E1E\0E17\0E22\0E4C\0E41\0E1C\0E19%') OR (COALESCE(pm.emp_position_main_name, '') ILIKE U&'%\0E1E\0E22\0E32\0E1A\0E32\0E25\0E27\0E34\0E0A\0E32\0E0A\0E35\0E1E%' OR (COALESCE(pm.emp_position_main_name, '') ILIKE U&'%\0E1E\0E22\0E32\0E1A\0E32\0E25%' AND COALESCE(pm.emp_position_main_name, '') NOT ILIKE U&'%\0E1C\0E39\0E49\0E0A\0E48\0E27\0E22%' AND COALESCE(pm.emp_position_main_name, '') NOT ILIKE U&'%\0E1E\0E19\0E31\0E01\0E07\0E32\0E19%')) OR ((NOT (COALESCE(pm.emp_position_main_name, '') ILIKE U&'%\0E41\0E1E\0E17\0E22\0E4C%' AND COALESCE(pm.emp_position_main_name, '') NOT ILIKE U&'%\0E40\0E17\0E04\0E19\0E34\0E04\0E01\0E32\0E23\0E41\0E1E\0E17\0E22\0E4C%' AND COALESCE(pm.emp_position_main_name, '') NOT ILIKE U&'%\0E1C\0E39\0E49\0E0A\0E48\0E27\0E22\0E41\0E1E\0E17\0E22\0E4C%' AND COALESCE(pm.emp_position_main_name, '') NOT ILIKE U&'%\0E41\0E1E\0E17\0E22\0E4C\0E41\0E1C\0E19%')) AND (NOT (COALESCE(pm.emp_position_main_name, '') ILIKE U&'%\0E1E\0E22\0E32\0E1A\0E32\0E25\0E27\0E34\0E0A\0E32\0E0A\0E35\0E1E%' OR (COALESCE(pm.emp_position_main_name, '') ILIKE U&'%\0E1E\0E22\0E32\0E1A\0E32\0E25%' AND COALESCE(pm.emp_position_main_name, '') NOT ILIKE U&'%\0E1C\0E39\0E49\0E0A\0E48\0E27\0E22%' AND COALESCE(pm.emp_position_main_name, '') NOT ILIKE U&'%\0E1E\0E19\0E31\0E01\0E07\0E32\0E19%'))) AND (COALESCE(pm.emp_position_main_name, '') ILIKE ANY (ARRAY[U&'%\0E1C\0E14\0E38\0E07\0E04\0E23\0E23\0E20\0E4C%', U&'%\0E40\0E20\0E2A\0E31\0E0A%', U&'%\0E1C\0E39\0E49\0E0A\0E48\0E27\0E22\0E41\0E1E\0E17\0E22\0E4C%', U&'%\0E2D\0E32\0E0A\0E35\0E27\0E2D\0E19\0E32\0E21\0E31\0E22%', U&'%\0E2A\0E34\0E48\0E07\0E41\0E27\0E14\0E25\0E49\0E2D\0E21%', U&'%\0E01\0E32\0E22\0E20\0E32\0E1E%', U&'%\0E42\0E20\0E0A\0E19\0E32%', U&'%\0E2A\0E37\0E48\0E2D\0E04\0E27\0E32\0E21\0E2B\0E21\0E32\0E22%', U&'%\0E17\0E31\0E28\0E19\0E21\0E32\0E15\0E23%', U&'%\0E2D\0E32\0E0A\0E35\0E27\0E1A\0E33\0E1A\0E31\0E14%', U&'%\0E01\0E34\0E08\0E01\0E23\0E23\0E21\0E1A\0E33\0E1A\0E31\0E14%', U&'%\0E40\0E17\0E04\0E19\0E34\0E04\0E01\0E32\0E23\0E41\0E1E\0E17\0E22\0E4C%', U&'%\0E40\0E17\0E04\0E19\0E34\0E04\0E1E\0E22\0E32\0E18\0E34%', U&'%\0E1E\0E22\0E32\0E18\0E34%', U&'%\0E1C\0E39\0E49\0E0A\0E48\0E27\0E22\0E40\0E20\0E2A\0E31\0E0A%', U&'%\0E2D\0E38\0E1B\0E01\0E23\0E13\0E4C\0E01\0E32\0E23\0E41\0E1E\0E17\0E22\0E4C\0E40\0E17\0E35\0E22\0E21%', U&'%\0E1E\0E19\0E31\0E01\0E07\0E32\0E19\0E01\0E32\0E23\0E1E\0E22\0E32\0E1A\0E32\0E25%', U&'%\0E1C\0E39\0E49\0E0A\0E48\0E27\0E22\0E17\0E31\0E19\0E15%', U&'%\0E17\0E31\0E19\0E15\0E20\0E34\0E1A\0E32\0E25%', U&'%\0E40\0E27\0E0A\0E23\0E30\0E40\0E1A\0E35\0E22\0E19%', U&'%\0E2A\0E38\0E02\0E20\0E32\0E1E\0E0A\0E38\0E21\0E0A\0E19%', U&'%\0E1B\0E23\0E30\0E01\0E2D\0E1A\0E41\0E27\0E48\0E19%', U&'%\0E1C\0E39\0E49\0E0A\0E48\0E27\0E22\0E19\0E31\0E01\0E01\0E32\0E22\0E20\0E32\0E1E%', U&'%\0E1C\0E39\0E49\0E15\0E23\0E27\0E08\0E2A\0E2D\0E1A%', U&'%\0E23\0E16\0E1E\0E22\0E32\0E1A\0E32\0E25%', U&'%\0E08\0E48\0E32\0E22\0E01\0E25\0E32\0E07%', U&'%\0E40\0E27\0E0A\0E20\0E31\0E13\0E11\0E4C\0E01\0E25\0E32\0E07%', U&'%\0E41\0E1E\0E17\0E22\0E4C\0E41\0E1C\0E19%']))))) AS is_direct_contact
        FROM emp e
        LEFT JOIN emp_position_main pm ON pm.emp_position_main_id = e.emp_position_main_id
        JOIN GENERATE_SERIES(
          DATE_TRUNC('month', GREATEST(COALESCE(e.emp_work_begindate, (SELECT fy_start FROM thip_params)), (SELECT fy_start FROM thip_params))),
          DATE_TRUNC('month', LEAST(COALESCE(e.emp_resign_enddate, (SELECT fy_end FROM thip_params)), (SELECT fy_end FROM thip_params)) - INTERVAL '1 day'),
