    ('SS0102', 'S', 'percent', 'higher-is-better', 'monthly', 'System', 'CSSD: Percent of exact medical equipment prepared for specific procedures', U&'\0E23\0E49\0E2D\0E22\0E25\0E30\0E01\0E32\0E23\0E08\0E31\0E14\0E2D\0E38\0E1B\0E01\0E23\0E13\0E4C\0E40\0E04\0E23\0E37\0E48\0E2D\0E07\0E21\0E37\0E2D\0E17\0E32\0E07\0E01\0E32\0E23\0E41\0E1E\0E17\0E22\0E4C \0E16\0E39\0E01\0E15\0E49\0E2D\0E07\0E04\0E23\0E1A\0E16\0E49\0E27\0E19', U&'\0E40\0E1B\0E47\0E19\0E01\0E32\0E23\0E1B\0E23\0E30\0E40\0E21\0E34\0E19\0E1B\0E23\0E30\0E2A\0E34\0E17\0E18\0E34\0E20\0E32\0E1E\0E02\0E2D\0E07\0E01\0E32\0E23\0E08\0E31\0E14\0E2D\0E38\0E1B\0E01\0E23\0E13\0E4C\0E40\0E04\0E23\0E37\0E48\0E2D\0E07\0E21\0E37\0E2D\0E17\0E32\0E07\0E01\0E32\0E23\0E41\0E1E\0E17\0E22\0E4C \0E15\0E32\0E21\0E21\0E32\0E15\0E23\0E10\0E32\0E19 \0E2B\0E23\0E37\0E2D\0E02\0E49\0E2D\0E15\0E01\0E25\0E07\0E17\0E35\0E48\0E01\0E33\0E2B\0E19\0E14\0E42\0E14\0E22\0E04\0E13\0E30\0E01\0E23\0E23\0E21\0E01\0E32\0E23\0E02\0E2D\0E07\0E42\0E23\0E07\0E1E\0E22\0E32\0E1A\0E32\0E25', '(a/b) x 100', 'a', 'b', ARRAY['supply_sterile', 'supply_sterile_item', 'operation_list', 'operation_detail']::text[], U&'\0E17\0E38\0E01\0E40\0E14\0E37\0E2D\0E19 (\0E23\0E32\0E22\0E40\0E14\0E37\0E2D\0E19)', U&'THIP KPI Dictionary 2025 - \0E2B\0E19\0E49\0E32 258', 'registered-2026.1', NULL, 'registered'),
    ('SS0103', 'S', 'percent', 'higher-is-better', 'monthly', 'System', 'CSSD: Percent of medical supplies which are accurately provided by the CSSD', U&'\0E23\0E49\0E2D\0E22\0E25\0E30\0E01\0E32\0E23\0E08\0E48\0E32\0E22\0E2D\0E38\0E1B\0E01\0E23\0E13\0E4C\0E40\0E04\0E23\0E37\0E48\0E2D\0E07\0E21\0E37\0E2D\0E17\0E32\0E07\0E01\0E32\0E23\0E41\0E1E\0E17\0E22\0E4C\0E43\0E2B\0E49\0E2B\0E19\0E48\0E27\0E22\0E07\0E32\0E19\0E16\0E39\0E01\0E15\0E49\0E2D\0E07', U&'\0E2D\0E31\0E15\0E23\0E32\0E01\0E32\0E23\0E08\0E48\0E32\0E22\0E2D\0E38\0E1B\0E01\0E23\0E13\0E4C\0E40\0E04\0E23\0E37\0E48\0E2D\0E07\0E21\0E37\0E2D\0E17\0E32\0E07\0E01\0E32\0E23\0E41\0E1E\0E17\0E22\0E4C\0E43\0E2B\0E49\0E2B\0E19\0E48\0E27\0E22\0E07\0E32\0E19\0E16\0E39\0E01\0E15\0E49\0E2D\0E07 \0E40\0E1B\0E47\0E19\0E01\0E32\0E23\0E1B\0E23\0E30\0E40\0E21\0E34\0E19 \0E1B\0E23\0E30\0E2A\0E34\0E17\0E18\0E34\0E20\0E32\0E1E\0E02\0E2D\0E07\0E01\0E32\0E23\0E08\0E48\0E32\0E22\0E2D\0E38\0E1B\0E01\0E23\0E13\0E4C\0E40\0E04\0E23\0E37\0E48\0E2D\0E07\0E21\0E37\0E2D\0E17\0E32\0E07\0E01\0E32\0E23\0E41\0E1E\0E17\0E22\0E4C\0E16\0E39\0E01\0E15\0E49\0E2D\0E07 \0E04\0E23\0E1A\0E16\0E49\0E27\0E19 (\0E04\0E27\0E32\0E21\0E16\0E39\0E01\0E15\0E49\0E2D\0E07 \0E04\0E23\0E1A\0E16\0E49\0E27\0E19 \0E17\0E31\0E19\0E40\0E27\0E25\0E32) \0E02\0E2D\0E07\0E2B\0E19\0E48\0E27\0E22 CSSD', '(a/b) x 100', 'a', 'b', ARRAY['supply_sterile', 'supply_sterile_item', 'operation_list', 'operation_detail']::text[], U&'\0E17\0E38\0E01\0E40\0E14\0E37\0E2D\0E19 (\0E23\0E32\0E22\0E40\0E14\0E37\0E2D\0E19)', U&'THIP KPI Dictionary 2025 - \0E2B\0E19\0E49\0E32 259', 'registered-2026.1', NULL, 'registered')
),
fiscal_periods AS (
  SELECT
    generated.period_start::date AS period_start,
    CASE WHEN EXTRACT(MONTH FROM generated.period_start) >= 10 THEN EXTRACT(MONTH FROM generated.period_start)::integer - 9 ELSE EXTRACT(MONTH FROM generated.period_start)::integer + 3 END AS fiscal_month,
    CASE WHEN EXTRACT(MONTH FROM generated.period_start) >= 10 THEN EXTRACT(YEAR FROM generated.period_start)::integer + 1 ELSE EXTRACT(YEAR FROM generated.period_start)::integer END AS fiscal_year
  FROM generate_series(
    CAST((SELECT fy_start FROM thip_params) AS date),
    CAST((SELECT fy_end FROM thip_params) AS date) - INTERVAL '1 month',
    INTERVAL '1 month'
  ) AS generated(period_start)
),
-- Registered HOSxP codes get a complete fact grid: a period whose registered
-- query ran and found an empty cohort is a measured zero cohort (0 facts, NULL
-- value), never a fabricated rate. External-fact codes (hospital-loaded
-- staging) and pending tiers stay out of the grid, so a missing source row
-- remains an explicit unavailable row in the outer SELECT instead of a zero.
facts AS (
  SELECT
    e.indicator_code,
    fp.period_start,
    fp.fiscal_year,
    fp.fiscal_month,
    COALESCE(fe.numerator, 0) AS numerator,
    CASE WHEN m.unit = 'count' THEN fe.denominator ELSE COALESCE(fe.denominator, 0) END AS denominator,
    fe.value
  FROM expected e
  JOIN metadata m
    ON m.indicator_code = e.indicator_code
   AND m.tier = 'registered'
   AND NOT (m.indicator_code = ANY(ARRAY['CG0103', 'CG0104', 'DE1301', 'DE1302', 'DE1303', 'DE1304', 'DE1305', 'DE1306', 'DE1601', 'DM0103', 'DM0203', 'DM0401', 'DM0402', 'DS0101', 'DS0201', 'DS0301', 'SC0101', 'SC0102', 'SC0103', 'SC0104', 'SC0105', 'SC0106', 'SF0101', 'SF0102', 'SF0103', 'SF0104', 'SF0105', 'SF0106', 'SG0104', 'SH0201', 'SH0202', 'SH0203', 'SH0204', 'SH0205', 'SH0206', 'SH0207', 'SH0208', 'SH0209', 'SH0210', 'SH0211', 'SH0212', 'SH0213', 'SH0214', 'SH0215', 'SH0216', 'SI0101', 'SI0102', 'SI0103', 'SI0201', 'SI0202', 'SI0203', 'SI0301', 'SI0302', 'SI0303', 'SS0101']::text[]))
  JOIN fiscal_periods fp
    ON fp.fiscal_month = e.fiscal_month
  LEFT JOIN fact_events fe
    ON fe.indicator_code = e.indicator_code
   AND fe.period_start = fp.period_start
   AND fe.fiscal_month = fp.fiscal_month
   AND fe.fiscal_year = fp.fiscal_year
)
SELECT
  m.indicator_code,
  fp.period_start,
  fp.fiscal_year,
  fp.fiscal_month,
  CASE WHEN m.tier = 'registered' THEN f.numerator ELSE NULL END AS numerator,
  CASE WHEN m.tier = 'registered' THEN f.denominator ELSE NULL END AS denominator,
  CASE WHEN m.tier = 'registered' THEN f.value ELSE NULL END AS value,
  NULL::numeric AS target,
  m.target_scope,
  NULL::numeric AS percentile,
  m.indicator_group,
  m.unit,
  m.direction,
  m.category,
  m.title,
  m.title_th,
  m.definition,
  m.formula,
  m.numerator_label,
  m.denominator_label,
  m.source_tables,
  m.frequency,
  m.reference,
  m.rule_version,
  m.pending_reason,
  m.tier,
  NOW() AS refreshed_at
FROM metadata m
JOIN expected e
  ON e.indicator_code = m.indicator_code
JOIN fiscal_periods fp
  ON fp.fiscal_month = e.fiscal_month
LEFT JOIN facts f
  ON f.indicator_code = m.indicator_code
 AND f.period_start = fp.period_start
 AND f.fiscal_month = fp.fiscal_month
 AND f.fiscal_year = fp.fiscal_year
ORDER BY m.indicator_code, fp.period_start;

